  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  def solve(): Unit = {
    val K = ns()
    val N = K.length
    val M = ni()

    val dp = Array.ofDim[Long](N + 1, 2, M)
    dp(0)(0)(0) = 1
    dp(0)(1)(0) = 1

    REP(N, 1) { i =>
      REP(2) { less =>
        val digit = K(N - i) - '0'
        val len = if (less == 1) 10 else digit + 1
        REP(len) { d =>
          REP(M) { m =>
            val nextLess = less | (if (d < digit) 1 else 0)
//            debug(s"$i $less $nextLess m:$m j:$d")
            dp(i)(less)(m) += dp(i - 1)(nextLess)((M * 10 + m - d) % M)
          }
        }

        // まとめてやる
        REP(M) { m =>
          dp(i)(less)(m) %= MOD
        }

        DEBUG {
          debug(s"i:$i less:$less")
          debug(dp(i)(less))
        }
      }
    }

    val ans = dp(N)(0)(0) - 1 // 0を引く
    out.println(ans)
  }

