int getAns(int level,int tlo,int thi,int rem){
    if(level>=L.size()){
        if(rem==0)return 1;
        return 0;
    }
    if(dp[level][tlo][thi][rem]==-1){
        int blo=0;
        int bhi=9;
        if(tlo){
            blo=L[level]-'0';
        }
        if(thi){
            bhi=R[level]-'0';
        }

        int ans=0;
        for(int i=blo;i<=bhi;i++){
            int ntlo=tlo;
            int nthi=thi;
            if(i>L[level]-'0'){
                ntlo=0;
            }
            if(i<R[level]-'0'){
                nthi=0;
            }

            ans+=getAns(level+1,ntlo,nthi,(rem+i)%D);
            ans%=mod;

        }
        dp[level][tlo][thi][rem]=ans;
    }
    return dp[level][tlo][thi][rem];
}

