    for (auto i=0; i<(int)k.size(); ++i)
        for (auto r=0; r<d; ++r)
            for (auto c=0; c<10; ++c)
                dyn[i+1][(r+c)%d] += dyn[i][r];

    auto prefr = 0;
    auto total = M(0);
