  for (int i = 1; i < l; i++)
  {
    for (int c = 0; c < 10; c++)
    {
      for (int crr = 0; crr < d; crr++)
      {
        int nxt = (crr + c) % d;
        add(dp[i][nxt], dp[i - 1][crr]);
      }
    }
  }

  int ans = 0;
  int res = 0;
  for (int i = 0; i < l; i++)
    {
    int c = n[i] - '0';
    while(c--){
      add(ans, dp[l - 1 - i][res]);
      res--;
      if (res < 0) {
        res += d;
      }
    }
  }
  if (res == 0) {
    add(ans, 1);
  }
  sub(ans, 1);
  cout << ans << '\n';
  return 0;
}

