	if (d == 0)return 0;
	if (dp[d][m][mn] != -1)return dp[d][m][mn];
	ll ret = 0;
	if (mn) {
		REP(i, 10) {
			(ret += solve(mn, d - 1, ((m - i)%D + D) % D)) %= MOD;
		}
	}
	else {
		ll t = a[d];
		ret += solve(mn, d - 1, ((m - t) % D + D) % D);
		REP(i, t) {
			(ret += solve(1, d - 1, ((m - i) % D + D) % D)) %= MOD;
		}
	}
//	cout << d << ' ' << m << ' ' << mn << ' ' << ret << endl;
	return dp[d][m][mn] = ret;
}


