    n = (ll)k.size();
    ll num = (k[0]-'0');
    ll ans = rec(1, num, 0);
    for(ll i = 0; i < num; i++){
        add_self(ans, rec(1, i, 1));
    }
    cout<<ans-1;
	return 0;
}

