int solve(int pos, int anygood, int modsum)
{
    if(pos == digits.size())
        return (modsum == 0);
    assert(pos < digits.size());
    if(dp[pos][anygood][modsum] == -1)
    {
        dp[pos][anygood][modsum] = 0;
        for(int i = 0; i < 10; i++)
