typedef long long ll;
const long long mod = 1000000007;
std::string k;
int d, n;
ll dp[1001][100][2];
// dp[dig][r][less]:
// 上位dig桁目まで見たとき、各桁の和のmod dがrになるような方法
// less(未満フラグ)は、k未満が確定しているか (1) kギリギリか (0)

ll rec(int dig, int r, int less){
	if(dig >= n) return (r == 0);
	if(dp[dig][r][less] >= 0) return dp[dig][r][less];

	int lim = (less ? 9 : k[dig] - '0'); //上限値
	int res = 0;
	// 各桁のごとにmodをとった総和を求める
	for(int i=0; i<=lim; i++){
		res += rec(dig+1, (i+r) % d, less | (i < lim));
		res %= mod;
	}
	return dp[dig][r][less] = res;
}

int main(){
	std::cin >> k >> d;
	n = k.size();
	for(int i=0; i<1001; i++){
		for(int j=0; j<100; j++){
			dp[i][j][0] = -1;
			dp[i][j][1] = -1;
		}
	}

	ll ans = rec(0, 0, 0);
	std::cout << (ans + mod - 1) % mod << std::endl;
	return 0;
}

#include <bits/stdc++.h>

const int N = 1e4+5, MOD = 1e9+7, D = 105;
char str[N];
int n, d, dp[N][2][D];

void add_self(int& a, int b, int mod) {
  //assert(a < mod);
  //assert(b < mod);

  a += b;
  if (a >= mod)
    a -= mod;
}

int add(int a, int b, int mod) {
  return (a + b) % mod;
}

int f(int pos, bool limited, int cur_sum) {
  if (pos >= n)
    return (cur_sum == 0);

  if (dp[pos][limited][cur_sum] != -1)
    return dp[pos][limited][cur_sum];

  int ans = 0;
  int max_digit = limited ? str[pos] : 9;

  for (int i = 0; i <= max_digit; i++) {
    if (i == max_digit && limited) {
      int tmp = f(pos + 1, 1, add(cur_sum, i, d));
      add_self(ans, tmp, MOD);
    } else {
      int tmp = f(pos + 1, 0, add(cur_sum, i, d));
      add_self(ans, tmp, MOD);
    }
  }

  return dp[pos][limited][cur_sum] = ans;
}

int32_t main() {
  scanf("%s%d", str, &d);

  n = strlen(str);
  assert(n < N);
  for (int i = 0; i < n; i++)
    str[i] -= '0';

  memset(dp, -1, sizeof dp);
  //assert(f(0, 1, 0) - 1 >= 0);
  printf("%d\n", f(0, 1, 0) - 1);
  return 0;
}

