  for (int i = 0; i < d; i++)
    for (int j = 0; j < 10; j++)
      dp[0][i][j] = 0;
  dp[0][0][0] = 1;

  for (int i = 0; i < d; i++)
    sdp[1][i] = 0;
  sdp[1][(s[0] - '0') % d] = 1;
  reverse(s.begin(), s.end());
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < d; j++) {
      for (int k = 0; k < 10; k++) {
        dp[i + 1][j][k] = 0;
        if (i == 0) {
          dp[i + 1][k % d][k] = 1;
          continue;
        }
        for (int l = 0; l < 10; l++) {
          dp[i + 1][j][k] += dp[i][(j - k + d) % d][l];
          dp[i + 1][j][k] %= P;
        }
      }
      if (i > 0) {
        sdp[i + 1][j] = sdp[i][(j - (s[i] - '0') + d) % d];
        for (int k = 0; k < s[i - 1] - '0'; k++) {
          sdp[i + 1][j] += dp[i][(j - (s[i] - '0') + d) % d][k];
          sdp[i + 1][j] %= P;
        }
      }
    }
  }
  long long ans = sdp[n][0];

  for (int i = 0; i < n; i++) {
    if (i == n - 1) {
      for (int j = 1; j < s[i] - '0'; j++) {
        ans += dp[i + 1][0][j];
        ans %= P;
      }
    } else {
      for (int j = 1; j < 10; j++) {
        ans += dp[i + 1][0][j];
        ans %= P;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

