                    dp[len][sum][last] += dp[len - 1][prev][i];
                dp[len][sum][last] %= mod;
            }
        }
    }
    int ans = 0, cnt = 0;
    for(int i = n; i > 0; i--) {
        for(int j = 0; j < (s[i] - '0'); j++) {
            int prev = (k - cnt + 10000000LL * k) % k;
            ans += dp[i][prev][j];
        }
        ans %= mod;
        cnt += s[i] - '0';
    }
    ans = (ans - 1 + mod) % mod;
    if(cnt % k == 0) ans = (ans + 1) % mod;
    cout << ans << '\n';
    return 0;
}

