#define n 10005
ll mod=1e9+7;
ll dp[n][105];
ll ans=0;
ll D;
void f(string s,ll p)
{
	if (s.length()==0)
		return;
	ll v=s[0]-'0';
	ll N=s.length();
	if (N==1)
		v++;
	for(ll i=0;i<v;i++)
	{
		ll V=(i%D+p)%D;
		if (V!=0)
			V=D-V;
		//cout<<i<<" "<<V<<" "<<dp[N-1][V]<<endl;
		if (N>1)
		ans+=(dp[N-1][V]);
		else
		ans+=(i%D==V);
		if (ans>=mod)
			ans%=mod;
	}
	s=s.substr(1,N);
	v=(v%D+p)%D;
	f(s,v);
}

