const ll MAX_SIZE = 10005;
ll memo[MAX_SIZE][2][105];
string K;
ll D;
VV(ll) A;



int main() {



    cin >> K;
    cin >> D;

    // Kの桁分解。
    vector<ll> dig;
    vector<ll>cumsum;
    dig.push_back((K[0]-'0'));
    for(auto i = 1; i<K.size(); i++){
        dig.push_back(K[i] - '0');
    }
    cumsum.push_back(dig[0]%D);
    for(auto i = 1; i<K.size(); i++){
        cumsum.push_back((cumsum[i-1]+dig[i])%MOD);
    }


    reverse(all(dig));
    reverse(all(cumsum));
    ll N = (ll)K.size();

    memo[N-1][1][dig[N-1]%D] = 1;
    for(auto i = 0; i<dig[N-1];i++){
        memo[N-1][0][i%D] += 1;
        memo[N-1][0][i%D] %=MOD;
    }

    for(auto n = N-2;n>=0;n--){
        memo[n][1][cumsum[n]%D] = 1;
        for(auto i =0; i<D; i++){
            for(auto j = 0; j<dig[n];j++){
                memo[n][0][(i+j)%D] += memo[n+1][1][i];
                memo[n][0][(i+j)%D] %=MOD;
            }

            for(auto j = 0; j<10;j++){
                memo[n][0][(i+j)%D] += memo[n+1][0][i];
                memo[n][0][(i+j)%D] %=MOD;
            }
        }

    }

    cout << (memo[0][1][0] + memo[0][0][0] - 1) %MOD << endl;

    return 0;
}

