long dpss[MAX_LOG10K][MAX_D];

int main() {
  // read inputs
  long ks[MAX_LOG10K], num_digits = 0, D;
  char buf[SIZE_BUF], c;
  while ((c = fgetc(stdin)) != '\n') {
    ks[num_digits++] = c - '0';
  }
