void R() {
    ll N,K;
    cin>>N>>K;
    vector<vector<ll>> a(N+1,vector<ll>(N+1,0));
    for(int i=1; i<=N; i++) {
        for(int j=1; j<=N; j++) {
            cin>>a[i][j];
        }
    }
    auto amul=[](vvl aa,vvl bb,int n) {
        vector<vector<ll>> t(n+1,vector<ll>(n+1,0));
        for(int i=1; i<=n; i++) {
            for(int k=1; k<=n; k++) {
                for(int j=1; j<=n; j++) {
                    t[i][j]=(t[i][j]+aa[i][k]*bb[k][j])%mod;
                }
            }
        }
        return t;
    };
    auto power=[&amul](ll k,vvl cur,int n) {
        vvl res(n+1,vector<ll> (n+1,0));
        for(int i=1; i<=n; i++)
            res[i][i]=1;
        while(k>0) {
            if(k&1)
                res=amul(res,cur,n);
            k=k>>1;
            cur=amul(cur,cur,n);
        }
        return res;
    };
    ll ans=0;
    vvl f=power(K,a,N);
    for(int i=1; i<=N; i++) {
        for(int j=1; j<=N; j++) {
            ans+=f[i][j];
            ans%=mod;
        }
    }
    cout<<ans<<endl;
}
ll SHelper(int pos,int state,bool limit){
    //cout<<pos<<" "<<pre<<" "<<state<<" "<<limit<<endl;
    if(pos==-1) return state==0?1ll*1:1ll*0;
    if(!limit&&dp[pos][state]!=-1) return dp[pos][state];

    int up=limit?a[pos]:9;
    //cout<<"ok"<<endl;
    ll ans=0;
    for(int i=0;i<=up;i++){
        ans=(ans+SHelper(pos-1,(state+i)%d,limit&&(i==a[pos])))%mod;
    }

    if(!limit) dp[pos][state]=ans;
    return ans;
};
