const int MOD = (int)1e9 + 7;

void solve(istream& in, ostream& out) {
  auto num = next<string>(in);
  auto d = next<int>(in);
  if (num.length() == 1 && num[0] == '1') {
    out << "1\n";
    return;
  }

  vec2d<int> dp = makeVec2d<int>(d, 2);
  vec2d<int> nxt = makeVec2d<int>(d, 2);

  int dd = num[0] - '0';
  FOR(i, dd) {
    dp[i % d][0] = 1;
  }
  dp[dd % d][1] = 1;

  FOR(i, num.length()) if (i) {
    FOR(j, d) {
      FOR(w, 2) {
        if (!dp[j][w]) continue;
        if (w == 1) {
          // continue prefix
          FOR(nd, num[i] - '0' + 1) {
            int newJ = j + nd;
            newJ %= d;
            (nxt[newJ][nd == num[i] - '0' ? 1 : 0] += dp[j][w]) %= MOD;
          }
        } else {
          FOR(nd, 10) {
            int newJ = j + nd;
            newJ %= d;
            (nxt[newJ][0] += dp[j][w]) %= MOD;
          }
        }
      }
    }
    dp = nxt;
    nxt = makeVec2d<int>(d, 2, 0);
  }

  int res = 0;
  FOR(j, 2) {
    res += dp[0][j];
    if (res >= MOD) {
      res -= MOD;
    }
  }
  --res;
  if (res < 0) res += MOD;
  out << res << "\n";
}

