ll F(int pos,int mod,bool isbig)
{
    if(pos >= s.size() )
        return mod == 0;
    ll &r = dp[pos][mod][isbig] ;

    if(r != -1) return r;

    r = 0;
    if(isbig)
    {
        for(int i = 0; i <= 9; i++)
        {
            r += F(pos+1, (mod +  i) % d, isbig);
            r %= MOD;
        }

    }
    else{
        for(int i = 0; i <= (s[pos] - '0'); i++)
        {
            if( (s[pos] - '0') == i) {
                r += F(pos+1, (mod + i) % d, isbig) ;
                r %= MOD;
            }
            else{
                r += F(pos+1,(mod +  i) % d, 1);
                r %= MOD;
            }

        }
    }
    return r;
}
