LL call(int pos,bool isSmall,int rem)
{
    if(pos==len) {
        if(rem==0) return 1;
        else return 0;
    }
    if(vis[pos][rem][isSmall]==1) return dp[pos][rem][isSmall];
    vis[pos][rem][isSmall]=1;
    int last=9;
    if(!isSmall) last=inp[pos];
    LL ret=0;
    for(int i=0;i<last;i++) ret=(ret+call(pos+1,1,(rem+i)%k))%MOD;
