ll dp[10000][100][2];

ll solve(ll n,ll md,ll s){
    if((n==k.length())&&(md==0))
        return 1;
    if(n==k.length())
        return 0;
    if(dp[n][md][s]!=-1)
        return dp[n][md][s];
    dp[n][md][s]=0;
    int mx=(s==0?k[n]:'9')-'0';
    for(ll i=0;i<=mx;i++){
        ll nmd=(md+i)%d;
        ll ns=(s||(i<mx))?1:0;
        dp[n][md][s]=(dp[n][md][s]+solve(n+1,nmd,ns))%mod;
    }
    return dp[n][md][s];
}
