ll solve(int idx, int sum, int smaller)
{
    if (idx == (int)num.size())
    {
        return sum == 0;
    }

    if (vis[idx][sum][smaller])
        return dp[idx][sum][smaller];
    vis[idx][sum][smaller] = 1;

