LL A[maxn + 1];
struct Node {
    LL ans, sum, size;
    Node operator+(const Node &node) const {
        Node res;
        res.size = size + node.size;

        if (size & 1)
            res.sum = sum - node.sum;
        else
            res.sum = sum + node.sum;

        if (size & 1)
            res.ans = ans - node.ans - size * node.sum;
        else
            res.ans = ans + node.ans + size * node.sum;

        return res;
    }
} T[maxn << 2];

void build(int v, int tl, int tr) {
    if (tl == tr) {
        T[v].size = 1;
        T[v].ans = T[v].sum = A[tm];
    } else {
        build(ls, tl, tm);
        build(rs, tm + 1, tr);
        T[v] = T[ls] + T[rs];
    }
}

void update(int v, int tl, int tr, int x, int V) {
    if (tl == tr) {
        T[v].ans = T[v].sum = V;
    } else {
        if (x <= tm)
            update(ls, tl, tm, x, V);
        else
            update(rs, tm + 1, tr, x, V);
        T[v] = T[ls] + T[rs];
    }
}

Node query(int v, int tl, int tr, int l, int r) {

    if (l <= tl and tr <= r)
        return T[v];
    if (r <= tm)
        return query(ls, tl, tm, l, r);
    if (l > tm)
        return query(rs, tm + 1, tr, l, r);
    return query(ls, tl, tm, l, r) + query(rs, tm + 1, tr, l, r);
}

int d = 0;
map<vector<int>, LL> dic;
int mod = 1e9 + 7;
LL dfs(int pos, int limit, int zero, int pre, vector<int> &v) {

    if (pos == v.size()) {
        if (zero)
            return 0;
        return (pre % d) == 0 ? 1 : 0;
    }
    vector<int> key = {pos, pre};
    if (!limit and !zero and dic.count(key))
        return dic[key];

    int up = limit ? v[pos] : 9;

    LL res = 0;
    for (int i = 0; i <= up; ++i) {

        res = (res + dfs(pos + 1, limit and (i == up), zero and (i == 0), (pre + i) % d, v)) % mod;
    }

    if (!limit and !zero)
        return dic[key] = res;

    return res;
}
