    if(dp[idx][mod][flag] != -1)
        return dp[idx][mod][flag];
    int ans = 0;
    int curDig = (int)(k[idx] - '0');
    if(!flag){
        for(int i = curDig; i >= 0; i--){
            ans = ans + solve(idx + 1, (mod + i) % m, (i < curDig));
            if(ans >= M)
                ans -= M;
        }
    }
    else{
        for(int i = 0; i < 10; i++){
            ans = ans + solve(idx + 1, (mod + i) % m, flag);
            if(ans >= M)
                ans -= M;
        }
    }
    return dp[idx][mod][flag] = ans;
}
