typedef long long int lli;

const lli MOD = 1e9+7;
vector<lli> num;
lli dp[10000][100][2];

lli solve(lli index, lli sum, lli flag, lli d, lli val)
{
	if(index == num.size())
	{
		// cout<<"val "<<val<<" sum "<<sum<<endl;
		return sum % d == 0;
	}
	if(dp[index][sum][flag] != -1) return dp[index][sum][flag];

	lli limit, result = 0;
	if(flag == 0) limit = num[index];
	else limit = 9;

	for(lli digit = 0; digit <= limit; digit++)
	{
		lli nflag = flag;
		lli nsum = (sum + digit)%d;
		lli nval = val*10 + digit;
		if(flag == 0 and digit < limit) nflag = 1;
		result = (result%MOD + solve(index+1, nsum, nflag,d,nval)%MOD)%MOD;
	}

	return dp[index][sum][flag] = result;
}

