int solve(int idx, int rem, bool smaller)
{
  if(idx == s.size())
    return rem == 0;
  int &ans = dp[idx][rem][smaller];
  if(ans != -1)
    return ans;
  ans = 0;
  if(smaller)
  {
      for(int digit = 0; digit < 10; digit++)
        ans = add(ans, solve(idx + 1, (rem + digit) % d, 1));
