    {
      if(digit < s[idx] - '0')
        ans = add(ans, solve(idx + 1, (rem + digit) % d, 1));
      else
        ans = add(ans, solve(idx + 1, (rem + digit) % d, 0));
    }
    return ans;
  }
}

