i64 solve(string s, int d) {
    i64 dp[(int)s.size()+1][2][d];
    rep(i, s.size()+1)rep(j, 2)rep(k, d)dp[i][j][k] = 0;
    dp[0][0][0] = 1;
    rep(i, s.size()) rep(j, 2) rep(k, d) {
        int lim = j ? 9 : s[i] - '0';
        rep(l, lim + 1) {
            dp[i + 1][j || l < lim][(k+l)%d] += dp[i][j][k];
