/*
 * n: 今何桁目
 * d: 今までの合計 (MOD D)
 * l: 次の桁の数字を制限するか
 */
ll rec(int n = 0, int d = 0, bool l = true) {
  ll &cache = dp[l][n][d];
  if (~cache) return cache;
  if (n == N) return cache = d == 0;
  int u = l ? K[n] - '0' : 9;
  ll ways = 0;
  for (int i=0; i<=u; i++) {
    ways += rec(n + 1, (d + i) % D, l && i == u);  // 一度でも制限解除されると最後の桁まで制限なし.
    ways %= MOD;
  }
  return cache = ways;
}

void memoRec() {
  memset(dp, -1, sizeof(dp));
  ll ways = (rec() - 1 + MOD) % MOD; // 1<= なので0の分を引く
  cout << ways << endl;
}

// 遷移
// dp[false][n+1][(d+i)%D] = dp[false][n][d] + dp[true][n][d];
// dp[i == u][n+1][(d+i)%D] = dp[true][n][d];

void give() {
  memset(dp, 0, sizeof(dp));
  dp[1][0][0] = 1;
  for (int n=0; n<N; n++) {
    for (int d=0; d<D; d++) {
      for (int l=0; l<=1; l++) {
        for (int i=0; i<=9; i++) {
          if (l && i > K[n] - '0') continue;
          int nl = (l && i == K[n] - '0') ? 1 : 0;
          dp[nl][n+1][(d+i)%D] += dp[l][n][d];
        }
      }
    }
  }

  ll ans = dp[0][N][0];
  ans += dp[1][N][0];
  ans--;
  ans = (ans + MOD) % MOD;
  cout << ans << endl;
}

void solve() {
  give();
}

int main() {
  // cout.precision(15);
  input();
  solve();
  return 0;
}

