    for (int i = n - 1; i >= 0; --i) {
        for (int x = 0; x < 10; ++x) {
            for (int j = 0; j < d; ++j) {
                upd(right[i][(j + x) % d], right[i + 1][j]);
            }
        }    
    }

    int total = 0; upd(total, -1);

