int solve(int idx, int sum, int tight){
    // cout << idx << " " << sum << " " << tight << '\n';
    if(idx == -1) 
        return sum % d == 0;

    if(dp[idx][sum][tight] != -1 and tight != 1)
        return dp[idx][sum][tight];

    int ret = 0;

    int j = (tight) ? digits[idx] : 9;

    for(int i=0;i<=j;++i){
