		for( int i = 0 ; i <= 9 ; i++ )
			dp[curr][sum][type] = ( dp[curr][sum][type] + f( curr+1 , (sum+i)%k , 1 ) ) % mod;
	}
	else {
		for( int i = 0 ; i < val ; i++ )
			dp[curr][sum][type] = ( dp[curr][sum][type] + f( curr+1 , (sum+i)%k , 1 ) ) % mod;
		dp[curr][sum][type] = ( dp[curr][sum][type] + f( curr+1 , (sum+val)%k , 0 ) ) % mod;
	}
	return dp[curr][sum][type];
}

