          add(dp[i][0][q], dp[i-1][1][p]);
        } else if (g == digit) {
          add(dp[i][0][q], dp[i-1][0][p]);
          add(dp[i][1][q], dp[i-1][1][p]);
        } else {
          add(dp[i][0][q], dp[i-1][0][p]);
        }
      }
    }
  }
  cout << ((dp[s.size()][0][0] + dp[s.size()][1][0] - 1) % MOD + MOD) % MOD << endl;
}

