	int ret = 0;
	for (int i=0; i<=u; ++i) {
		ret += dfs(pos+1,(sum+i)%D,limit && i==k[pos]-'0');
		ret%=Mod;
	}
	if (!limit) dp[pos][sum] = ret;
	//  cout<<"dfs("<<pos<<","<<sum<<","<<limit<<")="<<ret<<endl;
	return ret;
}
signed main() {
	memset(dp,-1,sizeof(dp));
	cin>>k>>D;
	cout<<dfs(0,0,true)-1<<endl;
	return 0;
}

