int binpow(int x, int p) {
    int res = 1;
    while(p) {
        if(p % 2)
            res = (res * x) % mod;
        x = (x * x) % mod;
        p /= 2;
    }
    return res;
}

const int N = 1e5 + 7, NS = 3e3 + 7, lg = 20, sq = 550, inf = 1e9 + 7, SM = 1e2 + 7;
const ld eps = 1e-9;
void sum(int &x, int y) {
    x += y;
    if(x >= mod)
        x -= mod;
}
int d[N][SM][2], a[N];
void solve() {
    mod = hash_mod[0];
    string s;
    cin >> s;
    int n = s.size(), q;
    for (int i = 0; i < n; i++)
        a[i] = (int) (s[i] - '0');
    cin >> q;
    for (int i = 0; i < a[0]; i++)
        d[0][i % q][0]++;
    d[0][a[0] % q][1]++;
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < q; j++) {
            for (int l = 0; l < 10; l++) {
                if(l < a[i + 1]) {
                    sum(d[i + 1][(j + l) % q][0], d[i][j][0]);
                    sum(d[i + 1][(j + l) % q][0], d[i][j][1]);
                }
                if(l > a[i + 1]) 
                    sum(d[i + 1][(j + l) % q][0], d[i][j][0]);
                if(l == a[i + 1]) {
                    sum(d[i + 1][(j + l) % q][0], d[i][j][0]);
                    sum(d[i + 1][(j + l) % q][1], d[i][j][1]);
                }
            }
        }
    }

    int ans = 0;
    sum(ans, d[n - 1][0][0]);
    sum(ans, d[n - 1][0][1]);
    cout << (mod + ans - 1) % mod;
}

