ll f(ll cur , ll modulo , bool isFree) {
  if (cur >= n) return modulo == 0;
  ll &sol = dp[cur][modulo][isFree];
  if (sol != -1) return sol;
  sol = 0;
  if (!isFree) {
    for (ll i = 0 ; i < ctoi(s[cur]) ; i++) {
      sol = add(sol , f(cur + 1 , (modulo + i) % d , 1));
