    sol = add(sol , f(cur + 1 , (modulo + ctoi(s[cur])) % d , 0));
  } else {
    for (ll i = 0 ; i < 10 ; i++) {
      sol = add(sol , f(cur + 1 , (modulo + i) % d , 1));
    }
  }
  return sol;
}

