int dp[101][10001][2], d;
string s;

int solve(int i, int val, int tight) { 
	val %= d;
	if (i == s.length()) {
		if (val % d == 0) {
			return 1;
		}
		return 0;
	}

	if (dp[val][i][tight] != -1) {
		return dp[val][i][tight];
	}

	int limit = 9, ans = 0;
	if (!tight) {
		for (int num = 0; num <= limit; num++) {
			ans += solve(i + 1, val + num, tight);
			ans %= mod;
		}	
	}

	if (tight) {
		limit = s[i] - '0';
		for (int num = 0; num < limit; num++) {
			ans += solve(i + 1, val + num, !tight);
		}	
		ans += solve(i + 1, val + limit, tight);
		ans %= mod;
	}

	return dp[val][i][tight] = ans;
} 

