        res = (res + calc(idx + 1, (muda + i) % d, newtight)) % oo;
    }
    dp[idx][muda][tight] = res;
    return res;
}
long long solve(string s)
{
    digit.clear();
    reset(dp, -1);
    get(s, digit);
    return calc(0, 0, 1);
