ll dfs(int pos, int now, bool limit) {
    if (pos == len + 1) {
        return dp[pos][now] = (now == 0);
    }
    if (!limit && dp[pos][now] != -1) {
        return dp[pos][now];
    }
    int up = limit ? a[pos] : 9;
    ll sum  = 0;
    for (int i = 0;i <= up; ++i) {
        sum += dfs(pos + 1, (now + i) % d, limit && i == up);
        if (sum >= mod) sum -= mod;
    }
    if (!limit) dp[pos][now] = sum;
    return sum;
}


