ll count(int idx, ll sum_so_far,int lo)
{
    int n = y.size();
    if(idx==n)
        return (sum_so_far%d ==0)*1LL;

    if(dp[idx][sum_so_far%d][lo]!=-1)
       return dp[idx][sum_so_far%d][lo];

    ll result =0;   
