ll solve(string& K, int D, int pos, int d, bool restr) {
	if (dp[pos][d][restr] != -1) return dp[pos][d][restr];
	ll ans = 0;
	int mx = (restr) ? K[pos] - '0' : 9;

	if (pos == (K.length() - 1)) {

