        if(b==0){
            rep(i,0,10){
                res+=rec(d-1,0,(r+i)%D);
                res%=mod;
            }
        }else{
            rep(i,0,val[d]){
                res+=rec(d-1,0,(r+i)%D);
                res%=mod;
            }
            res+=rec(d-1,1,(r+val[d])%D);
            res%=mod;
        }

        return res;
    };

    assert(rec(max_digit-1,1,0)!=0);
    cout << (rec(max_digit-1, 1, 0)-1+mod)%mod << endl;
}

