long long go (int pos = 0, bool sp = 1, int m = 0) {
	if (pos == s.size()) return m == 0;
	int l = 0, r = 9;
	if (sp) r = s[pos] - '0';
	if (sp) {
		long long res = 0;
		while (l < r) {
