int go (int n, int pos , long long sum, bool flag){

    if(dp[pos][sum][flag] != -1){
        return dp[pos][sum][flag] % mod;
    }

    if( pos > n ){
        // cout<<sum<<endl;
        if(/*sum!=0 &&*/ sum % d == 0){
           return 1;
        }
        return 0;
    }

    int limit = 9;
