    }

    long long ans = 0;

    for( int i = 0 ; i <= limit ; i++ ) {
        if(flag || i < limit)
        dp[pos][sum][flag] = ans = ( ans % mod +  (go (n, pos + 1, (sum + i) % d, true) % mod) ) % mod;
        else
        dp[pos][sum][flag] = ans = ( ans % mod +  (go (n, pos + 1, (sum + i) % d, false) % mod) ) % mod;

    }

    return dp[pos][sum][flag] = ans % mod;

}


