int digitdp(int pos, string &b, bool tight, int cur_sum, int d)
{
	if(pos == b.size())
		return cur_sum % d == 0;

	if(mem[pos][tight][cur_sum] != -1)
		return mem[pos][tight][cur_sum];


	int dig = b[pos] - '0';
	// error(pos, tight, cur_sum);

	int k = tight == 1 ? dig : 9;

	int ret = 0;

	for (int i = 0; i <= k; ++i)
	{
		bool newtight = (tight && i == dig);

		ret += digitdp(pos + 1, b, newtight, cur_sum + i, d);
		ret %= mod;
	}

	mem[pos][tight][cur_sum] = ret;

	return ret;
}

