    if(pos==n)
        return sum==0;
    if(dp[pos][sum][isFree]!=-1)
        return dp[pos][sum][isFree];
    ll ans=0;
    for(ll i=0;i<10;i++)
    {
        if(isFree)
        {
            ans = ( ans + go(pos+1,(sum+i)%d,1) )%mod ;
        }
        else
        {
            if(i < s[pos]-'0')
                ans = ( ans + go(pos+1,(sum+i)%d,1) )%mod;
            if(i==s[pos]-'0')
                ans = ( ans + go(pos+1,(sum+i)%d,0) )%mod;
        }
    }
    return dp[pos][sum][isFree] = ans;
}

void solve()
{
    n=s.size();
    memset(dp,-1,sizeof dp);
    cout<<go(0,0,0)-1;
}

