mi solve(int i, int m, bool tight) {
  if (i == k.size()) {
    return m == 0;
  }
  if (!vis[i][m][tight]) {
    if (tight) {
      int maxd = k[i] - '0';
      dp[i][m][1] += solve(i+1, (m+maxd)%d, 1);
      for (int j = 0; j < maxd; ++j) {
        dp[i][m][1] += solve(i+1, (m+j)%d, 0);
      }
    } else {
      for (int j = 0; j < 10; ++j) {
        dp[i][m][0] += solve(i+1, (m+j)%d, 0);
      }
    }
    vis[i][m][tight] = 1;
  }
  return dp[i][m][tight];
}

