ll go(string str,ll d,ll pos=0,ll rem=0,ll tight=1)
{
	if(pos==str.length())
	{
		if(rem==0)
			return 1;
		else
			return 0;
	}
	else if(dp[pos][rem][tight]!=-1)
		return dp[pos][rem][tight];
