			if(i==str[pos]-'0')
				res=(res%mod+go(str,d,pos+1,(rem+i)%d,1)%mod)%mod;
			else
				res=(res%mod+go(str,d,pos+1,(rem+i)%d,0)%mod)%mod;
		}
		if(res<0)
			res+=mod;
		return dp[pos][rem][tight]=res%mod;	
	}
	else
	{
		ll res=0;
		for(int i=0;i<=9;i++)
			res=(res%mod+go(str,d,pos+1,(rem+i)%d,0)%mod)%mod;
		if(res<0)
			res+=mod;
		return dp[pos][rem][tight]=res%mod;
