    for (int i = 0; i < len; ++i) {
        for (int j = 0; j < 2; ++j) {
            for (int k = 0; k < 10; ++k) {
                for (int l = 0; l < D; ++l) {
                    if (dp[i][j][k][l] == 0) continue;

                    if (j == 0) { //制限なし
                        for (int m = 0; m < 10; ++m)
                            (dp[i + 1][0][m][(l + m) % D] += dp[i][j][k][l]) %= MOD;
                    }
                    else { // 制限あり
                        const int ub = (int)(K[i] - '0');
                        for (int m = 0; m < ub; ++m)
                            (dp[i + 1][0][m][(l + m) % D] += dp[i][j][k][l]) %= MOD;
                        (dp[i + 1][1][ub][(l + ub) % D] += dp[i][j][k][l]) %= MOD;
                    }
                }
            }
        }
    }

    ll res = 0;
    for (int i = 0; i < 10; ++i) {
        (res += dp[len][0][i][0]) %= MOD;
