ll calc(int idx, bool tight, int sum, vector<int> digit, int D)
{
	int sz = digit.size();
	if(idx==sz) {
		return sum%D? 0ll:1ll;
	}
	int modulo = sum%D;
	if(dp[idx][tight][modulo]!=-1ll) return dp[idx][tight][modulo];

	int lmt = tight? digit[idx]:9;
	ll ret = 0ll;
	for(int i=0; i<=lmt; i++) {
		ret+=calc(idx+1, tight and i==lmt, sum+i, digit, D);
		if(ret>=mod) ret-=mod;
	}
	return dp[idx][tight][modulo] = ret%mod;
}


