        }else{
            rep(i,0,val[d]){
                res+=rec(d-1,0,(r+i)%D);
                res%=mod;
            }
            res+=rec(d-1,1,(r+val[d])%D);
            res%=mod;
        }

        return res;
    };

    cout << rec(max_digit-1, 1, 0)-1 << endl;
}

