    for (int j = 0; j < d[i]; j++) {
      f[i][(x2 + j) % k]++;
      f[i][(x2 + j) % k] %= mod;
    }
    x2 = (x2 + d[i]) % k;
  }
  return (f[n][0] % mod) - 1;
}

