ll calculate(string s,ll d,ll pos,ll sum,bool tight){
	if(dp[pos][sum][tight]==-1){
		ll ub=9;
		ll count=0;
		if(tight)
			ub=s[pos]-'0';
		for(ll i=0;i<=ub;i++){
			if(pos==s.length()-1){
				if((sum+i)%d==0)
