typedef long long int  ll;

const ll mod = 1e9+7;
const int N = 1e4+7, D = 111;

ll dp[N][D];

ll solve(string& s, int d)
{
  ll res = 0, curmod = 0;
  for(int i=0;i<(int)s.size();++i)
  {
    for(int j=0;j<s[i]-'0';++j)
    {
      res = (res  + dp[s.size() - i - 1][(0 + d - (curmod + j) % d) % d]) % mod;
    }
    curmod += s[i]-'0';
    curmod %= d;
  }
  if(curmod == 0) ++res;
  return res;
}

