int solve(string s,int idx,bool smaller,int rem)
{
  if(idx==s.size())
  {
    return (rem!=0)?0:1;
  }
  if(dp[idx][smaller][rem]!=-1)
    return dp[idx][smaller][rem];

  int limit=9;
  if(smaller)
    limit=s[idx]-'0';

