			sek = (d - i) % D;
			if (sek >= 0) ret = (ret + rek(pos + 1, sek, ter)) % MOD; 
			else ret = (ret + rek(pos + 1, sek + D, ter)) % MOD;
		}
		else if (ter == 1){
			if (k[pos] - '0' < i) {
				sek = (d - i) % D;
				if (sek >= 0) ret = (ret + rek(pos + 1, sek, 2)) % MOD; 
