Mint rec(int digit, bool smaller, int modD) {
    if (digit >= K.size()) return (modD == 0);
    Mint memo = dp[digit][smaller][modD];
    if (!memo.init) return memo;

    int lim = smaller ? 9 : (K[digit] - '0');

