		for (int num = 0; num < limit; num++) {
			ans += solve(i + 1, val + num, !tight, actual_sum + num);
		}	
		ans += solve(i + 1, val + limit, tight, actual_sum + limit);
		ans %= mod;
	}

	return dp[val][i][tight] = ans;
} 

