typedef long long ll;

int dp[10001][100][2];
const int mod = 1e9 + 7;

void add_self(int &a, int b) {
	a += b;
	if (a >= mod) a -= mod;
}

int solve(string k, int d, int len, int modulo, int flag) {
	if (len == k.length())
		return (modulo == 0);
	if (dp[len][modulo][flag] != -1)
		return dp[len][modulo][flag];
	int ans = 0;
	if (flag) {
		int msd = k[len] - 48;
		for (int i = 0; i < msd; i++)
			add_self(ans, solve(k, d, len + 1, (modulo + i) % d, 0));
		add_self(ans, solve(k, d, len + 1, (modulo + msd) % d, 1));
	}
	else {
		for (int i = 0; i < 10; i++)
			add_self(ans, solve(k, d, len + 1, (modulo + i) % d, 0));
	}
	return dp[len][modulo][flag] = ans;
}

int main() {
	string k;
	int d;
	cin >> k >> d;

	memset(dp, -1, sizeof dp);
	cout << min(0, solve(k, d, 0, 0, 1)-1) << "\n";
}

