    for(int i = 1; i <= n; i++)
    {
        int x = s[i-1] - '0';
        for(int j = 0; j < d; j++)
        {
            int prev = (j - x + 10 * d) % d;
            dp[i][j][0] += dp[i-1][prev][0];
            dp[i][j][0] %= mod;
            for(int k = 0; k < 10; k++)
            {
                prev = (j - k + 10 * d) % d;
                dp[i][j][1] += dp[i-1][prev][1];
                if(k < x)
                    dp[i][j][1] += dp[i-1][prev][0];
                dp[i][j][1] %= mod;
            }
        }
    }
    int ans = dp[n][0][0] + dp[n][0][1] - 1 + mod;
    ans %= mod;
    cout << ans << endl;
