          for (int d = 0; d < cur_d; d++) {
            dp[i + 1][1][(k + d) % mod] += dp[i][0][k];
          }
          dp[i + 1][0][(k + cur_d) % mod] += dp[i][0][k];
        } else {
          // j == 1
          for (int d = 0; d < 10; d++) {
            dp[i + 1][1][(k + d) % mod] += dp[i][1][k];
          }
        }
      }
    }
  }
  FiniteField ans = dp[n][0][0] + dp[n][1][0] - 1;
  cout << ans.Value() << endl;
}

