	ll ans = mod - 1;
	ll rem = 0;
	for(int ind = num.size() - 1; ind >= -1; ind--) {
		if(ind == -1) {
			ans += rem == 0;
			break;
		}
		ll cnt0 = 0;
		for(int d = 0; d < num[ind]; d++) {
			cnt0 = add(cnt0, dp[ind][(-rem - d + 10 * K) % K]);
		}
		ans += cnt0;
		ans %= mod;
		rem = (rem + num[ind]) % K;
	}
	cout << ans;
    return 0;
}

