	dpe[0][(s[0] - '0') % m][s[0] - '0'][1]++;

	for (int i = 1; i < n; i++)
	{
	for (int j = 0; j <= 9; j++)
	{
	for (int z = 0; z < m; z++)
	{
		for (int a = 0; a < s[i] - '0'; a++)
		{
			int y = (z + a) % m;
			dpe[i][y][a][0] = (dpe[i][y][a][0] + dpe[i - 1][z][j][1]);
			if (dpe[i][y][a][0] >= mod)
				dpe[i][y][a][0] -= mod;
		}

		for (int a = 0; a <= 9; a++)
		{
			int y = (z + a) % m;
			dpe[i][y][a][0] = (dpe[i][y][a][0] + dpe[i - 1][z][j][0]);
			if (dpe[i][y][a][0] >= mod)
				dpe[i][y][a][0] -= mod;
		}

		int x = s[i] - '0';
		int y = (z + x) % m;
		dpe[i][y][x][1] = (dpe[i][y][x][1] + dpe[i - 1][z][j][1]);
		if (dpe[i][y][x][1] >= mod)
			dpe[i][y][x][1] -= mod;
	}
	}
	}

	for (int i = 0; i <= 9; i ++)
	{
		for (int b = 0; b < 2; b++)
		{
			ans = (ans + dpe[n - 1][0][i][b]);
			if (ans >= mod)
				ans -= mod;
		}
	}

	cout << ans;
	return 0;
}

