ll digitDP(vector<vector<vll>> &dp,ll x,ll y,ll p,string &s,ll val){
	if(x>=s.size()){
		if(y%val==0)
			return 1;
		else
			return 0;
	}
	if(dp[x][y][p]!=-1)
		return dp[x][y][p];
	ll ans=0;
