		for(ll i=0;i<s[x]-'0';i++){
			ans+=digitDP(dp,x+1,(y+i)%val,1,s,val)%mod;
		}
		ans+=digitDP(dp,x+1,(y+s[x]-'0')%val,0,s,val)%mod;
	}
	else{
		for(ll i=0;i<10;i++){
			ans+=digitDP(dp,x+1,(y+i)%val,1,s,val)%mod;
		}
	}
	return dp[x][y][p]=ans%mod;
}

