signed main() {
    string K;
    int D;
    cin >> K >> D;

    //dp[i][j][smaller] := i番目まで条件smallerを満たして決めたときあまりjになる場合の数
    int first = K[0] - '0';
    rep(i, first) {
        dp[0][i % D][smaller]+= mint(1);
    }
    dp[0][first % D][not] += mint(1);
    for(int i = 1;i<K.length(); i++) {
        int digi = K[i] - '0';
        //smaller->smaller(なんでもいい)、i桁目をjにすることを考える
        rep(j, 10) {
            //前のけたの和のmod + 今のけた のmod
            rep(k, D) {
                dp[i][(k + j) % D][smaller] += dp[i - 1][k][smaller];
            }
        }
        //not->smaller(digi 未満のみOK)
        rep(j, digi) {
            rep(k, D) {
                dp[i][(k + j) % D][smaller] += dp[i - 1][k][not];
            }
        }
        //not->not(digi のみOK)
        rep(k, D) {
            dp[i][(k + digi) % D][not] += dp[i - 1][k][not];
        }
    }
    //全部ゼロは除くので-1
    cout << dp[K.length() - 1][0][0] + dp[K.length() - 1][0][1] - 1 << "\n";

    return 0;
}

