                for (int digit = 0; digit < 10; digit++) {
                    if (digit > k[where] - '0' && !sm_already) {
                        break;
                    }
                    add_self(new_dp[(sum + digit) % D][sm_already || (digit < k[where] - '0')],
                        dp[sum][sm_already]);
                }
            }
        }
        dp = new_dp;
