int rec(int idx, int smaller, int modD) {
	if (dp[idx][smaller][modD] != -1) return dp[idx][smaller][modD];

	if (idx == s.size()) return modD == 0;

	int ret = 0;
	if (smaller == 1) {
		int lim = 9;
		for (int num = 0; num <= lim; num++) {
			Add(ret, rec(idx + 1, 1, (num + modD) % d));
		}
	} else {
		int lim = s[idx] - '0';
		for (int num = 0; num < lim; num++) {
			Add(ret, rec(idx + 1, 1, (num + modD) % d));
		}
		Add(ret, rec(idx + 1, 0, (lim + modD) % d));
	}

	return dp[idx][smaller][modD] = ret;
}

