const ll MOD=1e+9+7;
struct mint{
  ll x;
  mint(ll x=0):x(x%MOD){}
  mint& operator+=(const mint a){
    if((x+=a.x)>=MOD) x-=MOD;
    return *this;
  }
  mint& operator-=(const mint a){
    if((x += MOD-a.x)>=MOD) x-=MOD;
    return *this;
  }
  mint& operator*=(const mint a){
    (x*=a.x)%=MOD;
    return *this;
  }
  mint operator+(const mint a) const{
    mint res(*this);
    return res+=a;
  }
  mint operator-(const mint a) const{
    mint res(*this);
    return res-=a;
  }
  mint operator*(const mint a) const{
    mint res(*this);
    return res*=a;
  }
  mint pow(ll t) const{
    if(!t) return 1;
    mint a = pow(t>>1);
    a*=a;
    if(t&1) a*=*this;
    return a;
  }

  //for prime mod
  mint inv() const{
    return pow(MOD-2);
  }
  mint& operator/=(const mint a){
    return (*this) *= a.inv();
  }
  mint operator/(const mint a) const{
    mint res(*this);
    return res/=a;
  }
};
string k;
int d;
mint dp[10010][100][2];
int main()
{
  cin >> k >> d;

  dp[0][0][0].x = 1;

  int ks = k.size();

  rep(i,ks) rep(j,d) rep(l,2){
    int ki = k[i] - '0';
    rep(jj,(l?10:ki+1)){
      dp[i+1][(j+jj)%d][l||jj<ki] += dp[i][j][l];
    }
  }

  mint res = dp[ks][0][0] + dp[ks][0][1];

  cout << res.x-1 << "\n";

  return 0;
}

