const int MAXN = 1e4;
const int MAXD = 100;
const int TIGHT = 2;
const int UNSET = -1;
const int MOD = 1e9 + 7;

int dp[MAXN + 1][MAXD + 1][TIGHT];
int d[MAXN + 1];

string K;
int D, N;

void fast_io() {
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	cout.tie(NULL);
}

int solve(int pos, int mod, bool r) {
	if(pos == N) return (mod == 0);
	if(dp[pos][mod][r] != UNSET) return dp[pos][mod][r];

	int lim = (r ? d[pos] : 9);
	int sum = 0;

	for(int i = 0; i <= lim; i++) {
		bool nr = (i == d[pos]) ? r : 0;
		sum += solve(pos + 1, (mod + i) % D, nr);
		if(sum >= MOD) sum -= MOD;
	}

	return dp[pos][mod][r] = sum;
}

int main() {
	fast_io();
//	freopen("input/dp_s.txt", "r", stdin);

	memset(dp, UNSET, sizeof(dp));
	cin >> K >> D;

	N = K.length();
	for(int i = 0; i < N; i++) 
		d[i] = K[i] - '0';

	cout << solve(0, 0, 1) - 1 << '\n';

	return 0;
}

