LL dp[1005][105][2], D;
vector<int> arr;
LL solve(int i, int d, int op) {
    if (i == -1) return d == 0;
    if (~dp[i][d][op]) return dp[i][d][op];
    dp[i][d][op] = 0;
    int up = op ? arr[i] : 9;
    for (int k = 0 ; k <= up ; k++)
        (dp[i][d][op] += solve(i - 1, (d + k) % D, op && (k == arr[i]))) %= MOD;
    return dp[i][d][op];
}
