int digitDP(int index, int rem, int fit, string &number)
{
    if(index == -1)
        return (rem == 0) ? 1 : 0;
    if(!fit && dp[index][rem] != -1)
        return dp[index][rem];
    int limit = (fit) ? (number[index]-'0') : 9, cnt = 0;
    for(int i = 0; i <= limit; i++)
    {
        int newFit = (fit && (i == limit)) ? 1 : 0;
        cnt += digitDP(index-1, (rem-i+d)%d, newFit, number);
        cnt %= mod;
    }
    if(!fit)
        dp[index][rem] = cnt;
    return cnt;
}

