typedef long long ll;
int k, n, d[1005];
ll mod = 1e9 + 7;
ll f[1005][105][105];
string str;

void tra() {
  n = str.length();
	for (int i = 0; i < str.length(); i++) {
		d[i+1] = str[i] - '0';
	}
}

ll solve() {
	if (str == "0") return 1;
	tra();
	memset(f, 0, sizeof(f));
	int x1 = 0, x2 = 0;
	     for (int i = 1; i <= n; i++) {
		for (int x = 0; x < k; x++) {
			for (int y = 0; y < k; y++) {
				for (int j = 0; j <= 9; j++) {
					f[i][(x * 10 + j) % k][(y + j) % k] += f[i - 1][x][y];
				}
			}
		}
		for (int j = 0; j < d[i]; j++)
			f[i][(x1 * 10 + j) % k][(x2 + j) % k]++;
		x1 = (x1 * 10 + d[i]) % k;
		x2 = (x2 + d[i]) % k;
	}
	if (x1 == 0 && x2 == 0)
		f[n][0][0]++;
	ll ret = 0;
	     for(int i = 0; i < k; i++) {
	       ret += f[n][i][0];
	       ret %= mod;
	     }
	return ret-1;
}

