int f(int index, int sum, bool tight)
{
    sum %= d;
    if(index == (int)k.size()) 
    {
        if(sum%d == 0) return 1;
        return 0;
    }
    if(dp[index][sum][tight] != -1) return dp[index][sum][tight];
    int last = 9;
    if(tight) last = k[index] - '0';
    int curr =0;
    for(int i=0;i<=last;i++)
    {
        if(tight and i == last)
            curr += f(index+1, sum+i, tight);
        else
            curr += f(index+1, sum+i, 0);
    }

    dp[index][sum][tight] = curr%MOD;
    return curr%MOD;
}

