int dfs(const int i, const int j, const bool limit)
{
    if (i < 0)
        return j == 0;
    if (!limit && dp[i][j] != -1)
        return dp[i][j];
    int ans = 0;
    int last = limit ? digit[i] : 9;
    FOR(x,0,last+1) {
        ans += dfs(i-1, (j+x)%d, limit && (x==last));
        ans %= mod;
    }
    if (!limit)
        dp[i][j] = ans;
    return ans;
}

