int solve(int len, int modd){
    if(memo[len][modd] != -1) return memo[len][modd];
//    printf("solve %d %d\n",len, modd);
    if(len == 0) return modd==0;

    if(len == 1){
        int res = 0;
        for(int fd = 0; fd <= 9; fd++){
            if(fd % d == modd) res++;
        }
        return res;
    }

