ll dp[10001][101][2];
ll solve_by_dp(string &k, int &D, int pos, int d, int tight) {
  if(dp[pos][d][tight] != -1)
    return dp[pos][d][tight];
  int ub = (tight) ? k[pos]-'0' : 9;
  if(pos == k.length()-1) {
      ll ans=0;
      for(int x=0; x<=ub; x++) {
        if(d == x%D)
          ans++;
      }
      return dp[pos][d][tight] = ans%mod;
  }

  else {
    ll ans=0;
    for(int x=0; x<=ub; x++) {
      ans = (ans + solve_by_dp(k, D, pos+1, (D + d - x%D)%D, tight && (x==ub)))%mod;
    }
    return dp[pos][d][tight] = ans%mod;
  }
}

