long long Get(string& arr, int d, int i, int n, int cur) {
    if (i == n) return (cur % d == 0);
    long long ans = 0;
    for (int dig = 0; dig < arr[i]; dig++) {
        ans += Get(n - 1 - i, cur + dig, d);
        ans %= mod;
    }
    ans += Get(arr, d, i + 1, n, cur + arr[i]);
    ans %= mod;
    return ans;
}

