int solve (int pos,int prevsum,  bool lmt){
    int ret = dp[pos][prevsum][lmt];
    if (ret!= -1) return ret;
    if(pos == s.size()) return (prevsum%D==0);
    int v = s[pos] - '0', bound = lmt? v : 9; ret = 0;
    for(int i = 0; i <= bound; ++i){
        ret += solve(pos+1, (prevsum+i)%D, lmt && i == v);
        ret %= mod;
    }
    return dp[pos][prevsum][lmt] = ret;
}
