	for (int z = 0; z <= 9; z++)
	{
		dp[i][(j + z) % m] = (dp[i - 1][j] + dp[i][(j + z) % m]);
		if (dp[i][(j + z) % m] >= mod)
			dp[i][(j + z) % m] -= mod;
	}
	}
	}

	int ans = 0;
	for (int i = 1; i < n; i++)
	{
		ans = (ans + dp[i][0]) % mod;
	}

	for (int i = 1; i < s[0] - '0'; i++)
	{
		dpe[0][i][i % m][0]++;
	}
	dpe[0][s[0] - '0'][(s[0] - '0') % m][1]++;

	for (int i = 1; i < n; i++)
	{
	for (int j = 0; j <= 9; j++)
	{
	for (int z = 0; z < m; z++)
	{
		for (int a = 0; a < s[i] - '0'; a++)
		{
			dpe[i][a][(z + a) % m][0] = dpe[i][a][(z + a) % m][0] + dpe[i - 1][j][z][1];
			if (dpe[i][a][(z + a) % m][0] >= mod)
				dpe[i][a][(z + a) % m][0] -= mod;
		}
		int x = s[i] - '0';
		dpe[i][x][(z + x) % m][1] = (dpe[i][x][(z + x) % m][1] + dpe[i - 1][j][z][1]);
		if (dpe[i][x][(z + x) % m][1] >= mod)
			dpe[i][x][(z + x) % m][1] -= mod;

		for (int a = 0; a <= 9; a++)
		{
			dpe[i][a][(z + a) % m][0] = (dpe[i][a][(z + a) % m][0] + dpe[i - 1][j][z][0]);
			if (dpe[i][a][(z + a) % m][0] >= mod)
				dpe[i][a][(z + a) % m][0] -= mod;
		}
	}
	}
	}

	for (int i = 0; i <= 9; i ++)
	{
		for (int b = 0; b < 2; b++)
		{
			ans = (ans + dpe[n - 1][i][0][b]) % mod;
		}
	}

	cout << ans;
	return 0;
