    int N = K.size();

    vector<int> digit(N);
    for (int i = 0; i < N; i++)
    {
        digit[i] = K[i] - '0';
    }

    vector<vector<Mod<MOD>>> dp(N, vector<Mod<MOD>>(D, 0));
    for (int i = 0; i < 10; i++)
    {
        dp[0][i % D]++;
    }

    for (int i = 1; i < N; i++)
    {
        for (int j = 0; j < 10; j++)
        {
            for (int k = 0; k < D; k++)
            {
                dp[i][(j + k) % D] += dp[i - 1][k];
            }
        }
    }

    long long current = 0;
    Mod<MOD> ans = 0;
    int idx;
    for (int i = 0; i < N; i++)
    {
        idx = N - i - 2;
        // cout << current << endl;
        if (idx >= 0)
        {
            for (int j = 0; j < digit[i]; j++)
            {
                // cout << "current: " << (current + j) << endl;
                // cout << "i: " << i << endl;
                // cout << "dp index: " << idx << endl;
                // cout << "dp remain: " << (2 * D - (current + j)) % D << endl;
                // cout << "dp value: " << dp[idx][(D - (current + j)) % D] << endl;
                ans += dp[idx][(D - (current + j)) % D];
            }
        }
        else
        {
            for (int j = 0; j <= digit[i]; j++)
            {
                if ((current + j) % D == 0)
                {
                    ans++;
                }
            }
        }
        current += digit[i];
        current %= D;
        // cout << endl;
    }
    // cout << endl;

    // minus 1 to remove 0
    cout << ans - 1 << endl;
}

