int getdigit(int idx , int tight , int sum , int r)
{
    int ans = 0;
    int lim = (tight == 1) ? a[idx] : 9;
    FOR(i , 0 , lim)
    {
        int x = (tight & (i == a[idx]));
        int y = add(i , sum , k);
        if(idx == r && i == 0 && idx != 1)
            continue;
        if(idx == 1)
            ans += (y % k == 0);
        else
        {
            if(x == 1)
                ans = add(ans , getdigit(idx - 1 , x , y , r) , mod);
            else
                ans = add(ans , dp[idx - 1][sub(k , y , k)] , mod);
        }
    }
    return ans;
}

