        else return 0;
    }
    ll temp=0;
    if(flag==1){
        rep(i,0,s[idx]-'0') temp+=solve(idx+1,(((mod1-i+5*d)%d)+d)%d,0);
        temp+=solve(idx+1,(((mod1-(s[idx]-'0')+d)%d)+d)%d,1);
    }

    else{
        rep(i,0,10) temp+=solve(idx+1,(((mod1-i+d)%d)+d)%d,0);
    }
        //cerr<<idx<<" "<<mod1<<" "<<flag<<" "<<temp<<endl;
    return dp[mod1][idx][flag]=temp%mod;
}

