ll dp[N][2][105];

ll calc(ll pos, bool f, ll mod){
	if(dp[pos][f][mod]!=-1)return dp[pos][f][mod];
	ll ret=0;
	ll mx=9;
	if(!f)mx=a[pos];
	if(pos==n-1){
		rep(i,0,mx+1){
			if(i%d==mod)ret++;
		}
	// cerr<<"pos:"<<pos<<" f:"<<f<<" mod:"<<mod<<" ret:"<<ret<<endl;
		return dp[pos][f][mod]=ret%hell;
	}
	rep(i,0,mx+1){
		bool nf=f;
		if(!f && i<a[pos])nf=1-f;
		ll modreq = (mod-i+d)%d;
		ret=(ret+calc(pos+1,nf,modreq))%hell;
	}
	return dp[pos][f][mod]=ret;
}


