				tmp[j | (k < lim)][(l + k) % d] %= MOD;
			}
		}
		std::swap(dp, tmp);
	}
	//dump(dp);
	ll ans = 0;
	REP(i, 2) { ans += dp[i][0]; }
	return (ans - 1 + MOD) % MOD;
}

