ll solve(int pos, int rem, bool lo)
{
    if(dp[pos][rem][lo] != -1)
        return dp[pos][rem][lo];

    if(pos == s.size())
    {
        if(rem)
            return dp[pos][rem][lo] = 0;
        else
            return dp[pos][rem][lo] = 1;
    }
    ll res = 0, hi = s[pos]-'0';
