template<typename T=lint>
vector<vector<T>> pow(const vector<vector<T>>& s,const lint& n){
    if(n==0){
        lint sz=s.size();
        vector<vector<T>> res(sz,vector<T>(sz,0));
        rep(i,sz)res[i][i]=1;
        return res;
    }
    if(n==1)return s;
    if(n%2==0){
        vector<vector<T>> tmp=pow<T>(s,n/2);
        return mul<T>(tmp,tmp);
    }else{
        return mul<T>(s,pow(s,n-1));
    }
}
