int solve(string k,int dp[][100][2],int D,int pos,int d,int tight){
    if(dp[pos][d][tight]!=-1){
        return dp[pos][d][tight];
    }
    int ub;
    if(tight){
        ub=k[pos]-'0';
    }
    else{
        ub=9;
    }
    //base case
    if(pos==k.length()-1){
        int ans=0;
        for(int x=0;x<=ub;x++){
            if(x%D==d){
                ans++;
            }
        }
        return ans;
    }
    //recursive call
    int ans=0;
    for(int x=0;x<=ub;x++){
        ans=(ans+solve(k,dp,D,pos+1,(d-x%D+D)%D,tight&(x==ub)))%mod;
    }
    return dp[pos][d][tight]=ans;
}
