vector<vector<vector<ll>>> memo;

ll solve(ll i, ll j, bool equal) {
    if (i == K.size()) {
        return j == 0;
    }

    if (memo[i][j][equal] != -1) {
        return memo[i][j][equal];
    }

    ll result = 0;
