int solve(int idx, int S, int tight, string &digit) {
	int &res = dp[idx][S][tight];
	if (idx == -1 && S == 0) {
		return 1ll;
	}
	if (idx == -1) {
		return 0ll;
	}
	if (res != -1 && !tight) {
		return res;
	}
