	if (dp[index][smaller][rem] != -1) return dp[index][smaller][rem];
	ll limit = 9, cnt = 0;
	if (smaller) limit = S[index] - '0';
	foo(i, 0, limit) {
		bool ns;
		if (i < S[index] - '0') ns = 0;
		else ns = smaller;
		cnt = (cnt % mod + (solve(S, index + 1, ns, (rem  + i) % d)) % mod) % mod;
	}
	return dp[index][smaller][rem] = cnt;
}

