    for(int i = 0; i < (int)a.size(); ++i)
        num.push_back(a[i] - '0');

    memset(dp, -1, sizeof(dp));
  	// invoke the call function with flag = 1
  	// because digit at first pos has limit of num[0]
    int res = call(0, 0, 1) - 1;
  	if(res < 0) res += mod;
    return res;
}

