ll dp[1001][101][2];

ll solve(string k,int D,int pos, int d, bool tight){
    int ub=tight==1?k[pos]-'0':9;



    if(pos==k.length()-1){
        ll ans=0;
        for(int x=0;x<=ub;x++){
            if(x%D==d){
                ans++;
                ans%=mod;
            }
        }
        return ans;
    }

    if(dp[pos][d][tight]!=-1){
        return dp[pos][d][tight];
    }

    ll ans=0;

    for(int x=0;x<=ub;x++){
        ans=(ans+solve(k,D,pos+1,(D+d-x%D)%D,((x==ub)&&tight)))%mod;
    }

    return dp[pos][d][tight]=ans;


}

int main() {
   string k;
   cin>>k;
   int D;
   cin>>D;

    memset(dp,-1,sizeof(dp));

   cout<<solve(k,D,0,0,1)-1;


}

