int dfs(int k,int now,int lim)
{
    if(dp[k][now][lim]>=0) return dp[k][now][lim];
    if(k==m) return dp[k][now][lim] = (now==0);
    int sum = 0;
    int up = lim?a[k]:9;
    for(int i=0;i<=up;i++)
    {
        sum += dfs(k+1,(now+i)%n,lim&&i==up);
        sum%=mod;
    }
    return dp[k][now][lim] = sum;
}


