long long f(int pos, long long sum , bool sw){
    if(pos == K.size()){
        if(sum%D == 0) return 1;
        else return 0;
    }
    if(dp[pos][sum][sw]!=-1) return dp[pos][sum][sw];
    long long re = 0;
    long long i = 0;
    if(sw == 0){
        for(i ; i < 10 ; i++){
            re = (re%P  + f(pos+1,(sum%D+i%D)%D,0)%P)%P;
