        for( i; i <= int(K[pos]-'0') ; i++){
            if(i == int(K[pos]-'0')){
                re=(re%P +f(pos+1,(sum%D+i)%D,1)%P)%P;
            } 
            else re = (re%P +f(pos+1,(sum%D+i)%D,0)%P)%P;
        }
    }
    dp[pos][sum][sw] = re;
    return re;
}
