ll f(ll sum, ll index, bool eq)
{
	if (index == n)
	{
		if (sum % d == 0)
			return 1;
		else
			return 0;
	}
	if (dp[sum][index][eq] != -1)
		return dp[sum][index][eq];

	ll ans = 0;
	if (eq)
	{
		int digit = get(index);
		for(int i = 0; i < digit; ++i)
		{
			ans += (f((sum + i)%d, index + 1, !eq)%MOD);
			ans %= MOD;
		}
		ans += (f((sum + digit)%d, index + 1, eq)%MOD);
		ans %= MOD;
	}
	else
	{
		for(int i = 0 ; i <= 9; ++i)
		{
			ans += (f((sum + i)%d, index + 1, eq)%MOD);
			ans %= MOD;
		}
	}
	return (dp[sum][index][eq] = ans);
}
