long long rc(unsigned int digit, int rest, int tight)
{
	long long& sum{digit_dp[digit][rest][tight]};
	if (sum >= 0) return sum;
	sum = 0;

	int limit{10};
	if (tight) limit = k[digit] - '0';

	for (int i{}; i < limit; i++)
	{
		sum += rc(digit + 1, (rest + i) % d, false);
		sum %= mod;
	}
	if (tight)
	{
		sum += rc(digit + 1, (rest + limit) % d, true);
		sum %= mod;
	}
	return sum;
}

