void solve() {
    string s;
    int d;
    cin >> s >> d;
    int n = sz(s);

    vector<vector<vector<ll>>> dp(n + 1, vector<vector<ll>>(d, vector<ll>(2)));
    dp[0][0][0] = 1;

    REP(i, n) REP(j, d) REP(k, 10) {
        int nd = s[i] - '0';
        int r = (j + k) % d;
        dp[i + 1][r][1] += dp[i][j][1];
        dp[i + 1][r][1] %= MOD;
        // border
        if (k == nd) {
            dp[i + 1][r][0] += dp[i][j][0];
            dp[i + 1][r][0] %= MOD;
        }
        // under
        if (k < nd) {
            dp[i + 1][r][1] += dp[i][j][0];
            dp[i + 1][r][1] %= MOD;
        }
    }
    // REP(i, n + 1) {
    //     cout << i << ": " << endl;
    //     printvv(dp[i]);
    // }

    // 0 の分がカウントされているので1引く
    cout << dp[n][0][0] + dp[n][0][1] - 1 << endl;
}

