int calc(int i, int m, int roof) {
	if (i == n) return (m == 0 ? 1 : 0);
	if (dp[i][m][roof] != -1) return dp[i][m][roof];
	int &x = dp[i][m][roof];
	x = 0;
	if (roof) {
		for (int put = 0; put < k[i] - '0'; put++)
			x = (x + calc(i + 1, (m - put + d) % d, 0)) % md;
		x = (x + calc(i + 1, (m - (k[i] - '0') + d) % d, 1)) % md;
	}
	else {
		for (int put = 0; put < 10; put++)
			x = (x + calc(i + 1, (m - put + d) % d, 0)) % md;
	}
	return x;
}

