long long dp[10100][105];

long long go (int pos = 0, bool sp = 1, int m = 0) {
	if (pos == (int) s.size()) return !m;
	int l = 0, r = 9;
	if (sp) {
		long long res = 0;
		r = s[pos] - '0';
		while (l < r) {
			res += go (pos + 1, 0, (m + l) % d);
			res %= mod;
			++l;
		}
		res += go (pos + 1, 1, (m + r) % d);
		res %= mod;
		return res;
	}
	long long &res = dp[s.size() - pos][m];
	if (res != -1) return res;
	res = 0;
	while (l <= r) {
		res += go (pos + 1, 0, (m + l) % d);
		res %= mod;
		++l;
	}
	return res;
}

