//            db(add);

            res += add;
            res %= MOD;
        }

        modd = modd + d - x;
        modd %= d;
    }


    reverse(all(v));
    ll sum = 0;
    ll p10 = 1;
    for(int e : v){
        sum += (p10 * 1ll *e)%MOD;
        sum %= MOD;

        p10 *= 10;
