int compute(string &k, int& D, int pos, int d, bool tight){

    if(dp[pos][d][tight] != -1) 
        return dp[pos][d][tight];

    int ub = (tight) ? (k[pos] - '0') : 9;

    if(pos == k.length()-1){
        int ans=0;
        forI(x, 0, ub)
            if(x%D == d)    ans++;
        return ans;
    }
    int ans=0;
    forI(x, 0, ub)
        ans = (ans + compute(k, D, pos+1, (D+d-x%D)%D, tight && (x == ub)))%mod;

    return dp[pos][d][tight] = ans;
}

