int dp(int i, int m, int free){
  if(i==s.size()) return !m;
  if(memo[i][m][free]!=-1) return memo[i][m][free];

  int ret = 0;

  if(!free)
  {
    ret = addmod(ret, dp(i+1, (m+s[i]-'0')%d, 0));
    for(int j=s[i]-'0'-1 ; j>=0 ; j--)
      ret = addmod(ret, dp(i+1, (m+j)%d, 1));
  }
  else
  {
    for(int j=9 ; j>=0 ; j--)
    {
      ret = addmod(ret, dp(i+1, (m+j)%d, 1));
    }
  }

  return memo[i][m][free] = ret;
}
