    int n = sz(k);
    dp[0][0][0] = 1;
    fori (i, 1, n + 1) {
        fori (sum, 0, d + 1) {
            for (bool sm_already : {false, true}) {
                for (int digit = 0; digit < 10; ++digit) {
                    if (digit > k[i - 1] - '0' && !sm_already) {
                        break;
                    }
                    add(dp[i][(sum + digit) % d][sm_already || (digit < k[i-1]-'0')], dp[i-1][sum][sm_already]);
                }
            }
        }
    }
    int ret = (dp[n][0][0] + dp[n][0][1]) % mod;
    output(ret - 1);
}

