using namespace std;

typedef long long ll;
const ll modl = 1e9 + 7;

ll dp[10005][100][2];

ll solve(string K, int D, int pos, int d, bool restr) {
	if (dp[pos][d][restr] != -1) return dp[pos][d][restr];
	ll ans = 0;
	int mx = (restr) ? K[pos] - '0' : 9;

	if (pos == (K.length() - 1)) {

		for (int i = 0; i <= mx; i++) {
			if (i % D == d)
				ans++;
		}
		return dp[pos][d][restr] = ans % modl;

	}

	for (int i = 0; i <= mx; i++) {
		ans += solve(K, D, pos + 1, (D + d - i % D) % D, restr && (i == mx));
	}

	return dp[pos][d][restr] = ans % modl;
}

int main() {

	memset(dp, -1, sizeof dp);

	string K;
	int D;

	cin >> K;
	cin >> D;


	cout << solve(K, D, 0, 0, true) - 1;

	return 0;
}

