// Constants here
const int MAXK = 10010;
const int MAXD = 110;
const int MOD = 1e9 + 7;

int num[MAXK];
ll memo[MAXK][MAXD];
int D;

ll dfs(int pos, int rem, bool limit) {
  if (pos == -1) {
    return rem == 0;
  }

  if (!limit && memo[pos][rem] != -1) {
    return memo[pos][rem];
  }

  ll ans = 0;

  int maxx = limit ? num[pos] : 9;

  for (int i = 0; i <= maxx; i++) {
    ans = (ans + dfs(pos - 1, (rem + i) % D, limit && i == num[pos])) % MOD;
  }

  if (!limit) {
    memo[pos][rem] = ans;
  }

  return ans;
}

// Pre-Build Function
inline void build() { memset(memo, -1, sizeof memo); }

// Actual Solver
inline void solve() {
  string K;
  readln(K, D);

  int len = K.size();

  for (int i = len - 1; i >= 0; i--) {
    num[i] = K[len - i - 1] - '0';
  }

  writeln((dfs(len - 1, 0, true) + MOD - 1) % MOD);
}

