        for (int j = 0; j < 2; j++)
        {
            for (int d = 0; d <= (j ? 9 : D); d++)
            {
                for (int k = 0; k <= B; k++)
                {
                    dp[i + 1][j || (d < D)][(k + d) % B] += dp[i][j][k]; //dp[i][j][k] : i桁目まで見たときに
