void cachefact(ll lim, ll mod = md) {
    for(int i = 2; i <= lim; i++) {
        ifac.push_back((ifac[mod%i] * (mod - mod/i) % mod)%mod);
    }
    for(ll i = 2; i <= lim; i++) {
        fac.push_back((fac[i-1] * i)%mod);
        ifac[i] = (ifac[i-1] * ifac[i])%mod;
    }
}

ll C(ll n, ll r) {
    if(n < r || r < 0) return 0;
    return ml(fac[n], ml(ifac[r], ifac[n-r]));
}

ll PIE(ll n, ll k, ll f, ll mod = md) {
	if(f < 0 || k < 0 || n < 0) return 0;
	ll ans = 0, l = min(n, k/(f+1));
	for(int i = 0; i <= l; i++) {
		ans = ad(ans, (i&1 ? -1 : 1) * ml(C(n, i), C(n - 1 + k - (f+1) * i, k - (f+1) * i)));
	}
	return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cachefact(1e6);
    string s;
    ll d;
    cin >> s >> d;
    int n = s.size();
    ll sm = 0, off = 0;
    for(int i = 0; i < n; i++) {
		if(i != n-1) {
			for(int j = 0; j < s[i] - '0'; j++) {
				for(int k = max(d, ((off + j + d - 1)/d)*d); k <= 9*n; k += d) {
					sm = ad(sm, PIE(n - i - 1, k - off - j, 9));
	    		}
	    	}
    	} else {
    		for(int j = (n==1?1:0); j <= s[i] - '0'; j++) {
    			if((off + j)%d == 0) {
    				sm++;
				}
    		}
    	}
    	off += s[i] - '0';
    }
    cout << sm%md << "\n";
    return 0;
}

