typedef long long ll;
const int mod = 1000000007;
int n, d;
string s;
int dp[10001][2][100];
int calc(int idx, bool lmt, int sum) {
	if (idx == n) {
		if (sum == 0)
			return 1;
		return 0;
	}
	int &ret = dp[idx][lmt][sum];
	if (ret != -1)
		return ret;
	ret = 0;
	if (lmt) {
		for (int i = 0; i < s[idx] - '0'; ++i)
			ret = (ret + calc(idx + 1, false, (sum + i) % d)) % mod;
		ret = (ret + calc(idx + 1, true, (s[idx] - '0' + sum) % d)) % mod;
	}
	else
		for (int i = 0; i < 10; ++i)
			ret = (ret + calc(idx + 1, false, (sum + i) % d)) % mod;
	return ret;
}
