	n = s.size();
	int ans = 0;
	for (int i = 0; i < s[0] - '0'; ++i)
		ans = (ans + calc(1, false, i % d)) % mod;
	ans = (ans + calc(1, true, (s[0] - '0') % d)) % mod;
	cout << (ans - 1 + mod) % mod << endl;
	return 0;
}

