          dp[i + 1][j][k] %= P;
        }
      }
      sdp[i + 1][j] = sdp[i][((j - (s[i] - '0')) % d + d) % d];
      for (int k = 0; i > 0 && k < s[i - 1] - '0'; k++) {
        sdp[i + 1][j] += dp[i][((j - (s[i] - '0')) % d + d) % d][k];
        sdp[i + 1][j] %= P;
      }
    }
  }
  long long ans = sdp[n][0];

  for (int i = 0; i < n; i++) {
    if (i == n - 1) {
