// Problem - S



int solve(vector<vector<vector<int>>> &dp, string K, int D, int pos, int d, int tight) {

	if (dp[pos][d][tight] != -1)
		return dp[pos][d][tight];
	int ub = tight ? K[pos] - '0' : 9;
	long long ans = 0;
	if (pos == K.size() - 1) {
		for (int x = 0; x <= ub; x++) {
			if (x % D == d)
				ans++;
		}
		return ans;
	}

	for (int x = 0; x <= ub; x++) {
		ans = (ans + solve(dp, K, D, pos + 1, (D + d - x % D) % D, tight && (x == ub) )) % mod;
	}
	return dp[pos][d][tight] = ans;
}

