long long rec(int k,bool tight,int sum) {
  if(k==N.size()){return sum%D==0 && sum!=0;}

  int x=N[k]-'0';
  int r;
  if(tight){r=x;}
  else{r=9;}

  long long &res=dp[k][tight][sum];
  if(~res) return res;
  res=0;

  for(int i=0;i<=r;++i){
    res+=rec(k+1,tight && i==r,sum+i); res%=mod;
  }
  return res;
}

