ll solve(int n, int rem){
	if(n == 0)
		return (rem ? 0 : 1);
	if(dp[n][rem] != -1)
		return dp[n][rem];
	ll ans = 0;
	for(int i = 0; i < 10; i++)
		ans += solve(n - 1, (rem + i) % d), ans %= mod;
	return dp[n][rem] = ans;	
}

ll calc(){
	int sum = 0, n = (int)s.size();

	ll ans = 0;

	for(int i = 0; i < n; i++){
		int top = s[i] - '0';
		for(int j = 0; j < top; j++){
			int rem = (sum + j) % d;
			ans += solve(n - i - 1, rem), ans %= mod;
		}
		sum += top;
		sum %= d;
	}

	ans--;
	ans += mod;
	ans %= mod;

	if(sum == 0)
		ans++, ans %= mod;

	return ans;
}

