int solve(int ind, int mod, int c, int st){
    if (ind==-1)
        return (mod % D) == 0;
    if (dp[ind][mod][c]!=-1)
        return dp[ind][mod][c];
    if (mod>=D)
        mod -= D;
    int maxi  = 9, ans  = 0;
    if (c==1)
        maxi = no[ind];
    for (int i=st; i<=maxi; i++){
        int nc = c;
        if (c && i<maxi) nc = 0;
        ans = (ans+solve(ind-1, mod+i, nc, false));
        if (ans>=M)ans -= M;
    }
    return dp[ind][mod][c] = ans;
}
