//端数繰りあがり割り算(検証済)
// a÷bの端数繰り上げ
// b!=0のデバグはしてないので分母に0を入れないように
//負数対応
long long divup(long long a, long long b) {
	long long x = abs(a);
	long long y = abs(b);
	long long z = (x + y - 1) / y;
	if((a < 0 && b > 0) || (a > 0 && b < 0))
		return -z;
	else if(a == 0)
		return 0;
	else
		return z;
}

//階乗
//検証済み
long long kaijou(long long i) {
	if(i == 0) return 1;
	long long j = 1;
	for(long long k = 1; k <= i; k++) {
		j *= k;
	}
	return j;
}

//順列nPk(完成)
// n個の異なる要素から、取り出す順序を区別してk個取り出す場合の数
// n<kなら0を返す
//敢えて負数時のデバグはしてない
long long P(long long n, long long k) {
	if(n < k) return 0;
	long long y = 1;
	for(long long i = 0; i < k; i++) {
		y *= (n - i);
	}
	return y;
}
//組み合わせnCk(検証済み)
// P,kaijouと併用
long long C(long long n, long long k) {
	if(n < k) return 0;
	return P(n, k) / kaijou(k);
}
// nHk
//区別しないn個の要素を、区別するk個のグループに分ける
// 0個のグループがあっ
//て良い
// C必須

//最大公約数GCD,最小公倍数LCM
// LCMを使うときはGCDをセットで
//検証済み
long long GCD(long long a, long long b) {
	if(a < b) swap(a, b);
	long long d = a % b;
	if(d == 0) {
		return b;
	}
	return GCD(b, d);
}
long long LCM(long long a, long long b) { return (a / GCD(a, b)) * b; }

//素数判定
//素数ならばtrue、素数以外の整数にはfalse
//負数は全てfalse
//検証済み
bool prime(long long N) {
	if(N == 1) {
		return false;
	}
	if(N < 0) return false;
	long long p = sqrt(N);
	for(long long i = 2; i <= p; i++) {
		if(N % i == 0) {
			return false;
		}
	}
	return true;
}

