// dp[dig][r][less]:
// 上位dig桁目まで見たとき、各桁の和のmod dがrになるような方法
// less(未満フラグ)は、k未満が確定しているか (1) kギリギリか (0)

ll rec(int dig, int r, int less){
	if(dig >= n) return (r == 0);
	if(dp[dig][r][less] >= 0) return dp[dig][r][less];

	int lim = (less ? 9 : k[dig] - '0'); //上限値
	int res = 0;
	// 各桁のごとにmodをとった総和を求める
	for(int i=0; i<=lim; i++){
		res += rec(dig+1, (i+r) % d, less | (i < lim));
		res %= mod;
	}
	return dp[dig][r][less] = res;
}

