                        nk = (k+d)%D;
                        if (j == 0) {
                            if(d < x) nj = 1;
                            if(d > x) continue;
                        }
                        dp[ni][nj][nk] += dp[i][j][k];
                        dp[ni][nj][nk] %= mod;
                    }
                }
            }
	    }

	    out << (dp[n][0][0] + dp[n][1][0] + mod - 1) % mod << endl;
	}
};


