long long calc(int idx, int sum, bool t)
{
    if (idx == k.size())
        return (!sum) ? 1 : 0;
    if (dp[idx][sum][t] != -1)
        return dp[idx][sum][t];
    int m = (t) ? (k[idx] - 48) : 9;
    LL res = 0;
