#define mod 1000000007
int function(int initial,int final,int memo[][101],int d,int sum)
{
	if(initial>final)
	{
		if(initial==1)
		  return 0;
		return sum==0?1:0;
	}
	if(memo[initial][sum]!=-1)
	   return memo[initial][sum];
	else
	{
		if(initial==1)
		{
			int answer=0;
			int j;
			for(j=1;j<=9;j++)
			{
				answer+=function(initial+1,final,memo,d,(sum+j)%d);
				answer%=mod;
			}
			memo[initial][sum]=answer;
			return answer;
		}
		else
		{
			int answer=0;
			if(sum==0)
			  answer++;
			for(int j=0;j<=9;j++)
			{
				answer+=function(initial+1,final,memo,d,(sum+j)%d);
				answer%=mod;
			}
			memo[initial][sum]=answer;
			return answer;
		}
	}
}
int function(int arr[],int initial,int final,int memo[][101][2],int status,int d,int sum)
{
	if(initial>final)
	{
		return sum==0?1:0;
	}
	if(memo[initial][sum][status]!=-1)
	  return memo[initial][sum][status];
	else
	{
		int val=arr[initial];
		if(initial==0)
		{
			int j;
			int answer=0;
			for(j=1;j<=val;j++)
			{
				int next=(sum+j)%d;
				int nextstatus=0;
				if(j<val)
				  nextstatus=1;
				answer+=function(arr,initial+1,final,memo,nextstatus,d,next);
				answer%=mod;
			}
			memo[initial][sum][status]=answer;
			return answer;
		}
		else
		{
			int j,answer=0;
			if(status==1)
			{
				for(j=0;j<=9;j++)
				{
					answer+=function(arr,initial+1,final,memo,1,d,(sum+j)%d);
					answer%=mod;
				}
				memo[initial][sum][status]=answer;
				return memo[initial][sum][status];
			}
			else
			{
				for(j=0;j<=val;j++)
				{
					int next=(sum+j)%d;
					int nextstatus=0;
					if(j<val)
					  nextstatus=1;
					answer+=function(arr,initial+1,final,memo,nextstatus,d,next);
					answer%=mod;
				}
				memo[initial][sum][status]=answer;
				return memo[initial][sum][status];
			}
		}
	}
}
