    for (int i = 0; i < a.size(); i++) {
        for (int j = 0; j < D; j++) {
            for (int num = 0; num <= 9; num++) {
                int neJ = (j + num) % D;
                if (num == a[i]) dp[i+1][neJ][1] += dp[i][j][1];
                if (num < a[i]) dp[i+1][neJ][0] += dp[i][j][1];
                dp[i+1][neJ][0] += dp[i][j][0];
            }
        }
    }
