long long solve(long long idx, long long sum, long long tight)
{
    if(idx==num.size())
        return(sum%k==0);
    if(dp[idx][sum][tight]!=-1)
        return dp[idx][sum][tight];
    long long res=0;
    long long k=(tight)?num[idx]:9;
    for(int i=0;i<=k;i++)
