	cin >> s >> d;
	vector<vector<vector<long long>>> memo(s.size() + 1,vector<vector<long long>>(2,vector<long long>(d,-1LL)));
	cout << dgtdp(0,true,0,d,s,memo) - 1LL << endl;
}

