ll dp[10001][101][2];

ll calculate(string s,ll d,ll pos,ll sum,bool tight){
	if(pos==s.length()){
		return sum%d==0;
	}
	if(dp[pos][sum][tight]==-1){
		ll ub=9;
		ll count=0;
		if(tight)
			ub=s[pos]-'0';
		for(ll i=0;i<=ub;i++){
			count=(count+calculate(s,d,pos+1,(sum-i+d)%d,tight&(i==ub)))%M;
		}
		dp[pos][sum][tight]=count;
	}
	return dp[pos][sum][tight];
}

