int f(int idx, int sum_so_far, bool tight, string& s)
{
  if (idx == s.size())
    return (sum_so_far == 0);
  auto& ret = dp[idx][sum_so_far][tight];
  if (ret != -1)
    return ret;
  ret = 0;
  int ul = tight ? s[idx]-'0' : 9;
  for (int i = 0; i <= ul ; ++i) {
    ret += f(idx + 1,(sum_so_far + i) % d, tight & (i == ul), s);
    ret %= mod;
  }
  return ret;
}



