int gdp(int x, int v, int enDessous)
{
    if (x == c) {
        if (v == 0) return 1;
        else return 0;
    }
    if (dp[x][v][enDessous] == -1) {
        dp[x][v][enDessous] = 0;
        int chiffre = s[x] - '0';
