std::string& ltrim(std::string& str, const std::string& chars = "0\t\n\v\f\r ")
{
    str.erase(0, str.find_first_not_of(chars));
    return str;
}

std::string& rtrim(std::string& str, const std::string& chars = "\t\n\v\f\r ")
{
    str.erase(str.find_last_not_of(chars) + 1);
    return str;
}



int main() {


  string s;
  getline(cin, s);
  s = ltrim(rtrim(s));
  long long N = s.size();

  vector<long long> K(N);
  vector<long long> mod(N);

  for (auto i=0; i<N; i++) {
    K[i] = s[i] - '0';
  }

  long long D;
  cin >> D;
  long long TT = 0;
  for (auto i=0; i<N; i++) {
    TT = (TT + K.at(i)) % D;
    mod.at(i) = TT;
  }
  // cerr << D << endl;

  // F[i, j],  count all numbers with i digits (including 0) such that its sum of digits % D =j
  vector< vector<long long> > F( D, vector<long long>(N, 0) );
  for (auto i=0; i < N; i++) {
    for (auto digit=0; digit<=9; digit++) {
      for (auto j=0; j< D; j++) {
        auto target = (digit + j) % D;
        F.at(target).at(i) += ((i>0)?(F.at(j).at(i-1)):((j==0)?1:0)); // 
        F.at(target).at(i) %= MM;
        // cerr << "ftar" << target << " "  << i << " " << F[target][i] << endl;
      }
    }
  }

  reverse(K.begin(), K.end());
  reverse(mod.begin(), mod.end());

  long long myans = 0;
  for (auto i=0; i<N; i++) {
    for (auto digit=0; digit < K.at(i); digit++) {
      auto res = (- (digit +  ((i<N-1)?(mod.at(i+1)):0) ) + 30*D) % D;

      myans = (myans + ((i>0)?(F.at(res).at(i-1)): ((res==0)?1:0)  )   ) % MM;
    }

  }
  cout << (myans + (TT%D ==0)  - 1) % MM  << endl;


  return 0;
}

