    cout<<(Rec()-1+Mod)%Mod;
}

ll Rec(ll i,ll m,bool Equal)
{
    if(i==n)    return m==0;

    if(Dp[i][m][Equal]+1)   return Dp[i][m][Equal];

    ll Res = 0;

    for(ll j = 0 , L = Equal ? s[i] : 9 ; j<=L ; j++ )  Res += Rec(i+1,(m+j)%D,Equal&&s[i]==j);

    return Dp[i][m][Equal] = Res%Mod;
}

