inline int inmod(int aa, int mo) {
	if(aa >= mo) aa %= mo;
	return aa;
}
inline void add(int &aa, int bb, int mo) {
	aa += bb;
	if(aa < Mod) aa += mo;
	if(aa > Mod) aa -= mo;
	return;
}

