		for(reg int j = 0; j < sum; ++j)
			for(reg int k = 0; k <= 9; ++k)
				add(f[1][inmod(j + k, D)], f[0][j], Mod);
		for(reg int k = 0; k <= 9; ++k) {
			if(k <= a[i])
				add(f[1][inmod(sum + k, D)], f[0][sum], Mod);
