ll dp[100005][105][2];
ll n;
ll d;
string s;

ll rec(int pos,int f,int rem)
{
	if(pos == n)
	{
		if(rem==0) return 1;
		else return 0;
	}

	if(dp[pos][rem][f]!=-1)return dp[pos][rem][f];
	else
	{
		dp[pos][rem][f] = 0;
		if(f==0)
		{
			for(int i=0;i<=9;i++)
			{
				int r = (rem + i)%d;
				dp[pos][rem][f] = (dp[pos][rem][f] + rec(pos+1,0,r))%mod;
			}
		}
		else
		{
			int val = s[pos] - '0';
			for(int i=0;i<=val;i++)
			{
				int r = (rem+i)%d;
				if(i < val)
				{
					dp[pos][rem][f] = (dp[pos][rem][f] + rec(pos+1,0,r))%mod;
				}
				else
				{
					dp[pos][rem][f] = (dp[pos][rem][f] + rec(pos+1,1,r))%mod;
				}
			}
		}
	}

	return dp[pos][rem][f];
}

