ll go(int pos, int rem, int tight) {
    if (pos == sz(num)) {
        return !rem;
    }
    if (dp[pos][rem][tight] != -1) return dp[pos][rem][tight];

    int limit = (tight ? num[pos] : 9);
    ll ans = 0;
    for (int i = 0; i <= limit; ++i) {
