	if(memo[pos][sum][limit]!=-1){
		return memo[pos][sum][limit];
	}

	ll num = (int)s[pos]-'0';

	if(limit == true){
		num = 9;
	}

	ll ans = 0;

	rep(i,0,num){
		if(i == (s[pos]-'0')){
			ans = ans + dp(pos+1,(sum + i)% d ,limit);
		}else{
			ans = ans + dp(pos+1,(sum+i)%d , true);

		}

		ans=ans%mod;
	}


	return memo[pos][sum][limit] = ans;

}


