//最大公約数GCD,最小公倍数LCM
// LCMを使うときはGCDをセットで
//検証済み
long long GCD(long long a, long long b) {
	if(a < b) swap(a, b);
	long long d = a % b;
	if(d == 0) {
		return b;
	}
	return GCD(b, d);
}
long long LCM(long long a, long long b) { return (a / GCD(a, b)) * b; }

//素数判定
//素数ならばtrue、素数以外の整数にはfalse
//負数は全てfalse
//検証済み
bool prime(long long N) {
	if(N == 1) {
		return false;
	}
	if(N < 0) return false;
	long long p = sqrt(N);
	for(long long i = 2; i <= p; i++) {
		if(N % i == 0) {
			return false;
		}
	}
	return true;
}

//ユークリッド距離
//検証済み
//位置ベクトル1,位置ベクトル2,ベクトルの次元(2または3が一般的)
double distance(vector<long long> p, vector<long long> q, long long n) {
	double x = 0;
	for(long long i = 0; i < n; i++) {
		x += pow((p.at(i) - q.at(i)), 2);
	}
	return sqrt(x);
}

//配列圧縮(検証済)
//{1,36,1,3,8,-2,-92}を
//{2, 5,2,3,4, 1,  0}にする
void press(vector<long long> &v) {
	long long n = v.size();
	vector<long long> w(n);
	map<long long, long long> m;
	for(auto &p : v) {
		m[p] = 0;
	}
	long long i = 0;
	for(auto &p : m) {
		p.second = i;
		i++;
	}
	for(long long i = 0; i < n; i++) {
		w.at(i) = m[v.at(i)];
	}
	v = w;
	return;
}

//配列のi番目の要素がj番目に小さいとき、j番目の数がiであるベクトルを返す関数
//配列の要素が全て異なるときにしか正常に動作しない
//配列の要素に同じものが含まれても見かけ上動作はするが意味のない値を戻し、
//エラーも起きないので注意
//検証済
//{2,4,1,6,0,3,8,9,5}を
//{4,2,0,5,1,8,3,6,7}にして返す
//"rank"という名前にするとSTLの関数(配列の次元を返す関数)になるので注意
void ranking(vector<long long> &v) {
	long long n = v.size();
	map<long long, long long> m;
	long long i;
	for(i = 0; i < n; i++) {
		m[v.at(i)] = i;
	}
	vector<long long> w(n);
	i = 0;
	for(auto &p : m) {
		v.at(i) = p.second;
		i++;
	}
	return;
}

//部分削除(未検証)
//ベクトルのi番目(i=0,1,2,...,n-1)の要素を削除し、
//以降の要素を全て前に1ずらして参照返し
//ベクトル長は1小さくなって返る
// i>n-1の時は変化しない
void erase(vector<long long> &v, long long i) {
	long long n = v.size();
	if(i > n - 1) return;
	for(long long j = i; j < n - 1; j++) {
		v.at(j) = v.at(j + 1);
	}
	v.pop_back();
	return;
}

//重複削除(未完成)
//引数ベクトルに同一要素が複数あるとき、先頭を残し他は削除
//参照返し
//ベクトル長も変化する
// O(logn)くらい
void unique(vector<long long> &v) {
	long long n = v.size();
	set<long long> s;
	long long i = 0;
	while(i < n) {
		if(s.count(v.at(i))) {
			erase(v, i);
			n--;
		} else {
			s.insert(v.at(i));
			i++;
		}
	}
	return;
}

