ll dp[N][105];
ll func(int c, int sum, int D)
{
	if(c == 0)
		return (sum % D == 0);
	if(dp[c][sum] != -1)
		return dp[c][sum];
	ll res = 0;
	for (int i = 0; i <= 9; ++i)
	{
		res += func(c - 1, (sum + i) % D, D);
	}
	return dp[c][sum] = res;
}
ll solve(string s, int D)
{
	int c;
	ll res = 0, sum = 0, d;
	c = (int) s.size();
	for (int i = 0; i < c; ++i)
	{
		d = s[i] - '0';
		for (int digit = 0; digit < d; ++digit)
		{
			res += func(c - i - 1, (sum + digit) % D, D);
			res %= MOD;
		}
		sum = (sum + d) % D;
	}

	if(sum % D == 0)
		res++;
	return (res - 1);
}
