bool seen[111][MAXN];
int dp[111][MAXN];
int sol(int i, int t, int r) {
    if (i < 0) return r == 0;
    if (seen[r][i] && t == 0) return dp[r][i];
    int ans = 0;
    for (int j = 0, k = t ? di[i] : 9; j<=k; ++j) {
        ans += sol(i-1, j == k && t, (j+r)%d);
        if (ans >= mod) ans -= mod;
    }
    seen[r][i] = t == 0;
    return t ? ans : dp[r][i] = ans;
}

