ll dfs(int ind, int rem) {
    if (ind == -1) return 0;
    ll ret = 0;
    for (int dig = 0; dig < a[ind]; ++dig) {
        ret += dp[ind][rem][dig];
    }
    rem = (rem - a[ind] % d + d) % d;
    return ret + dfs(ind - 1, rem);
