        return memo[match][rem][i];
    int ans = 0;
    for (int d = 0; d <= (match ? (k[i] - '0') : 9); d++) {
        int nmatch = match & (d == (k[i] - '0'));
        int nrem = add(rem, d, x);
        ans = add(ans, dp(nmatch, nrem, i + 1), mod);
    }
    return memo[match][rem][i] = ans;
}

