int check(char c)
{
    return (c - '0');
}

int call(int pos, int sum, int flag)
{
    if (pos == num.size())
    {
        if (sum % D == 0) return 1;
        else return 0;
    }

    if (f[pos][sum][flag] != -1) return f[pos][sum][flag];

    int lim = 9;
    if (flag == 0) lim = check(num[pos]);

    int res = 0;
    for (int i = 0; i <= lim; i++)
    {
        int n_sum = (sum + i) % D;

        int n_flag = flag;
        if (i < lim) n_flag = 1;

        res = (res + call(pos + 1, n_sum, n_flag)) % MOD;
    }

    return f[pos][sum][flag] = res;
}

