ll solve(string k, int &D, int pos, int d, bool tight)
{
	if(dp[pos][d][tight]!=-1)
		return dp[pos][d][tight];

	ll ans=0;
	int ul=(tight)?(k[pos]-'0'):9;
	if(pos==k.length()-1)
	{
		for(int i=0;i<=ul;i++)
			if(i%D==d)
				ans+=1;
		return ans%mod;
	}
	for(int i=0;i<=ul;i++)
	{
		ans= (ans+solve(k,D,pos+1,(D+d-i%D)%D, tight&&(i==ul)))%mod;
	}
	return dp[pos][d][tight] =ans%mod;
}

