    for(int i = 1 ; i <= s.size() ; i++ ) {
        for(int j = 0 ; j < d ; j++ ) {
            for(int k = 0 ; k < 10 ; k++ ) {
                dp[i][j]+=dp[i-1][ok(j-k)];
                dp[i][j]%=mod;
            }
        }
    }
    reverse(s.begin(),s.end());
    long long int car=0, ans=0;
    for(int i = s.size()-1 ; i >= 0 ; i--) {
        for(int j = 0 ; j < s[i]-'0' ; j++) {
