const int mod = 1e9 + 7;
const int N = 10001;
int n;
int x;
string s;
int dp[N][10][2][100];
// f is zero means we can do anything .
// f is not zero means we are limited .
int calc(int pos ,int val , int f , int sum){

	if(pos==n){

		return (sum==0);
	}

	int &ans = dp[pos][val][f][sum];

	if(ans!=-1)
		return ans;

	int lim = 9;

	if(f==1)
		lim = s[pos]-'0';
	ans = 0;
	for(int i = 0 ; i <= lim ; ++i){

		if(f==0)
			ans += calc(pos+1 , i , 0 , (sum+i)%x);
		else if(i==lim && f==1)
			ans += calc(pos + 1 , i , 1 , (sum + i)%x);
		else ans += calc(pos+1 , i , 0 , (sum + i)%x);

		ans >= mod ? ans-=mod : true;
	}

	return ans;

}

void solve(){

	memset(dp , -1 , sizeof dp);

	cin>>s;

	n = s.size();

	cin>>x;


	int ans = calc(0 , 0 , 1 , 0);

	--ans;

	if(ans < 0)
		ans += mod;

	cout<<ans<<endl;
}

signed main(){

    fast;
    int t = 1;
    //cin>>t;
    while(t--)
        solve();
}

