int dp[100001][2];
int solve(int pos,int tight,int sum){

      if(pos == n)
      {
          if(sum%D == 0 && sum>0)
            return 1;
          else
            return 0;
      }

      if(dp[pos][tight]!= -1)
        return dp[pos][tight];

      int res = 0;

      int newtight;
      int lim = (tight)?(k[pos]-'0'):9;

      for(int i = 0;i<=lim;i++)
      {
          newtight = (tight==1 && i==lim)?1:0;

          res = (res+solve(pos+1,newtight,(sum+i)))%m;
      }

      return dp[pos][tight] = res;

}


