int call(bool cmp, int mod, int i)
{
    if(s[i]=='\0'){
        if(mod==0) return 1;
        return 0;
    }
    if(dp[cmp][mod][i]!=-1) return dp[cmp][mod][i];
    dp[cmp][mod][i] = 0;
    int d = 9;
    if(cmp) d = s[i]-'0';
    for(; d>=0; d--){
        if(d<s[i]-'0' || cmp==0) dp[cmp][mod][i] += call(0,(mod+d)%n,i+1);
        else dp[cmp][mod][i] += call(1,(mod+d)%n,i+1);
        if(dp[cmp][mod][i]>=M) dp[cmp][mod][i] -= M;
    }
    return dp[cmp][mod][i];
}

