ll rec(int pos, int sum, int free) {
    ll& res = dp[pos][sum][free];
    if (res == -1) {
        if (pos == N) {
            res = (sum == 0);
        } else if (free) {
            res = 0;
            for (int x = 0; x <= 9; ++x) {
                res += rec(pos + 1, (sum + x) % D, 1);
                res %= mod;
            }
        } else {
            res = rec(pos + 1, (sum + K[pos]) % D, 0);
            for (int x = K[pos] + 1; x <= 9; ++x) {
                res += rec(pos + 1, (sum + x) % D, 1);
                res %= mod;
            }
        }
    }
    return res;
}

