ll DP( ll pos , ll isSmall ,ll isStart, ll mod)
{
    if( pos == lim )
    {
        if(mod == 0 ) return 1;
        else return 0;
    }
    ll &ret = dp[isSmall][isStart][pos][mod];
    if(ret!=-1) return ret ;
    ll ses = isSmall ? 9 : inp[pos];
    ll i ;
    ret = 0 ;
  //  cout<<ret<<endl;
    if( !isStart )
    for ( i = 0 ; i <= ses ; i++ )
    {
        ret += DP( pos + 1 , isSmall | i < inp[pos] ,0, (i + mod)%k);
        ret %= 1000000007;
    }
    else
    {
         for ( i = 1 ; i <= ses ; i++ )
    {
        ret += DP( pos + 1 , isSmall | i < inp[pos] ,0, (i + mod)%k);
        ret %= 1000000007;
    }
    ret += DP( pos + 1 , 1 ,1, 0);
    ret %= 1000000007;
    }
    return ret%1000000007 ;
}

