int modExpo(int a,int b,int c){
	if(b == 0) return 1;
	int answer = 1;
	while(b){
		if(b & 1) answer = ((answer % c) * (a % c)) % c;
		a = ((a % c) * (a % c)) % c;
		b /= 2; 
	}

	return answer;
}

int d;
int dp[10005][105];

int f(string s,int index,int sum,bool flag){
	int n = (int)s.size();
	if(index == n){
		if(sum % d == 0) return 1;
		return 0;
	}

	if(flag == false && dp[index][sum] != -1) return dp[index][sum];

	int limit = 9;
	if(flag) limit = s[index] - '0';

	int ans = 0;
	for(int i = 0; i <= limit; ++i){
		bool newflag = flag;
		if(flag && i == limit) newflag = true;
		else newflag = false;
		ans = ((ans % mod) + f(s,index + 1,(sum + i) % d,newflag) % mod) % mod; 
	}

	if(flag == false) dp[index][sum] = ans; 
	return ans;
}

