int main(){
    string s; cin >> s;
    Int D; cin >> D;
    constexpr Int mod = 1e9 + 7;
    vector<Int>basemod(s.size());
    vector<vector<Int>>dp(s.size(), vector<Int>(D,0));
    vector<vector<bool>>visit(s.size(), vector<bool>(D,false));
    for(Int i = 0; i < basemod.size(); ++i)
        basemod[i] = (i == 0 ? 1 : basemod[i - 1] * 10) % D;
    for(Int i = 1; i < 10; ++i)
        dp.back()[i % D] += 1;
    function<Int(Int,Int)> solve = [&](Int idx,Int tmod){
        Int num = s[idx] - '0';
        if(idx + 1 ==  s.size() or visit[idx][tmod]){
            return dp[idx][tmod];
        } else {
            for(Int tnum = num ; tnum > 0; --tnum){
                Int digit = (s.size() - 1 - idx);
                Int cmd = (tnum * basemod[digit]) % D;
                Int nmod = abs(tmod - cmd);
                dp[idx][tmod] += solve(idx + 1,nmod);
                dp[idx][tmod] %= mod;
            }
        }
        visit[idx][tmod] = true;
        return dp[idx][tmod] ;
    };
    cout << solve(0LL, 0LL) << endl;
    cout << "debug" << endl;
}

