    rep(m, D){
      dp[d+1][0][(m+k_digit)%D] += dp[d][0][m];
      dp[d+1][0][(m+k_digit)%D] %= MOD;
    }

    // exact -> smaller
    // k_digit==0 だと構成できない
    // k_digit>=1 の場合は、0~k_digit-1 を選べる
    rep(i, k_digit){
