ll calc(ll position, bool flag, ll sum)
{
    ll answer = 0;
    ll limit = 9;
    if (flag) limit = arr[position] - '0';
    if (position == length) {
        if (sum % filler == 0) return 1;
        else return 0;
    }

    if (dp[position][flag][sum] != -1) return dp[position][flag][sum];

    for (ll i = 0; i <= limit; i++) {
        if (i < limit || flag == false) {answer += calc(position + 1, false, ((sum +i )% filler));  }
        else if (i == limit) {answer += calc(position + 1, true, ((sum +i)% filler));}
    }
    return dp[position][flag][sum] = answer;
}


