            while(res>=MOD) res-=MOD;
        }
        tmp[0]=0;
        i2=d-1;
        for(int i=0; i<9; ++i){
            tmp[0]+=dp[i2--];
            if(i2<0) i2+=d;
            if(tmp[0]>=MOD) tmp[0]-=MOD;
        }
        for(int i=1; i<d; ++i) tmp[i]=tmp[i-1]+dp[i-1]-dp[++i2%d];
        for(int i=0; i<d; ++i){
            dp[i]=dp[i]+tmp[i];
            if(dp[i]>=MOD){
                dp[i]-=MOD;
                while(dp[i]>=MOD) dp[i]-=MOD;
            }
            else if(dp[i]<0){
                dp[i]+=MOD;
                while(dp[i]<0) dp[i]+=MOD;
            }
        }
    }
    if(--res<0) res+=MOD;
    printf("%d",res);
    return 0;
}

