    int res = 0;
    for(int digit = 0; digit <= s[0]-'0'; ++digit) {
        bool equal = (digit == s[0]-'0');
        res += solve(1, digit%mult, equal);
        res %= mod;
    }
    cout << (res-1+mod)%mod << '\n';
    return 0;
}

