#include <bits/stdc++.h>
using namespace std;

int const M = 1e9 + 7;
vector<int64_t> dp(5500000, -1);
string K; int D;

int add_mod(int x, int y, int M) {
	if ((x += y) >= M) x -= M;
	return x;
}

int count(size_t i, int total, bool upto) {
	if (i == K.size()) return total == 0;

	// 14 bits for index, 7 bits for total, 1 bit for upto
	int64_t key = (i << 9) + (total << 1) + upto;
	if (dp[key] >= 0) return dp[key];

	int sum = 0, leading = K[i] - '0';
	for (int digit = 0; digit <= (upto ? leading : 9); ++digit) {
		// remainder of sum of previous digits and this digit
		int  digit_total = add_mod(total, digit, D);
		// if this digit is the leading digit pass in upto, else false
		bool digit_upto  = (digit == leading) & upto;
		sum = add_mod(sum, count(i+1, digit_total, digit_upto), M);
	}

	return dp[key] = sum;
}

int main() {
	ios_base::sync_with_stdio(false);

	getline(cin, K);
	cin >> D;

	cout << (count(0, 0, true) - 1) % M << endl;
}

