ll solve(string k, int m) {
    clear();
    for (int i = 1; i < 10; i++) {
        if (k[0] - '0' > i) {
            dp[0][i][i % m][0] = 1;
        } else if (k[0] - '0' == i) {
            dp[0][i][i % m][1] = 1;
        }
    }
    for (int i = 1; i < k.size(); i++) {
        for (int d = 0; d < 10; d++) {
            for (int ld = 0; ld < 10; ld++) {
                for (int ost = 0; ost < m; ost++) {
                    if (k[i] - '0' > d) {
                        dp[i][d][(ost + d) % m][0] = (dp[i][d][(ost + d) % m][0] + dp[i - 1][ld][ost][0] + dp[i - 1][ld][ost][1]) % mod;
                    } else if (k[i] - '0' == d) {
                        dp[i][d][(ost + d) % m][0] = (dp[i][d][(ost + d) % m][0] + dp[i - 1][ld][ost][0]) % mod;
                        dp[i][d][(ost + d) % m][1] = (dp[i][d][(ost + d) % m][1] + dp[i - 1][ld][ost][1]) % mod;
                    } else {
                        dp[i][d][(ost + d) % m][0] = (dp[i][d][(ost + d) % m][0] + dp[i - 1][ld][ost][0]) % mod;
                    }
                }
            }
        }
    }
    ll ans = 0;
    for (int i = 0; i < 10; i++) {
        ans = (ans + dp[k.size() - 1][i][0][0] + dp[k.size() - 1][i][0][1]) % mod;
    }
    return ans;
}

