ll solve(int pos, bool flag, int sum)
{
    if(pos==k.length())
        return sum==0;
    if(dp[pos][flag][sum]!=-1)
        return dp[pos][flag][sum];
    int limit = (flag)?(k[pos]-'0'):9;
