ll calc(string str,int pos,int d,int tight,int sum){
    if(pos==(int)str.length()){
        if(sum==0) return 1;
        else return 0;
    }
    if(dp[pos][sum][tight]!=-1) return dp[pos][sum][tight];
    ll res=0;
