int rec(int dgt,int isless,int d)
{
	if(dgt==K.length())
		return d==0;

	if(dp[dgt][isless][d]!=-1)
		return dp[dgt][isless][d];

	int res=0;
	int maxnd;
	if(isless)maxnd=9;
	else maxnd=K[dgt]-'0';
	for(int nd=0;nd<=maxnd;nd++)
	{
		int nisless;
		if(isless==1 || nd<maxnd)nisless=1;
		else nisless=0;
		res+=rec(dgt+1,nisless,(d+nd)%D);
		res%=mod;
	}

	dp[dgt][isless][d]=res;
	return res;
}

