string s;
ll k,n;
ll getSum(ll pos,ll mod,bool flag)
{
	if(dp[pos][flag][mod]!=-1)
		return dp[pos][flag][mod];
	if(pos>=n)
	{
		if(mod==0)
			return 1;
		return 0;
	}
	int lim=9;
	if(!flag)
		lim=s[pos]-'0';
	ll ans=0;
	for(int i=0;i<=lim;i++)
	{
		if(flag || i<lim)
			ans=(ans%MOD+getSum(pos+1,(mod+i)%k,true)%MOD)%MOD;
		else
			ans=(ans%MOD+getSum(pos+1,(mod+i)%k,false)%MOD)%MOD;
	}
	return dp[pos][flag][mod]=ans;
}
void solve()
{
	cin>>s;
	cin>>k;
	n=s.length();
	memset(dp,-1,sizeof(dp));
	ll ans=(getSum(0,0,0)-1)%MOD;
	cout<<ans<<"\n";
}



