ll fn(ll i, ll f, ll sum) { 
  if(i == n) {
    return !sum;
  }
  ll &res = dp[i][f][sum];
  if(res != -1) return res;
  res = 0;
  ll curdig = s[i] - 48;
  for(ll dig = 0; dig <= 9; dig++) {
    if(!f && dig > curdig) 
      break;
    res += fn(i + 1, f | (dig < curdig), (sum + dig) % d);
    if(res >= mod) 
      res -= mod;
  }
  return res;
}

