		for (int put = 0; put < 10; put++) {
			dp[l & 1][(i + put) % d] += dp[l & 1 ^ 1][i];
			if (dp[l & 1][(i + put) % d] >= md)
				dp[l & 1][(i + put) % d] -= md;
		}
