    cin >> K >> D;
    N = K.size();
  }

  ll rec(int i, int smaller, int r) {
    ll *cur = &dp[i][smaller][r];
    if(*cur >= 0) return *cur;
    if(i >= N) return *cur = (r == 0);
    int d = K[i] - '0';
    int ub = smaller ? 9 : d;
