int DP(int pos, int low, int sum) {
	if (pos == s.size()) return sum == 0;
	int &ret = memo[pos][low][sum];
	if (ret != -1) return ret;
	ret = 0;
	if (low) {
		for (int i = 0; i <= 9; ++i) {
			ret = (ret + DP(pos + 1, 1, (sum + i) % D)) % MOD;
		}
	} else {
		int d = s[pos] - '0';
		for (int i = 0; i <= d; ++i) {
			ret = (ret + DP(pos + 1, i < d? 1 : 0, (sum + i) % D)) % MOD;
		}
	}
	return ret;
}

