                    if (k == 0 && l > s[i] - '0') break;

                    if (k == 1 || l < s[i] - '0') {
                        dp[i + 1][(j + l) % d][1] += dp[i][j][k];
                        if (dp[i + 1][(j + l) % d][1] >= mod) dp[i + 1][(j + l) % d][1] -= mod;
                    } else {
                        dp[i + 1][(j + l) % d][0] += dp[i][j][k];
                        if (dp[i + 1][(j + l) % d][0] >= mod) dp[i + 1][(j + l) % d][0] -= mod;
                    }
                }
            }
        }
    }

    ans = dp[n][0][0] + dp[n][0][1] - 1;
    while (ans < 0) ans += mod;
    while (ans >= mod) ans -= mod;

    printf("%lld\n", ans);
    return 0;
}

