LL ans = 0LL;
LL dp[10004][102][2];
int D;
LL f(string &target, int i, int d = 0, int less = 0) {
	if (i == -1) {
		if (d%D == 0)return 1;
		else return 0;
	}

	if (dp[i][d][less] != -1 && less == 1)return dp[i][d][less];
	LL res = 0;
	int num = target[i] - '0';
	int Max = less ? 9 : num;
	FOR(nx, 0, Max + 1) {
		res += f(target, i - 1, (d + nx) % D, less || (nx<Max)) % MOD;
	}
	if (less == 1)
		return  (dp[i][d][less] = (res%MOD));
	return res;
}


