ll dp() {
    vector<int> nums;
    ll cnt = 0;
    ll last = 0; // 前缀信息；
    for(int i = num.size() - 1; i >= 0; i --) nums.push_back(num[i] - '0');
    for(int i = num.size() - 1; i >= 0; i --) {
        int curr = nums[i]; //当前位；
        if(curr > 0) {
            for(int digit = 0; digit < curr; digit ++) {
                cnt += f[i][(10*d - digit - last) % d];
                cnt %= mod;
            }
        }
        last += curr;
        last %= d;
    }
    if(last % d == 0) cnt ++;
    return cnt % mod;
}

