int main() {
    string N; cin>>N;
    ll D; cin>>D;

    //[決めた桁][未満フラグ,未満のとき1][]
    const ll modd_max=D+1;
    vector<vector<vector<ll>>> dp(N.size()+1, vector<vector<ll>>(2,vector<ll>(modd_max)));

