          Add(dp[digit+1][smaller || num < lim][(modD + num) % D], dp[digit][smaller][modD]);
        }
      }
    }
  }

  int ans = 0;
  for (int smaller : {0, 1}) {
    Add(ans, dp[n][smaller][0]);
  }
  Add(ans, -1LL);

  cout << ans << endl;

  return 0;
}

