const int MaxN = 100005;
const int Mod = 1000000007;

int n, D;
string s;
int dp[MaxN][2], tmp[MaxN][2];

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cin >> s;
    cin >> D;
    n = s.size();
    dp[s[0] - '0'][1] = 1;
    for (int i = s[0] - '0' - 1; i >= 0; i--)
    {
        dp[i][0] = 1;
    }
    int Sum = s[0] - '0';
    for (int i = 1; i < n; i++)
    {
        int x = s[i] - '0';
        for (int k = 0; k <= Sum; k++)
        {
            for (int l = 0; l < 2; l++)
            {
                if (dp[k][l] != 0)
                {
                    if (l == 0)
                    {
                        for (int t = 0; t <= 9; t++)
                        {
                            tmp[t + k][0] = (tmp[t + k][0] + dp[k][0]) % Mod;
                        }
                    }
                    else
                    {
                        for (int t = 0; t < x; t++)
                        {
                            tmp[t + k][0] = (tmp[t + k][0] + dp[k][1]) % Mod;
                        }
                        tmp[x + k][1] = (tmp[x + k][1] + dp[k][l]) % Mod;
                    }
                }
            }
        }
        Sum += 9;
        for (int k = 0; k <= Sum; k++)
        {
            for (int l = 0; l < 2; l++)
            {
                dp[k][l] = tmp[k][l];
                tmp[k][l] = 0;
            }
        }
    }
    int ans = 0;
    for (int k = D; k <= Sum; k += D)
    {
        for (int l = 0; l < 2; l++)
        {
            ans = (ans + dp[k][l]) % Mod;
        }
    }
    cout << ans;
    return 0;
}

