int dp[1004][105][2];

int solve(string k, int d, int pos, int rem, int tight) {

	if (dp[pos][rem][tight] != -1)	return dp[pos][rem][tight];

	int up = (tight) ? k[pos] - '0' : 9;
	int ans = 0;

	if (pos == k.length() - 1) {
		for (int i = 0; i <= up; i++) {
			if (rem == i % d)	ans++;
		}
		return dp[pos][rem][tight] = ans;
	}

	for (int i = 0; i <= up; i++) {
		ans += solve(k, d, pos + 1, (d + rem - i) % d, (tight and (i == k[pos] - '0')));
		ans %= mod;
	}
	return dp[pos][rem][tight] = ans;
}

