int rec(int i, int j, int f) {
    if(i == n) return !j;

    int& ans = dp[i][j][f];

    if(ans != -1) return ans;

    ans = 0;

    int st = 0, ed = f ? 9 : v[i];
    for(int d = st; d <= ed; d++) {
        int nj, nf;
        nj = (j + d) % m;
        nf = f | (d < v[i]);
        ans = add(ans, rec(i+1, nj, nf));
    }

    return ans;
}

