ll rec(int digit, int can_use_any_number, int remain){
  if (digit == -1){
    if (can_use_any_number){
      return 0;
    }
    else{
      return remain == 0 ? 1 : 0;
    }
  }
  if (dp[digit][can_use_any_number][remain] != -1){
    return dp[digit][can_use_any_number][remain];
  }

