string s;
int D;
ll memo[100010][2][101];
ll recu(int i, int ti,int v) {

	if (i >= s.size() ) {
		if (v == 0) {

			return 1;
		}
		else
		{
			return 0;
		}
	}
	if (~memo[i][ti][v]) return memo[i][ti][v];
	ll *res = &memo[i][ti][v];
	*res = 0;
	if (ti) {
		int c = s[i] - '0';
		*res += recu(i + 1, ti, (v + c) % D);
		for (ll j = c - 1; j >= 0 ; j--)
		{
			ll next = v + j;
			next %= D;
			*res += recu(i + 1, 0, next);
			*res %= INF;
		}
	}
	else {

		for (ll j = 0; j < 10; j++)
		{
			ll next = v + j;
			next %= D;
			*res += recu(i + 1, ti, next);
			*res %= INF;
		}

	}

	return *res;
}

void solv() {

	cin >> s;
	cin >> D;
	memset(memo, -1, sizeof(memo));
	ll r = recu(0, 1, 0);
	r += INF;
	r--;
	r %= INF;
	cout << r << endl;
}


