template< int64_t mod >
struct mInt {
    int64_t x;

    mInt() : x(0LL) {}
    mInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}
    mInt &operator+=(const mInt &p) {
        if ((x += p.x) >= mod) x -= mod;
        return *this;
    }
    mInt &operator-=(const mInt &p) {
        if ((x += mod - p.x) >= mod) x -= mod;
        return *this;
    }
    mInt &operator*=(const mInt &p) {
        x = (x * p.x % mod);
        return *this;
    }
    mInt &operator/=(const mInt &p) {
        *this *= p.inverse();
        return *this;
    }
    mInt operator-() const { return mInt(-x); }
    mInt operator+(const mInt &p) const { return mInt(*this) += p; }
    mInt operator-(const mInt &p) const { return mInt(*this) -= p; }
    mInt operator*(const mInt &p) const { return mInt(*this) *= p; }
    mInt operator/(const mInt &p) const { return mInt(*this) /= p; }
    bool operator==(const mInt &p) const { return x == p.x; }
    bool operator!=(const mInt &p) const { return x != p.x; }
    mInt inverse() const {
        int64_t a = x, b = mod, u = 1, v = 0, t;
        while (b > 0) {
            t = a / b;
            swap(a -= t * b, b);
            swap(u -= t * v, v);
        }
        return mInt(u);
    }
    mInt pow(int64_t n) const {
        mInt ret(1), mul(x);
        while (n > 0) {
            if (n & 1) ret *= mul;
            mul *= mul;
            n >>= 1;
        }
        return ret;
    }
    friend ostream &operator<<(ostream &os, const mInt &p) {
        return os << p.x;
    }
    friend istream &operator>>(istream &is, mInt &a) {
        int64_t t;
        is >> t;
        a = mInt< mod >(t);
        return (is);
    }
    static int get_mod() { return mod; }
};
using mint = mInt< MOD >;

string K;
int D;
int n;
ll dp[10005][105][2];

mint rec(int k, int l, bool f) { //f = trueならばKより小さいことが確定している
    if (k == n) {
        if (l == 0) return 1;
        else return 0;
    }
    if (dp[k][l][f] != -1) return dp[k][l][f];
    mint res = 0;
    if (f) {
        rep(i, 10) res += rec(k + 1, (l + i) % D, true);
    }
    else {
        int t = K[k] - '0';
        rep(i, t) res +=  rec(k + 1, (l + i) % D, true);
        res += rec(k + 1, (l + t) % D, false);
    }

    dp[k][l][f] = res.x;
    return res;
}

