int g(string str,int pos,int sum,int tight,int d)
{
    if(pos==str.length())
    {
        if(sum%d==0)
            return 1;
        return 0;
    }
    else if(dp[pos][sum][tight]!=-1)
        return dp[pos][sum][tight];
    else if(tight==1)
    {
        int res=0;
        for(int i=0; i<=str[pos]-'0'; i++)
        {
            if(i==str[pos]-'0')
            {
                res+=(g(str,pos+1,(sum+i)%d,1,d))%MOD;
                res=res%MOD;
            }
            else
            {
                res+=(g(str,pos+1,(sum+i)%d,0,d))%MOD;
                res=res%MOD;
            }
        }
        dp[pos][sum][tight]=res%MOD;
        return res%MOD;
    }
    else
    {
        int res=0;
        for(int i=0; i<=9; i++)
        {
            res+=(g(str,pos+1,(sum+i)%d,0,d))%MOD;
            res=res%MOD;
        }
        dp[pos][sum][tight]=res%MOD;
        return res%MOD;
    }
}

