    ll D; cin >> D;
    ll N = S.size();

    if(N <= 7){
        ll cnt = 0;
        for(int i = 1; i <= stoll(S); i++){
            if(digsum(i) % D == 0) cnt++;
        }
        cout << cnt%MOD << endl;
        return 0;
    }
    vector<vector<vector<ll>>> DP(N, vector<vector<ll>>(10, vector<ll>(D)));
    vector<vector<ll>> SUM(N, vector<ll>(D));

    for(int i = 0; i <= 9; i++) {
        DP[0][i][i%D]++;
        SUM[0][i%D]++;
    }

    // 下からi桁目の数がjの時のdigsumが k (mod D)
    for(int i = 1; i < N; i++) {
        for(int j = 0; j < 10; j++){
            for(int k = 0; k < D; k++){
                DP[i][j][(j+k)%D] = SUM[i-1][k]%MOD;
                SUM[i][(j+k)%D] += SUM[i-1][k]%MOD;
                DP[i][j][(j+k)%D]%=MOD;
                SUM[i][(j+k)%D]%=MOD;
            }
        }
    }
    ll ans = SUM[N-2][0];
