ll k;
ll dp[104][10][102];
ll solve(ll z,ll d,ll m)
{
    m=m%k;
    if(dp[z][d][m]!=-1)
        return dp[z][d][m];
    if(z==0&&d==0)
    {
        return 0;
    }
    if(z==0)
    {
        ll ans=solve(z,d-1,m);
        if(d%k==m)
            ans++;
        ans%=hell;
        dp[z][d][m]=ans;
        return dp[z][d][m];
    }
    if(d==0)
    {
        ll ans=0;
        for(ll i=0;i<z;i++)
        {
            ans=(ans+solve(i,9,(m-(9*(z-1-i))%k+k)%k));
        }
        dp[z][d][m]=ans;
        return ans;
    }
    ll ans=0;
    if(d!=1)
        ans=solve(z,d-1,m);
    ans=(ans+solve(z,0,(m-(d-1)%k+k)%k))%hell;
    if(d%k==m)
        ans=(ans+1)%hell;
    dp[z][d][m]=ans;
    return ans;
}
