int fun(int idx,int cur,bool gr)
{
    if(idx==s.size()) return !cur;
    int &ret=dp[idx][cur][gr];
    if(~ret)
        return ret;
        ret=0;
    if(!gr)
    {
        for(int i=0;i<s[idx]-'0';i++)
            ret+=fun(idx+1,(cur+i)%d,1)%mod;
        ret+=fun(idx+1,(cur+s[idx]-'0')%d,0)%mod;
    }
    else
    {
        for(int i=0;i<=9;i++)
            ret+=fun(idx+1,(cur+i)%d,1)%mod;
    }
    ret%=mod;
    return ret;
}
