long long bp(long long a, long long p, long long mod) {
    if (p == 0) {
        return 1ll;
    } else if (p % 2 == 1) {
        return bp(a, p - 1, mod) * a % mod;
    } else {
        long long res = bp(a, p / 2, mod);
        return res * res % mod;
    }
}

