ll DFS(int pos,int v,bool lim){
	if(pos==len+1){
		return dp[pos][v]=(v==0);
	}
	if(!lim&&dp[pos][v]!=-1){
		return dp[pos][v];
	}
	int Lim=lim?a[pos]:9;
	ll res=0;
	for(int i=0;i<=Lim;++i){
		res+=DFS(pos+1,(v+i)%d,lim&&(i==Lim));
		if(res>=mod){
			res-=mod;
		}
	}
	if(!lim){
		dp[pos][v]=res;
	}
	return res;
}
