constexpr LL mod = 1e9 + 7;

string K;
LL D;

LL dp[100010][2][110];

LL f(LL k = 0, bool tight = true, LL sum = 0) {
    if (K.size() == k)return sum == 0;
    int x = K[k] - '0';
    int r = tight ? x : 9;
    LL &res = dp[k][tight][sum];
    if (~res) return res;
    res = 0;
    for (int i = 0; i <= r; i++) {
        res += f(k + 1, tight && i == r, (sum + i) % D);
        res %= mod;
    }
    return res;
}

int main() {

    cin >> K >> D;

    memset(dp, -1, sizeof(dp));

    cout << (f() - 1 + mod) % mod;

    return 0;
}

