    if (ret != -1) return ret;
    ret = 0;
    int lim = 9;
    if (!smaller) lim = s[pos] - '0';
    for (int i = 0; i <= lim; ++i) ret = (ret + solve(pos + 1, (rem + i) % d, max(smaller, (i < lim) ) ) ) % mod;
    return ret;
}

