        for (int j = 0; j < 105; j++) {
            for (int k = 0; k < 2; k++) {
                dp[i][j][k] = -1;
            }
        }
    }

    int ans = solve(0, 0, 1);

    cout << (ans - 1) % MOD; // remove the number 0

    return 0;
}

