template<typename T>
vector<vector<T>> shrink(vector<vector<vector<T>>>v){
    vector<vector<T>>res(v[0].size(),vector<T>(v[0][0].size()));
    for(int i=0;i<(int)v.size();i++){
        for(int j=0;j<(int)v[i].size();j++)for(int k=0;k<(int)v[i][j].size();k++){
            res[j][k]+=v[i][j][k];
        }
    }
    return res;
}
