template<typename T>
vector<vector<vector<T>>> mul(vector<vector<vector<T>>>s,vector<vector<vector<T>>>t){
    vector<vector<vector<T>>>res(s.size(),vector<vector<T>>(s[0].size()*t[0].size(),vector<T>(s[0][0].size()*t[0][0].size())));
    for(int i=0;i<(int)s.size();i++){
        for(int j=0;j<(int)s[i].size();j++)for(int k=0;k<(int)s[i][j].size();k++){
            for(int p=0;p<(int)t[i].size();p++)for(int q=0;q<(int)t[i][p].size();q++){
                res[i][j*t[i].size()+p][k*t[i][p].size()+q]+=s[i][j][k]*t[i][p][q];
            }
        }
    }
    return res;
}

