int generate_top_down( string num, int idx, int sum, int D, int bound ){
	if( idx == SIZE ) return ( sum%D == 0 )? 1 : 0 ;
	int check = dp[idx][sum][bound] ;
	if( check != -1 ) return check ;
	int up_to = 9 ;
