		return dp[c][sum];
	ll res = 0;
	for (int i = 0; i <= 9; ++i)
	{
		res += func(c - 1, (sum + i) % D, D);
		res %= MOD;
	}
	return dp[c][sum] = res;
}
ll solve(string s, int D)
{
