			else if (k[pos] - '0' == i) {
				sek = (d - i) % D;
				if (sek >= 0) ret = (ret + rek(pos + 1, sek, 1)) % MOD; 
				else ret = (ret + rek(pos + 1, sek + D, 1)) % MOD;
			}
			else {
				sek = (d - i) % D;
				if (sek >= 0) ret = (ret + rek(pos + 1, sek, 0)) % MOD; 
				else ret = (ret + rek(pos + 1, sek + D, 0)) % MOD;
			}
		}
	}
	return ret;
}

