vector<vector<RCR>> dp;

RCR solve(const string& S, const int & D, int i = 0, int d = 0, bool ok = false){
    while(d < 0) d += D;
    if(i >= S.size()) return d == 0;
    if(ok){
        if(dp[i][d] != 0) return dp[i][d];
        else{
            for (int j = 0; j < 10; ++j) {
                dp[i][d] += solve(S, D, i+1, d-j, true);
            } // end j
            return dp[i][d];
        }
    }
    else{
        RCR ret = 0;
        for (int j = 0; j < S[i] - '0'; ++j) {
            ret += solve(S, D, i+1, d-j, true);
        } // end j
        return ret + solve(S, D, i+1, d-S[i] + '0', false);
    }
}

void sub_main(istream &is) {
    string K;
    ll D;
    is >> K >>  D;
    if(!is) return;

    dp.clear();
    dp.resize(K.size(), vector<RCR>(D, 0));
    RCR sum = solve(K, D);

    cout << sum - 1 << endl;

}

