        int r = (j + k) % d;
        dp[i + 1][r][1] += dp[i][j][1];
        dp[i + 1][r][1] %= MOD;
        // border
        if (k == nd) {
            dp[i + 1][r][0] += dp[i][j][0];
            dp[i + 1][r][0] %= MOD;
        }
        // under
        if (k < nd) {
            dp[i + 1][r][1] += dp[i][j][0];
            dp[i + 1][r][1] %= MOD;
        }
    }
    // REP(i, n + 1) {
    //     cout << i << ": " << endl;
    //     printvv(dp[i]);
    // }

    // 0 の分がカウントされているので1引く
    ll ans = dp[n][0][0] + dp[n][0][1] - 1;
    if (ans < 0) ans += MOD;
    cout << ans << endl;
}

