int get_digit(int x)
{
    fill(num,num+20,0);
    int n=0;
    stack <int> s;
    while (x!=0)
    {
        s.push(x%10);
        x/=10;
    }
    while (!s.empty())
    {
        num[++n]=s.top();
        s.pop();
    }
    return n;
}
long long solve(int idx, int sum, int tight)
{
    if (idx==n+1)
        if (sum%k==0)
            return 1;
        else
            return 0;
    if (dp[idx][sum][tight]!=-1)
        return dp[idx][sum][tight];
    long long res=0;
    int limit;
    if (tight==0)
