    for (int i=0; i<=limit; i++)
    {
        int new_tight=1;
        if (i==limit&&tight==0)
            new_tight=0;
        res+=solve(idx+1,sum+i,new_tight);
    }
    dp[idx][sum][tight]=(res%MOD);
    return res;
}
