        for_(i,range+1)
        {   int newRem = (rem+i%d)%d;
            int newFlag= ((!flag && (k[len-1-indx]-'0')>i )|| flag )? 1: 0;;
            val= (val + solve(indx-1,newRem,newFlag))%mod;
        }
        dp[indx][rem][flag] = val;
        return dp[indx][rem][flag];
