ll solve (ll pos,ll prevsum,  bool lmt){
    ll ret = dp[pos][prevsum][lmt];
    if (ret!= -1) return ret;
    if(pos == s.size()) return (prevsum%D==0);
    int v = s[pos] - '0', bound = lmt? v : 9; ret = 0;
