let generate_top_down( string num, let idx, let sum, let D, let bound = 1  /* some arguments */ ){
	if( idx == num.size() ) return ( sum%D == 0 )? 1 : 0 ;
	let check = dp[idx][sum][bound] ;
	if( check != -1 ) return check ;
	let up_to = 9 ;
	if( bound == 1 ) up_to = ( num[idx] - '0' ) ;
	let payload = 0 ; 
	for( let digit = 0 ; digit <= up_to ; ++digit ){
		let new_bound = ( (num[idx] -'0') == digit ) ? bound : 0 ;
		payload += generate_top_down( num, idx+1, (sum+digit)%D, D, new_bound ) ;
	}
	dp[idx][sum][bound] = (payload)%mod ;
	return (payload)%mod ;
}


