    if (rest == 1) md = K[ind] - '0';
    for (int i = 0; i < md; i++) {
        ans = (ans + solve(ind + 1, (s + i) % D, 0)) % MOD;
    }
    if (rest == 0) {
        ans = (ans + solve(ind + 1, (s + 9) % D, 0)) % MOD;
    } else {
        ans = (ans + solve(ind + 1, (s + md) % D, 1)) % MOD;
    }
    dp[ind][s][rest] = (int)ans;
    return (int)ans;
}

int main() {
