long long getsum(int id, int sum, int tight){
    if(id == -1)
        return (sum == 0) ? 1 : 0;
    if(dp[id][sum][tight] > -1 && tight == 0)
        return dp[id][sum][tight];
    long long res = 0, k1 = (tight == 0) ? 9 : digit[id];
