int rec(int n,int sum,int tight)
{
    if(n==-1)
    {
        if(sum==0)
            return 1;
        else
            return 0;
    }

    if(dp[n][sum][tight]!=-1)
        return dp[n][sum][tight];

    int k=9;
    if(tight)
        k=s[n]-'0';

