int dfs(int pos,int sum,bool lim){
    if(pos==0) return sum==0;
    if(!lim&&dp[sum][pos]!=-1) return dp[sum][pos];
    int t=lim?num[pos]:9;
    int re=0;
    for(int i=0;i<=t;i++){
        re+=dfs(pos-1,(sum+i)%D,lim&&(i==t));
        re%=mod;
    }
    if(!lim) dp[sum][pos]=re;
    return re;
}

