//state 0 for equal numbers
//1 for smaller
//2 for bigger

int go(int idx , int sta , int sum){
    if(idx == s.size()){
        return sum == 0 && (sta == 0 || sta == 1);
    }
    if(~mem[idx][sta][sum])
        return mem[idx][sta][sum];
    int ways = (sum == 0) && (idx != 0);
    for(int i = ((idx == 0) ? 1 : 0); i <= 9; i++){
        //if(sta == 1){
         //  add_self(ways , go(idx + 1 , 1 , (sum + i) % n));
        //}
        int new_sta = 0;
