            new_sta = 2;
        } else if( (sta == 0 && s[idx] - '0' > i) || sta == 1 ){
            new_sta = 1;
        }
        add_self(ways , go(idx + 1 , new_sta , (sum + i) % n));
    }
    return mem[idx][sta][sum] = ways;
}

