int memo[N][D][2][2];

int DP(int pos, int res, bool menor, bool valid){
	if(pos == n){
		return res == 0 and valid;
	}
	if(vis[pos][res][menor][valid]) return memo[pos][res][menor][valid];
	int ans = 0;
	if(menor){
		for(int i=0; i<10; i++){
			bool nxt_valid = valid || (i > 0);
			ans = add(ans,DP(pos+1,add(res,i,d),true,nxt_valid));
		}
	}
	else{
		for(int i=0; i<=s[pos]-'0'; i++){
			bool nxt_valid = valid || (i > 0);
			ans = add(ans,DP(pos+1,add(res,i,d),i < s[pos]-'0',nxt_valid));
		}
	}
	vis[pos][res][menor][valid] = true;
	return memo[pos][res][menor][valid] = ans;
}

