int dp[1001][101][2];

int numbers(int pos,int d,string &str,int D,int tight)
{
    int ub=(tight==1?str[pos]-48:9);
    if(pos==str.length()-1)
    {
        // jab hum last diggit pr hain in that case s and x will be same......
        // kyunki sirf last vali digit he placed nhi hui hai....

        int ans=0;
        for(int x=0;x<=ub;x++)
        {
            if(x%D==d)
            {
                ans++;
            }
        }
        return dp[pos][d][tight]=ans;
    }
    else
    {
        if(dp[pos][d][tight]!=-1)
        {
            return dp[pos][d][tight];
        }
        int ans=0;
        for(int x=0;x<=ub;x++)
        {
            ans=(ans%p+numbers(pos+1,(D+d-x%D)%D,str,D,tight&(x==ub))%p)%p;
        }
        return dp[pos][d][tight]=ans;

    }
}

