inline ll solve(int pos, int cnt, bool tight = false)
{
    if (pos == str.size())
    {
        if (!(cnt % d))
            return 1;
        return 0;
    }

    if (dp[pos][cnt][tight] != -1)
        return dp[pos][cnt][tight];

    ll res = 0;
    int x = (int) (str[pos] - '0');
    int lmt;
    if (tight)
        lmt = 9;
    else
        lmt = x;

    for (int i = 0; i <= lmt; i++)
    {
        int new_bool = tight;
        int new_cnt = cnt % d;
        if (!tight && i < lmt)
            new_bool = true;
        new_cnt = (i + new_cnt) % d;
        res = (res + solve(pos + 1, new_cnt, new_bool)) % mod;
    }

    return dp[pos][cnt][tight] = res;
}


