long long dgtdp(int k, bool t, int md, int& d, string& s, vector<vector<vector<long long>>>& memo) {
	if (memo[k][t][md] != -1) return memo[k][t][md];
	if (k == s.size()) return md == 0;
	int x = s[k]-'0';
