  dp[0][0] = 1;
  for (int i = 0; i < (int) s.length(); i++){
    vector<vector<ll>> new_dp (D , vector<ll> (2 , 0));
    for (int re = 0; re < D; re++){
      for (int taken = 0; taken < 2; taken++){
        int  foo = s[i] - '0';
