    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> K >> D;
    n = K.size();
    memset(dp, -1, sizeof dp);
    ll result = solve(true, 0, 0) - 1;
    if (result < 0)
        result += MOD;
    cout << result << endl;
}

