const int M = 1e4+1;
int D, n;
string K;

int dp[M][2][101];

int recurse(int pos, int tight, int sum){
	if (pos == n){
		return ((sum == 0) ? 1 : 0);
	}
	if (dp[pos][tight][sum] != -1){
		return dp[pos][tight][sum];
	}

	int ans = 0;

	int up = (tight ? (K[pos] - '0') : 9);
	for (int d = 0; d <= up; d++){
		ans = (ans + recurse(pos+1, (tight && !(d < K[pos] - '0')), (sum + d) % D)) % MOD;
	} 

	return (dp[pos][tight][sum] = ans);
}


