ll go ( ll i , ll rem = 0 , ll gr = 0 ){

    if ( i < 0 ){
        return mod(rem , d) == 0 && gr == 0;
    }

    ll& ret = dp[i][rem][gr];
    if ( ~ret ) return ret;

    ll ans = 0;
    for ( int digit = 0; digit < 10; ++digit ){
        if ( digit <  s[i] - '0' ){
            ans += go( i-1 , (rem+digit)%d , 0  );
        }
        if ( digit == s[i] - '0' ){
            ans += go( i-1 , (rem+digit)%d , gr );
        }
        if ( digit > s[i] - '0' ){
            ans += go( i-1 , (rem+digit)%d , 1  );
        }
        ans %= MOD;
    }
    return ret = (ans%MOD);
}

