llt dfs(int x, int d, int lim) {
  if (x > N) {
    if (d == 0) return 1;
    else return 0;
  }
  if (dp[x][d][lim] != 0) return dp[x][d][lim];

  if (lim == 0) {
    for (int i = 0; i <= 9; ++i) {
      int s = (d + i) % D;
