      int s = (d + i) % D;
      dp[x][d][lim] = (dp[x][d][lim] + dfs(x + 1, s, 0)) % Mod;
    }
    int s = (d + A[x]) % D;
    dp[x][d][lim] = (dp[x][d][lim] + dfs(x + 1, s, 1)) % Mod;
  }
  return dp[x][d][lim];
}

