int memo[2][D][N];

int dp(int at, int md, bool bounded) {
    if(at == n) return md == 0;
    int &ans = memo[bounded][md][at];
    if(ans != -1) return ans;
    ans = 0;
    int mx = bounded ? s[at]-'0' : 9;
    for(int i = 0; i <= mx; ++i) {
        ans += dp(at + 1, (md + i) % d, bounded && i == mx);
        ans %= mod;
    }
    return ans;
}

