        DP[0][i][0] = 1;

    for(int i = 1;i <= N;i++){

        ///DP[i][d][r] -> poniendo el digito d en la posicion i en cuantos numeros la suma de sus digitos es = r;
        for(int d = 0;d < 10;d++){
            for(int r = 0;r < D;r++){
                int newr = (r - (d % D) + D) % D;
                sum(DP[i][d][r],DP[i - 1][9][newr]);
            }
        }

        ///acumular la dinamica para todos los digitos con distancia r
        for(int d = 1;d < 10;d++){
