ll f(string &s, int D) {
    vll dp(D);
    int prev = s[0] - '0';
    for (int d = 1; d < prev; d++) {
        dp[d % D] = 1;
    }

    prev %= D;
    for (int i = 1; i < s.size(); i++) {
        int di = s[i] - '0'; 
        vll new_dp(D);
        for (int d = 0; d < 10; d++) {
            if (d) (++new_dp[d % D]) %= MOD;
            for (int j = 0; j < D; j++) {
                (new_dp[(j + d) % D] += dp[j]) %= MOD;
            }
            if (d < di) (++new_dp[(prev + d) % D]) %= MOD;
        }
        swap(dp, new_dp);
        (prev += di) %= D;
    }
    if (!prev) (++dp[0]) % MOD;
    return dp[0];
}

int g(int n) {
    int res = 0;
    while (n) res += n % 10, n /= 10;
    return res;
}

ll brute(string &s, int D) {
    int n = stoi(s);
    int res = 0;
    for (int i = 1; i <= n; i++) {
        res += g(i) % D == 0;
    }
    return res;
}

