ll recur(ll ind,ll rem,ll check){
	if(ind==k.size() && rem==0){return 1;}
	if(ind==k.size())return 0;
	if(dp[ind][rem][check]!=-1)return dp[ind][rem][check];

	ll ans=0;
	if(check)
