long long calc(int i, int m, int tight) {
	if (i < 0) {
		if (m == 0) return 1;
		else return 0;
	}
	if (dp[i][m][tight] != -1) return dp[i][m][tight];

	dp[i][m][tight] = 0;

	if (tight) {
		for (int j = 0; j < s[i]-48; j++) {
			dp[i][m][tight] += calc(i-1, (m+j)%d, 0);
		}
		dp[i][m][tight] += calc(i-1, (s[i]-48 + m+100*d)%d, tight);
	}
	else {
		for (int j = 0; j < 10; j++) {
			dp[i][m][tight] += calc(i-1, (m+j)%d, 0);
		}	
	}

	dp[i][m][tight] %= MOD;

	return dp[i][m][tight];
}

