int dp(int pos, int d, int tight) {
	if (pos == K.size()) {
		return (d == 0);
	}
	int &ans = cache[pos][d][tight];
	if (ans != -1)
		return ans;
	int ub = ((tight == 1) ? K[pos] - '0' : 9);
	ans = 0;
	for (int i = 0; i <= ub; i++) {
		ans += dp(pos + 1, (d + i) % D, (tight & (i == ub)));
		ans %= mod;
	}

	return ans % mod;
}
