	int l = K.length();
	if (pos == --l) {

		for (int i = 0; i <= mx; i++) {
			if (i % D == d)
				ans++;
		}
		return dp[pos][d][restr] = ans % modl;

	}

	for (int i = 0; i <= mx; i++) {
		ans = (( ans + solve(K, D, pos + 1, (D + d - i % D) % D, restr && (i == mx))) % modl);
	}

	return dp[pos][d][restr] = ans % modl;
}

