ll dfs(int pos, int less, int sum) {
    if (pos == s.size()) {
        if (sum % d == 0) {
            return 1;
        } else {
            return 0;
        }
    }
    if (dp[pos][less][sum] != -1) {
        return dp[pos][less][sum];
    }
    char upper = less ? '9' : s[pos];
    ll total = 0;
    for (char i = '0'; i <= upper; i++) {
        ll num = sum + i - '0';
        num %= d;
        total += dfs(pos + 1, less || i < upper, num) % M; 
        total %= M;
    }
    total %= M;
    return dp[pos][less][sum] = total;
}

