class SDigitSum {
public:
    void solve() {
        string K = in.readString();
        int D = in.readInt();
        int N = K.length();
        vector<int> digits;
        for (auto c : K)
            digits.push_back(c - '0');
        arr3d<modint> dp(N, D, 2, -1);
        RecursiveFunction rec = [&](auto const& self, int idx, int sum, bool flag) -> modint {
            if (idx == N) {
                if (sum % D == 0)
                    return modint(1);
                return modint(0);
            }
            if (dp(idx, sum, flag) != -1)
                return dp(idx, sum, flag);
            int limit = (flag == 1) ? digits[idx] : 9;
            modint tot(0);
            for (int i = 0; i <= limit; i++) {
                if (i == digits[idx]) {
                    tot += self(idx + 1, (sum + i) % D, flag);
                } else {
                    tot += self(idx + 1, (sum + i) % D, 0);
                }
            }
            return dp(idx, sum, flag) = tot;
        };
        modint ans(rec(0, 0, 1));
        ans -= 1;
        out.printLine(ans);
    }
};


