ll rec(int n, int flag, int sum)
{   
    if(dp[n][flag][sum] != -1) return dp[n][flag][sum];
    if(n == 0)
    {
        if(sum == 0) return dp[0][flag][0] = 1;
        else return dp[0][flag][sum] = 0;
    }

    ll res = 0;
    int digit = K[N - n] - '0';
    if(flag == 1)
    {   
        res += rec(n - 1, 1, (sum + digit) % D) % MOD;
