        for(int i = 0; i < digit; i++)
        {
            res += rec(n - 1, 0, (sum + i) % D) % MOD;
            res %= MOD;
        }
    }
    else
    {
        for(int i = 0; i <= 9; i++)
        {
            res += rec(n - 1, 0, (sum + i) % D) % MOD;
            res %= MOD;
        }
    }
    return dp[n][flag][sum] = res ;
}

