				int limit = j ? K[i] - '0': 9;
				for (int keta_val = 0; keta_val <= limit; keta_val++) {
					dp[i + 1][(!j) ? 0 : ((keta_val == limit) ? 1 : 0)][(amari + keta_val) % D]
						+= dp[i][j][amari];
				}

			}
		}
	}
	//000...000はレグレーション違反なので、その分を引く
	cout << (dp[K.size()][0][0] + dp[K.size()][1][0] - 1 + MOD) % MOD << endl;

	return 0;
}

