ll getSum(string &num, ll pos, ll sum, bool flag, ll D){
    if(pos==num.length()){
        return sum==0;
    }
    if(dp[pos][sum][flag]!=-1)
        return dp[pos][sum][flag];
    int limit = 9;
    if(flag)
        limit = num[pos]-'0';
    ll ans = 0;
    repA(i,0,limit){
        ans += getSum(num, pos+1, (sum+i)%D, flag&&i==limit,D);
        ans%=mod;
    }
    return dp[pos][sum][flag] = ans;
}


