            for (int cur = 0; cur < n[i]; cur++)
                modadd(dp[i][(cur + pr) % d][0], dp[i + 1][pr][1]);
        }
    }

    int result = 0;
    modadd(result, dp[0][0][0]);
    modadd(result, dp[0][0][1]);

