    vector<Int>basemod(s.size());
    auto dp = vectors(s.size(),10 * s.size(),2, 0LL);
    auto visit = vectors(s.size(),10 * s.size(),2,false);
    function<Int(Int,Int,bool)>solve = [&](Int idx, Int sum, bool tight){
        if(idx == s.size())
            return (sum % D == 0  ? 1LL: 0LL);
        if(visit[idx][sum][tight])
            return dp[idx][sum][tight];
        Int num = (not tight ? 9 : s[idx] - '0' );
        Int res = 0;
        for(Int i = 0; i <= num; ++i){
            res += solve(idx + 1, sum + i, tight and num == i);
            res %= mod;
        }
        visit[idx][sum][tight] = true;
        return dp[idx][sum][tight] = res;
    };
    cout << (mod + solve(0LL,0LL,true) - 1 ) % mod << endl;
}

