ll dp_recurse(int k, int remainder){
	//cout << k << " " << remainder << endl;
	if(k==0){
		if(remainder == 0){
			return 1;
		}
		return 0;
	}

	if(check[k][remainder] == 1){
		return dp[k][remainder];
	}

	ll sum = 0;
	for(int i=0;i<10;i++){
		sum = (sum + dp_recurse(k-1, (remainder - i%d + d)%d ) )%mod;
	}

	dp[k][remainder] = sum;
	check[k][remainder] = 1;
	return sum;
}

