int rec(int k = 0, bool tight = true, int sum = 0) {
	if (sum > D) {
		return 0;
	}
	if (k == N.size()) {
		return sum == D;
	}

	int x = N[k] - '0';
	int r = (tight ? x : 9);

	int &res = dp[k][tight][sum];
	if (~res) return res;
	res = 0;

	for (int i = 0; i <= r; ++i) {
		res += rec(k + 1, tight && i == r, sum + i);
		res %= (int)10e9+7;
	}

	return res;
}

