int add(int a, int b, int Mod)
{
    return (a + b) % Mod;
}
int solve(int idx, bool smaller, int sum)
{
    if(idx == k.size())
        return sum == 0;
    int &ans = dp[idx][smaller][sum];
    if(ans != -1)
        return ans;
    ans = 0;
    for(int digit = 0; digit <= 9; digit++)
    {
        if(!smaller && digit > k[idx] - '0')
            continue;
        bool new_smaller;
        if(smaller)
            new_smaller = 1;
        else
            if(digit < k[idx] - '0')
                new_smaller = 1;
            else
                new_smaller = 0;
        ans = add(ans, solve(idx + 1, new_smaller, add(sum, digit, d)), mod);
    }
    return ans;
}

