int solve(int ind, int curr = 0, bool small = 0) {
    if(ind == n) {
        return curr == 0;
    }
    if(small == 1 && dp[ind][curr] != -1) {
        return dp[ind][curr];
    }
    int ans = 0;
    int limit = small ? 9 : arr[ind];
    for(int i = 0; i <= limit; i ++) {
        if(i!= limit)
            ans += (solve(ind+1, (curr+i)%d, 1));
        else 
            ans += (solve(ind+1, (curr+i)%d, small));
        ans %= mod;
    }
    if(small == 1)
        dp[ind][curr] = ans;
    return ans;
}

