            for (int c = 0; c < 10; c++)
            {
                ret += dp[i - 1][((j - c) % d + d) % d];
                ret %= MOD;
            }
            dp[i][j] = ret;
        }
    }

    cout << ((solve(0, 0) - (d != 1)) % MOD + MOD) % MOD << endl;
}

