	memset(dp, -1, sizeof dp);
	for (int i = 1; i < k[0] - '0'; i ++) {
		sol += rek(1, i%d, 0);
		sol %= MOD;
	}

	sol += rek(1, (k[0] - '0')%d, 1);
	sol %= MOD;

	if (k.size() > 1) {
		memset(rj, -1, sizeof rj);
		for (int i = 1; i < 10; i ++) {
			sol += dr(1, i%d);
			sol %= MOD;
		}
	}

	cout << sol;

	return 0;
}

