void
solve() {
  string s;
  ll d;
  cin>>s>>d;

  vector<ll> dp(d, 0), temp(d);
  ll last = 0;
  for (ll i=0; i<s.length(); i++) {
    temp = vector<ll>(d, 0);
    if (i==0) {
      for (ll j=0; j<s[i]-'0'; j++) {
        temp[j] = 1;
      }
    }
    else {
      for (ll j=0; j<10; j++) {
        if (j < s[i]-'0') { 
          temp[(j+last)%d]++;
          temp[(j+last)%d] %= mod;
        }
        for (ll k=0; k<d; k++) {
          temp[(j+k)%d] += dp[k];
          temp[(j+k)%d] %= mod;
        }
      }
    }
    swap(dp, temp);
    last += s[i] - '0';

    //for (auto k : dp) cout<<k<<","; cout<<endl;
  }
  dp[last % d]++;
  cout<<(dp[0]-1 % mod) % mod<<endl;
}

