string s;


ll solve(ll pos, ll modi, bool tight){
	//base case
	if(pos == s.length()){
		return modi==0;
	}
	//recursive case
	if(dp[pos][modi][tight]!=-1){return dp[pos][modi][tight];}

	ll ans=0;
	ll end= (tight)?(s[pos]-'0'):9;
	for(ll i=0; i<=end; i++){
		ll t = (solve(pos+1, (modi+i)%d, tight&(i==end)))%mod;
		ans += t;
		ans %= mod;
	}
	return dp[pos][modi][tight] = ans;
}

