int main(){
  string S; cin >> S;
  int D; scanf("%d", &D);

  DP1[0][0] = 0;
  DP2[0][0] = 1;

  for (int i = 1; i <= S.length(); i++){
    int now = S[i - 1] - '0';

    for (int j = 0; j < D; j++){
      for (int k = 0; k < 10; k++){
        DP1[i][(j + k) % D] += DP1[i - 1][j];
      }
    }

    for (int j = 0; j < D; j++){
      for (int k = 0; k < now; k++){
        DP1[i][(j + k) % D] += DP2[i - 1][j];
      }
    }

    for (int j = 0; j < D; j++){
      DP2[i][(j + now) % D] += DP2[i - 1][j];
    }

    for (int j = 0; j < D; j++){
      DP1[i][j] %= nmax;
      DP2[i][j] %= nmax;
    }
  }

  ll ans = DP1[S.length()][0] + DP2[S.length()][0] + nmax - 1;
  printf("%lld\n", ans % nmax);
  return 0;
}

