vector<vector<mint>> dot(vector<vector<mint>> a, vector<vector<mint>>b) {
    vector<vector<mint>> ret;
    rep(i, a.size()) {
        vector<mint> v(b[0].size(), mint(0));
        ret.push_back(v);
    }

    rep(i, a.size()) {
        rep(j, b[0].size()) {
            rep(k, a.size()) {
                ret[i][j] += a[i][k] * b[k][j];
            }
        }
    }
    return ret;
}

