int dfs(int pos, int r, int f){
    if(pos==k.size()){
        if(r==0)
            return 1;
        else
            return 0;
    }

    if(dp[pos][r][f]!=-1)
        return dp[pos][r][f];

    int LMT;
    if(f) // sequence till pos-1 is has a digit smaller
        LMT = 9;
