ll dp[D][K];

int main(){
    // Input
    string s;
    cin>>s;
    int n=s.length();
    int d;
    cin>>d;
    // Computing DP
    for(int i=0; i<d; i++)
        dp[i][0]=0;
    dp[0][0]=1;
    for(int i=1; i<=n; i++){
        for(int j=0; j<d; j++){
            ll sum=0;
            for(int o=0; o<10; o++){
                int t=((j-o)%d+d)%d;
                sum+=dp[t][i-1];
            }
            dp[j][i]=sum%Mod;
        }
    }
    // Calculating Answer
    ll ans=0;
    int w=0;
    for(int i=0; i<n; i++){
        int j=n-i, t=s[i]-'0';
        for(int p=0; p<t; p++){
            int y=((-w-p)%d+d)%d;
            ans=(ans+dp[y][j-1])%Mod;
        }
        w+=t;
    }
    if(w%d==0)ans++;
    cout<<ans-1;
}

