LL DFS(int idx, int su, int flag){
    if (idx == (int)s.size()) return su == 0;
    if (dp[idx][su][flag] != -1) return dp[idx][su][flag];
    LL cnt = 0, en;
    if (flag == 1) en = s[idx] - '0';
    else en = 9;
    for (int i=0; i<=en; ++i){
