ll rec(int idx, int sum, int flag)
{
	if (idx == n)
	{
		if (sum % D == 0)
			return 1;
		return 0;
	}
	if (dp[idx][sum][flag] != -1)
		return dp[idx][sum][flag];
	ll ans = 0;
	int lim = (flag == 1) ? digits[idx] : 9;
	for (int i = 0; i <= lim; i++)
