int dp[100001][101][2];
string k;
int D;

int solve(int pos, int d, bool tight) {

	if (dp[pos][d][tight] != -1) return dp[pos][d][tight];
	int ub = (tight) ? (k[pos] - '0') : 9;
	if (pos == k.length() - 1) {
		int ans = 0;
		for (int x = 0; x <= ub; x++) {
			if (x % D == d) ans++;
		}

		return dp[pos][d][tight] = ans;
	}

	int ans = 0;
	for (int x = 0; x <= ub; x++) {
		ans = (ans + solve(pos + 1, (D + d - x % D) % D, tight && (ub == x))) % mod;
	}

	return dp[pos][d][tight] = ans;
}

