ll dfs(int at, int rem, bool zero, bool less)
{
	if(at == N){
		if(!rem && !zero) return 1;
		else return 0;
	}
	if(!zero && less){
		ll res = dp[at][rem];
		if(res != -1) return res;
	}
	ll res = 0;
	for(int i=0;i<=(less?9:K[at]-'0');++i){
		(res += dfs(at+1, (rem+i)%D, (zero&&!i), (less||(i<(K[at]-'0')))))%=MOD;
	}
	if(!zero && less) dp[at][rem]=res%MOD;
	return res;
}

