int solve(int i=0,int sum=0,bool f=0){
    if(i==k.length()){
        if(sum==0)return 1;
        return 0;
    }
    ll &ret=dp[i][sum][f];
    if(~ret)return ret;

    int num;
    if(!f)num=k[i]-'0';
    else num=9;
    ret=0;
    for(int j=0;j<=num;j++){
        bool flag=f;
        if(j<num)flag=1;
        int tmp=sum;
        tmp+=j;
        tmp%=d;
        ret+=solve(i+1,tmp,flag);
        ret%=mod;
    }
    return ret%mod;
}
