                  if(i == 1 && !j)
                        continue;
                  int sum = (pref[i - 1] + j) % d;
                  ans = (ans + dp[n - i][(d - sum + d) % d]) % mod;

            }
      }

      if(pref[n] % d == 0)
            ans = (ans + 1) % mod;

      cout << ans << endl;
}

