	for (ll i = 1; i <= K.size(); i++) {
		dig_sum[i] = (dig_sum[i-1] + Ki[i-1]) % D;
	}
	auto dp = make_vec_nd((Mod)0, K.size() + 1, D);
	for (ll i = 1; i <= K.size(); i++) {
