					dp[i][d] += 1;
				}
				dp[i][d] += dp[i-1][((d - n) % D + D) % D];
			}
		}
	}
	Mod ans = dp[K.size()][0];
	if (dig_sum[K.size()] == 0) {
		ans += 1;
	}
	ans -= 1;
	cout << ans.value << endl;
}

