long long go(int pos, bool fl, int sum) {
    if(pos >= n) return sum % d == 0 ? 1 : 0;
    if(dp[pos][fl][sum % d] != -1) return dp[pos][fl][sum % d];

    long long ret = 0;
    for(int i = 0; i <= 9; ++i) {
