    for(long long int j = 0; j <= D; j++){
      std::cerr << dp_table[i][j] << " ";
    }std::cerr << std::endl;
  }*/

  long long int ans = dp_table[digits-1][0]-1;
  if(dp_table[digits-1][D]==0){
    ans++;
  }
  ans %= MOD;

  std::cout << ans << std::endl;

  return 0;
}

