int solve(int i = 0, int m = 0, int f = 0) {
    if (i == n) {
        return m==0;
    }
    int& ret = dp[i][m][f];
    if (~ret) {
        return ret;
    }
    ret = 0;
    for (int j = 0; j <= 9; ++j) {
        if (j> s[i]-'0' && !f) {
            break;
        }
        ret += solve(i+1, (m+j)%d, f | (j < s[i]-'0'));
        if (ret >= M) {
            ret %= M;
        }
    }
    return ret;
}
