int call(int pos,int rem_sum,int f)
{

	//cout << pos << " " << rem_sum << " " << f << " \n";

	if(dp[pos][rem_sum][f] != -1)
		return dp[pos][rem_sum][f];

	if(pos == k.length())
	{
		if(rem_sum == 0)
		{
			return dp[pos][rem_sum][f] = 1;
		}

		return dp[pos][rem_sum][f] = 0;	
	}


	int limit;

	if(f==0)
	{
		limit = k[pos] - '0';
