mint solve(vector<int>& k, int offset, int d) {
    if (k.size() == 1) {
        mint res = 0;
        for (int i = 0; i <= k[0]; i++) {
            if ((offset + i) % d == 0)
                res++;
        }
        return res;
    }
    if (k.back() == 0) {
        k.pop_back();
        return solve(k, offset, d);
    }
    vector<vector<mint>> dp(2, vector<mint>(d, 0));
    int nof = offset ? d - offset : 0, n = k.size();
    dp[1][0] = dp[0][0] = 1;
    for (int x = 0; x < n; x++) {
        int stop = (x == n - 1 ? k[x] : 10);
        for (int j = 1; j < stop; j++) {
            for (int i = 0; i < d; i++) {
                int nj = (i + j) % d;
                dp[1][nj] += dp[0][i];
            }
        }
        dp[0] = dp[1];
    }
    offset = (offset + k.back()) % d;
    k.pop_back();
    cout << dp[1][nof] << '\n';
    return dp[1][nof] + solve(k, offset, d);
}

