template<typename T>
void add_self(T& a, T b)
{
  a += b;
  if(a > mod)
  {
    a -= mod;
  }
}


int func(int i, int sum, bool pre)
{
  if(i == n)
  {
    return sum == 0;
  }
  if(dp[i][sum][pre] != -1)
  {
    return dp[i][sum][pre];
  }
  int sol = 0;
  if(pre)
  {
    for(int d = 0; d <= nums[i]; d++)
    {
      add_self(sol, func(i + 1, (sum + d) % D , d == nums[i]));
    }
  }
  else
  {
    for(int d = 0; d <= 9; d++)
    {
      add_self(sol, func(i + 1, (sum + d ) % D, false));
    }
  }
  return dp[i][sum][pre] = sol;
}



