int solve(int pos, int rem, bool small)
{
    if (pos == n)
        return rem == 0;
    int &ans = dp[pos][rem][small];
    if (ans != -1) return ans;
    ans = 0;
    int maxd = 9;
    if (!small)
        maxd = (s[pos] - '0');
    for (int i = 0; i < maxd; ++i)
        ans = (ans + solve(pos + 1, (rem + i) % d, 1)) % MOD;
    ans = (ans + solve(pos + 1, (rem + maxd) % d, small)) % MOD;
    return ans;
}

