    gc(filler);
    memset(dp, -1, sizeof(dp));
    final = calc(0, true, 0);
    final --;
    if (final < 0) final = 1000000007  + final;
    else final = final % 1000000007;
    cout<<final<<"\n";
    return 0;
}

