int64_t getDigitSum(const std::vector<int> keta, const int64_t d) {
  std::vector<int64_t> dp1(d, 0);
  std::vector<int64_t> dp2(d, 0);
  dp2[0] = 1;

  const int digit = static_cast<int>(keta.size());

  for (int i = 0; i < digit; ++i) {
    std::vector<int64_t> dp1_next(d, 0);
    std::vector<int64_t> dp2_next(d, 0);
    const int current_max = keta[i];
    for (int j = 0; j < d; ++j) {
      for (int n = 0; n <= 9; ++n) {
        dp1_next[(j + n) % d] += dp1[j];
        dp1_next[(j + n) % d] %= 1000000007LL;
      }
      for (int n = 0; n < current_max; ++n) {
        dp1_next[(j + n) % d] += dp2[j];
        dp1_next[(j + n) % d] %= 1000000007LL;
      }
      dp2_next[(j + current_max) % d] += dp2[j];
      dp2_next[(j + current_max) % d] %= 1000000007LL;
    }

    dp1 = dp1_next;
    dp2 = dp2_next;
  }
  return (dp1[0] + dp2[0] - 1) % 1000000007LL;
}

