  std::vector<int> result;
  for (const auto &c : value) {
    result.push_back(c - '0');
  }
  return result;
}

int main() {
  std::string k;
  int d;
  std::cin >> k >> d;
  std::cout << getDigitSum(getVector(k), d) << std::endl;
  return 0;
}

