	ll dp[k.size()][d][2] = {};
	ll sum = 0;
	ll tmp1[10] = {};
	for(int j = 0; j < 10; j++){
		tmp1[j%d]++;
	}
	for(int i = 0; i < k.size(); i++){
		sum += k[i] - '0';
		if(i == 0){
			for(int j = 0; j < k[i] - '0'; j++){
				dp[i][j%d][0]++;
			}
			dp[i][sum % d][1]++;
			continue;
		}
		dp[i][sum%d][1]++;
		ll tmp2[k[i] - '0'] = {};
		for(int j = 0; j < k[i] - '0'; j++){
			tmp2[j%d]++;
		}

		for(int j = 0; j < d; j++){
			for(int m = 0; m < 10; m++){
				dp[i][(j+m)%d][0] = (dp[i][(j+m)%d][0] + dp[i-1][j][0] * tmp1[m]) % mod;
			}
			for(int m = 0; m < k[i] - '0'; m++){
				dp[i][(j+m)%d][0] = (dp[i][(j+m)%d][0] + dp[i-1][j][1] * tmp2[m]) % mod;
			}
		}
	}
	//-1 is for 00000...0
	cout<<(dp[k.size()-1][0][0] + dp[k.size()-1][0][1] - 1) % mod;
	return 0;
}

