const int N = (int)1e4 + 10, S = 104;
const int MOD = (int)1e9 + 7;

int dp[N][S][2];
int n, d;
string s;

inline int add (int a, int b) {
   return (a + b)%MOD;
}

// dp[pos][sum][false] := till pos, digits used are upto max limits(i.e. forming highest number)
//  // // // has to come from false
// dp[pos][sum][true] := till pos, digits used are such they are less than the limits
// // // // can come from both false and true

void solve() {
   n = (int)s.size();
   s = ' ' + s;

   for (int dg = 0; dg < s[1] - '0'; ++dg)
      dp[1][dg % d][true] += 1;

   dp[1][(s[1] - '0')%d][false] += 1;

   // or equivalent base case : dp[0][0][0] = 1 // and start dp from pos = 1

   for (int pos = 2; pos <= n; ++pos) {
      for (int rem = 0; rem < d; ++rem) {
         for (bool les : {false, true}) {
            int mx_digit = 9;
            if (!les)
            {
               mx_digit = s[pos] - '0';
            }
            for (int dg = 0; dg <= mx_digit; ++dg) {
               bool is_les = (les || (dg < s[pos] - '0'));
               dp[pos][(rem + dg) % d][is_les] =
                  add(dp[pos][(rem + dg) % d][is_les], dp[pos - 1][rem][les]);
            }
         }
      }
   }
   cout << (dp[n][0][0] + dp[n][0][1] - 1 + MOD) % MOD << '\n';
}

signed main() {
   IOS; PREC;
   cin >> s >> d;
   solve();

   return EXIT_SUCCESS;
}

