int rec(int pos, int sum, bool f)
{
	if(pos == v.size()) return (sum == 0);
	int &res = dp[pos][sum][f];
	if(~res) return res;

	int lim = (f ? 9 : v[pos]);
	res = 0;

	for(int i = 0; i <= lim; i++) {
		int nsum = (sum + i) % d;
		res += rec(pos + 1, nsum, f || (i < v[pos]));
		res %= MOD;
	}
	return res;
}
