	if(!limit && dp[pos][m]!=-1) return dp[pos][m];
	ll res = 0;
	int ub = limit ? S[pos]-'0' : 9;
	for(int i=0;i<=ub; ++i){
		res = (res + dfs(pos+1, (m+i)%D, (limit && i==ub)))%MOD;
	}
	res %= MOD;
	if(!limit) dp[pos][m]=res;
	return res;
}

