	cin>>k;

	cin>>d;

	for(int i = 0; i < k.length(); i++){

		for(int j = 0; j < d; j++){

			dp[i][j][0] = -1;

			dp[i][j][1] = -1;

		}

	}

	ll ans = fun(0, 0, 1) - 1 + mod;

	ans %= mod;

	cout<<ans<<endl;

	return 0;

}

#include<bits/stdc++.h>
