        return dp[pos][sum][tight];
    }

    int end = ((tight ? (s[pos - 1] - '0') : 9));
    int ans = 0;
    for (int i = 0; i <= end; i++)
    {
        ans = (ans + solve(pos + 1, (sum + i % d) % d, tight & (i == end))) % mod;
    }
    return dp[pos][sum][tight] = ans;
}

void Solution()
{
    cin >> s >> d;
    memset(dp, -1, sizeof dp);
    cout << solve(1, 0, 1) - 1;
}

int32_t main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);
    Solution();
}

