ll recurs(string& k, ll ind, ll need, ll d, vector<vector<ll> >& dp){
	ll len = (ll)k.length() - 1 - ind;
	if(len < (ll)0)
		return (need == 0);
	ll sum = 0;
	for(ll i = 0; i<(k[ind]-'0'); i++){
		sum+=dp[len][((need-i)%d + d)%d];
