long long solve(long long idx , long long rem , bool t , bool t2)
{
    if(idx == num.size())
    {
        if(rem == 0 && t2 == 1)
            return 1ll ;
        return 0ll ;
    }
    long long &ret = dp[idx][rem][t][t2] ;
    if(ret != -1)
        return ret ;
    ret = 0 ;
    long long LMT ;
    if(t == 0)
        LMT = num[idx] ;
    else
        LMT = 9 ;
    for(long long i = 0 ; i <= LMT ; ++i)
    {
        long long nt = t ;
        long long nt2 = t2 ;
        if(t == 0 && i < LMT)
            nt = 1 ;
        if(t2 == 0 && i != 0)
            nt2 = 1ll ;
        ret = (ret + solve(idx+1 , (rem + i) % d , nt , nt2)) % mod;
        ret = (ret % mod) ;
    }
    return (ret % mod) ;
}

