int alpha(int id , int sum , int ok)
{
	if(id == n)return (sum == 0);
	int &abs = dp[id][sum][ok];
	if(abs != -1)return abs;
	int ans = 0;

	int k = s[id]-'0';
	if(ok)k = 9;

	loop(i,0,k+1)
	{
		if(i < k)
		{
			int nsum = (sum + i)%d;
			ans += alpha(id+1 , nsum , 1);
			ans %= M;
		}
		else
		{
			int nsum = (sum + i)%d;
			ans += alpha(id+1 , nsum , ok);
			ans %= M;
		}
	}

	return abs = ans;
}


