const int MOD = 1e9 + 7;
const int INF = 0x3f3f3f3f;
const LL LLINF = 0x3f3f3f3f3f3f3f3f;
const int MAX_N = 10005;
const int MAX_D = 105;

LL dp[MAX_N][MAX_D][2];

struct Solution {
    LL solve(size_t idx, int r, bool tight, const string& K, const int D) {
        if(idx == K.size()) {
            return (r == 0) ? 1 : 0;
        } else if(dp[idx][r][tight] != -1) {
            return dp[idx][r][tight];
        }

        LL res = 0;
        int limit = tight ? (K[idx] - '0') : 9;
        for(int i = 0; i <= limit; ++i) {
            bool new_tight = tight and i == limit;
            int new_r = (r + i) % D;
            res += solve(idx + 1, new_r, new_tight, K, D);
            if(res >= MOD) res -= MOD;
        }
        dp[idx][r][tight] = res;
        return res;
    }

    Solution(int) {
        memset(dp, -1, sizeof(dp));

        string K;
        int D;
        read(K, D);
        auto ans = solve(0, 0, true, K, D) + MOD - 1;
        if(ans >= MOD) ans -= 1;
        print(ans);
    }
};

