    for(int i = 0; i < n; i++){
        for(int j = 0; j < s[i]-'0'; j++){ // x + sum + j mod= 0
            ans += dp[n-i-1][ (((-1*(sum+j))%d)+d)%d];
            ans %= mod;
        }
        sum += s[i]-'0';
    }
    //ans = (ans-1+mod)%mod;
