long long solve(int N, int lo, int rem, int K)
{
    if(N == S.size())
        return (rem == 0);

    if(dp[N][lo][rem] != -1)
        return dp[N][lo][rem];

    int val = S[N]-'0';
    long long ans = 0;

    for(int i=0; i<10; i++)
    {
        if(lo == 0 && i > val)
            break;

        ans += solve(N+1, (lo | (i < val)), (rem + i) % K, K);
    }

    return dp[N][lo][rem] = ans % MOD;
}

