int32_t go(int pos, int rem, bool f = false) {
    if (pos == s.size()) {
        return rem == 0;
    }
    auto &ref = dp[pos][rem][f];
    if (ref != -1) {
        return ref;
    }
    int curDig = s[pos] - '0';
    int ans = 0;
    for (int i = 0; i < 10; ++i) {
        if (i > curDig && f == false) {
            break;
        }
        int new_rem = (rem + i);
        while (new_rem >= d) {
            new_rem -= d;
        }
        ans = add(ans, go(pos + 1, new_rem, f | (i < curDig)));
    }
    return ref = ans;
}

