      return 1;
    } else {
      return 0;
    }
  }
  long long ans = 0;
  for (int d = 0; d <= 9; d++) {
    int leftmost_lo_prime = d < state.dig(i) && i < leftmost_lo? i : leftmost_lo;
    int leftmost_hi_prime = d > state.dig(i) && i < leftmost_hi? i : leftmost_hi;
