                    rep(k, 10)
                    {
                        dp[i][j] += dp[i - 1][(j - k % d + d) % d];
                        dp[i][j] %= MOD;
                    }
                } else {
                    dp[i][j] = dp[i][j - 1] + (dp[i - 1][j] - dp[i - 1][(j - 10 % d + d) % d] + MOD) % MOD;
                    dp[i][j] %= MOD;
                }
            }
            int e = s[i - 1] - '0';
            rep(j, e)
            {
                dp[i][(r + j) % d]++;
                dp[i][(r + j) % d] %= MOD;
            }

            r = (r + e) % d;
        }
    }

    int64_t result = (dp[s.size()][0] + (r == 0 ? 1 : 0) - 1 + MOD) % MOD;
    cout << result << endl;

    return 0;
}

