int solve(int l, bool isRestricted, int sum){

  if(l == n){
    return (sum == 0);
  }

  int &ans = dp[l][isRestricted][sum];
  if(~ans)
    return ans;

  int R = (isRestricted ? (k[l] - '0') : 9);
  ans = 0;

  if(isRestricted){
    for(int i = 0; i <= R; i++){
      if(i == R){
        ans = add(ans, solve(l + 1, 1, (sum + i) % d));
      }else{
        ans = add(ans, solve(l + 1, 0, (sum + i) % d));
      }
    }
  }else{
    for(int i = 0; i <= 9; i++){
      ans = add(ans, solve(l + 1, 0, (sum + i) % d));
    }
  }
  return ans;
}

