	int cnt=0;
	for(int j=1;j<=s[0]-'0';++j) ans+=dp[(9*n-j)%n][l-1],ans%=mod;
	for(int i=l;i>=2;--i){
		cnt+=s[l-i]-'0';
		for(int j=s[l-i+1]-'0'+1;j<=9;++j)
		ans+=(mod-dp[((cnt+9)*n-cnt-j)%n][i-2]),ans%=mod;
	}
	cout<<ans<<"\n";
	return 0;
}

