int countdigitsum(int pos,int d,bool tight,string k,int D){
	int ub = tight? k[pos]-'0': 9;
	if(dp[pos][d][tight]!=-1){
		return dp[pos][d][tight];
	}
	if(pos==k.length()-1){
		int ans=0;
		for(int x=0;x<=ub;x++){
			if(x%D==d){
				ans++;
			}
		}
		return ans;
	}
	int ans=0;
	for(int x=0;x<=ub;x++){
		ans= (ans+countdigitsum(pos+1,(D+d-x%D)%D,tight&&(x==ub),k,D))%mod;
	}
	return dp[pos][d][tight]=ans;
}
