	vector<vector<vector<ll>>> dp(1e4 + 1, vector<vector<ll>>(10, vector<ll>(D, 0)));
	rep(i, 10)dp[0][i][i%D]++;

	// 桁数 -> ソースの末尾数字 -> ソースのD除算余り -> 次の末尾数字
	rep(e, 1e4)rep(num, 10)rep(d, D)rep(add, 10) {
		(dp[e + 1][add][(d + add) % D] += dp[e][num][d]) %= MOD;
	}
	return dp;
}

int main()
{
	ll D;
	string N;
	cin >> D >> N;
	auto dp = way(D);

	ll res = 0;
	ll left = 0;
	rep(i, N.size()) {
		ll pos = N.size() - i - 1;
		ll top = N[i] - '0';
		rep(j, top) {
			(res += dp[pos][j][(D * 10000 - left) % D]) %= MOD;
		}
		(left += top) %= D;
	}

	cout << (res - 1 + MOD) % MOD << endl;

	return 0;
}

