const long long MAX = 1e5 ;
const long long mod = 1e9 + 7ll ;
long long dp[MAX][105][2] ;
vector<long long>num ;
long long d ;

long long solve(long long idx , long long rem , bool t)
{
    if(idx == num.size())
    {
        if(rem == 0)
            return 1ll ;
        return 0ll ;
    }
    long long &ret = dp[idx][rem][t] ;
    if(ret != -1)
        return ret ;
    ret = 0 ;
    long long LMT ;
    if(t == 0)
        LMT = num[idx] ;
    else
        LMT = 9 ;
    for(long long i = 0 ; i <= LMT ; ++i)
    {
        long long nt = t ;
        if(t == 0 && i < LMT)
            nt = 1 ;
        ret = (ret + solve(idx+1 , (rem + i) % d , nt)) % mod;
        ret = (ret % mod) ;
    }
    return (ret % mod) ;
}

