{
    for(long long i = 0 ; i < s.size() ; ++i)
        num.push_back(s[i] - '0') ;
    memset(dp , -1 , sizeof(dp));
    long long ans = solve(0 , 0 , 0);
    if(ans == 0ll)
        while(1);
    ans--;
    return ans ;
}

