int recurse(int pos = 0, int md = 0, int f = 0) {
    if (pos == num.size()) {
        if (md == 0)
            return 1;
        return 0;
    }

    if (dp[pos][md][f] != -1)
        return dp[pos][md][f];

    int limit = 9;
    if (!f) limit = (int)(num[pos] - '0');

    int ans = 0;
    for (int i = 0; i <= limit; i++) {
