ll solve(long long cs, int pos, bool isLower, bool isUpper) {
    if(dp[cs][pos][isLower][isUpper] != -1) {
        return dp[cs][pos][isLower][isUpper];
    }
    ll res = 0;
    int clb = isLower ? lower[pos]-'0' : 0;
    int cub = isUpper ? upper[pos]-'0' : 9;

    if(pos == lower.count-1) {
        rep(i,clb,cub+1) {
            res += (cs + i)%d == 0 ? 1 : 0;
        }
        dp[cs][pos][isLower][isUpper] = (res)%d;
        return res;
    }
    rep(i, clb, cub+1) {
        long long ns = (cs + i)%d;
        res = (res + solve(ns,
                           pos+1,
                           isLower && i == clb,
                           isUpper && i == cub));
    }
    dp[cs][pos][isLower][isUpper] = res;
    return res;
}


