ll solve(string &k,int &D,int pos, int d, bool tight){

    if(dp[pos][d][tight]!=-1){
        return dp[pos][d][tight];
    }

    int ub=(tight)?(k[pos]-'0'):9;

    if(pos==(int)k.length()-1){
        ll ans=0;
        for(int x=0;x<=ub;x++){
            if(x%D==d){
                ans++;
            }
        }
        return ans;
    }

    ll ans=0;

    for(int x=0;x<=ub;x++){
        ans=(ans+solve(k,D,pos+1,(D+d-x%D)%D,tight&&(x==ub)))%mod;
    }

    return dp[pos][d][tight]=ans;


}

