int const MAXEK = 10000;
int const MAXD = 100;
int const MOD = 1000000007;

char K[MAXEK+1];
int D, L;

int mod[2][MAXD];

int partial(int l) {
  int tmp = 0;
  for(int i = 0; i < l; ++i) tmp += K[i] - '0';
  tmp %= D;
  if(l == L) return tmp==0? 1: 0;
  int c = K[l] - '0';
  if(c == 0) return 0;
  for(int i = 0; i < D; ++i) mod[l%2][i] = 0;
  for(int i = 0; i < c; ++i) mod[l%2][(tmp+i)%D] += 1;
  for(int i = l+1; i < L; ++i) {
    for(int j = 0; j < D; ++j) {
      tmp = 0;
      for(int k = 0; k < 10; ++k) tmp = (tmp + mod[(i-1)%2][(j-k+D*9)%D])%MOD;
      mod[i%2][j] = tmp;
    }
  }
  return mod[(L-1)%2][0];
}


