ll solve(int i , int cur , bool tooksmaller){

    assert(i <=n && cur < d);
    if(i == n)
        return cur == 0;

    ll &ret = dp[tooksmaller][cur][i];
    if(~ret)
        return ret;

    int sz = (tooksmaller? 9 : K[i]);

    ret = 0 ;

