// 各桁の総和を知りたい場合は引数にsum,判定にsum==D
long rec(string &s, int k=0, bool tight=true, int sum=0){
  if(k == s.size()){
    //条件によって返す値が決まる
    return (sum == 0);
  }

  int m = s.at(k) - '0'; //k桁目の数字

  if(dp[k][tight][sum] != -1) return dp[k][tight][sum];

  int x = (tight ? m : 9);
  long res = 0;
  for(int i=0; i<=x; i++){
    //if(i == 4 || i == 9) continue;
    res += rec(s, k+1, i==x && tight, (sum+i)%D);
    res %= MOD;
  }

  return dp[k][tight][sum] = res;
}

