int dp[2][10010][128];

int calc(int pos, int rem, int lo) {
    if(pos == k.size()) return (rem == 0);
    int &y = dp[lo][pos][rem];
    if(y != -1) return y;
    y = 0;
    for(int i=0; i<=(lo?9:(k[pos]-'0')); ++i) {
        y += calc(pos+1, (rem+i)%d, (lo or (i < (k[pos]-'0'))));
        if(y >= MOD) y -= MOD;
    }
    return y;
}

