{
    cin >> s;
    cin >> d;
    n = s.size();

    memset(dp,-1,sizeof(dp));

    long long ans = solve(0,1,0) - 1;

    if (ans < 0)
        ans += mod;

    cout << ans << endl;

    return 0;

}

