	if(ret != -1) return ret;
	ret = 0;
	if(t == 1){
		for(int i=0;i<=9;i++){
			ret = (ret + bt(id+1,(sum+i)%d,1)) % mod;
		}
	}
	else{
		ll n = s[id] - '0';
		for(int i=0;i<n;i++){
			ret = (ret + bt(id+1,(sum+i)%d,1)) % mod;
		}
		ret = (ret + bt(id+1,(sum+n)%d,0)) % mod;
	}
	return ret;
}
