int recur(int pos,int sum,int flag)
{
	if(pos==n)
	{
		int some=(sum)%d;
		if((some)>0)
			return 0;
		else
		{
			return 1;
		}
	}
	else if(dp[pos][sum][flag]!=-1)
		return dp[pos][sum][flag];
	else
	{
		int tmp=0;
		int temp=k[pos]-'0';
		for(int i=0;i<temp;i++)
		{
			int some=(sum+i)%d;
			tmp+=recur(pos+1,some,0);
			tmp%=modd;
		}
		if(flag)
		{
			int some=(sum+temp)%d;
			tmp+=recur(pos+1,some,1);
			tmp%=modd;
		}
		else
		{
			for(int i=temp;i<10;i++)
			{
				int some=(sum+i)%d;
				tmp+=recur(pos+1,some,0);
				tmp%=modd;
			}	
		}
		dp[pos][sum][flag]=tmp;
		return dp[pos][sum][flag];
	}
}
