int f(int index,int sum,bool flag){
	int n = (int)s.size();
	if(index == n){
		if(sum == 0) return 1;
		return 0;
	}

	if(dp[index][sum][flag] != -1) return dp[index][sum][flag];

	int limit = 9;
	if(flag) limit = s[index] - '0';

	int ans = 0;
	for(int i = 0; i <= limit; ++i){
