#include <bits/stdc++.h>

using namespace std;

const int MAX = 1e5 ;
const long long mod = 1e9 + 7ll ;
long long dp[MAX][105][2] ;
vector<int>num ;
long long d ;

long long solve(int idx , int rem , bool t)
{
    if(idx == num.size())
    {
        if(rem == 0)
            return 1ll ;
        return 0ll ;
    }
    long long &ret = dp[idx][rem][t] ;
    if(ret != -1)
        return ret ;
    ret = 0 ;
    int LMT ;
    if(t == 0)
        LMT = num[idx] ;
    else
        LMT = 9 ;
    for(int i = 0 ; i <= LMT ; ++i)
    {
        int nt = t ;
        if(t == 0 && i < LMT)
            nt = 1 ;
        ret = (ret + solve(idx+1 , (rem + i) % d , nt)) % mod;
    }
    return (ret % mod) ;
}

long long run(string s)
{
    for(int i = 0 ; i < s.size() ; ++i)
        num.push_back(s[i] - '0') ;
    memset(dp , -1 , sizeof(dp));
    long long ans = solve(0 , 0 , 0) - 1ll ;
    return ans ;
}

