int solve(int dig, int m, bool less) {
  if (dig >= N.size()) {
    return (m == 0);
  }
  if (dp[dig][m][less] != -1) return dp[dig][m][less];

  int res = 0;
  for (int d = 0; d < 10; d++) {
    if (less || (d <= N[dig])) {
      res = (res + solve(dig + 1, (m + d) % D, less || (d < N[dig]))) % MOD;
    }
  }

  return dp[dig][m][less] = res;
}

