	dp[0][0][0] = 1;

	for (int digit = 0; digit < N; digit++) // 桁数
	{
		for (int d = 0; d < D; d++) // 総和 mod D
		{
			int c = K[digit] - '0';
			for (int isless = 0; isless < 2; isless++) // K 未満であるか (isless = true -> K 未満)
			{

				for (int next = 0; next < 10; next++) // digit 桁目にくる数字
				{
