					{
						(dp[digit + 1][(d + next) % D][1] += dp[digit][d][isless]) %= mod;
					}
					if (c == next) // isless = false -> Kと同じ, isless = true -> 既にK以下
					{
						(dp[digit + 1][(d + next) % D][isless] += dp[digit][d][isless]) %= mod;
					}
					if (c < next) // isless = false だとnextは置けない(Kより大きくなる)
					{
						if (isless)
