            for (int d = 0; d < 10; d++) if (lt || d <= cur) {
                dp[i + 1][(r + d) % D][lt | (d < cur)] += dp[i][r][lt];
            }
        }
    }
    cout << dp[n][0][0] + dp[n][0][1] - 1 << endl;  // 0 を除く
    return 0;
}

