const int N = 1e4 + 3, D = 103;
const ll MOD = 1e9 + 7;

ll dp[N][D][2];

void add(ll& a, ll b) {
    a += b;
    if (a >= MOD)
        a -= MOD;
}

void solve() {
    int d;
    string s;
    cin >> s >> d;

    int n = (int) s.size();
    for (int i = 0; i < n; ++i)
        s[i] -= '0';

    // dp[i][sum][sm] -- number of ways

    dp[0][0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < d; ++j) {
            for (int sm = 0; sm <= 1; ++sm) {
                for (int now = 0; now <= 9; ++now) {
                    if (!sm && now > s[i]) break;

                    add(dp[i + 1][(j + now) % d][sm || now < s[i]], dp[i][j][sm]);
                }
            }
        }
    }

    ll ans = 0;
    add(ans, dp[n][0][0]);
    add(ans, dp[n][0][1]);

    --ans;
    if (ans < 0)
        ans += MOD;

    cout << ans << '\n';
}

