// stanje:
// suma modulo D
// na kojoj smo znamenci
// jesan li dosad maksimalan broj ili ne

int add(const int& a, const int& b) {
    if(a + b >= MOD)
        return (a + b - MOD);
    return (a + b);
}

int subt(const int& a, const int& b) {
    if(a - b < 0)
        return (a - b + MOD);
    return (a - b);
}

int main() {
    int D, ans;
    string K;

    cin >> K >> D;
    int sz = K.size();

    if(K.size() == 1) {
        int cnt = 0;
        for(int i = 1; i <= K[0] - '0'; i++)
            if(i % D == 0)
                cnt ++;
        cout << cnt << endl;
        return 0;
    }

    for(int i = 0; i <= K[0] - '0' - 1; i++)
        dp[0][i] = 1;                         // inicijaliziras prvu znamenku svih koji su manji od 1. znam
    int sum_of_max = (K[0] - '0') % D;        // inicijaliziras ako je prva znamenka jednako velika ko broj

    for(int i = 0; i < sz - 1; i++) {
        int next_znam = K[i + 1] - '0';
        for(int j = 0; j < D; j++)
            for(int znam = 0; znam <= 9; znam++)
                dp[i + 1][(j + znam) % D] = add(dp[i + 1][(j + znam) % D], dp[i][j]);

        for(int znam = 0; znam <= next_znam - 1; znam++)
            dp[i + 1][(sum_of_max + znam) % D] = add(dp[i + 1][(sum_of_max + znam) % D], 1);
        sum_of_max = (sum_of_max + next_znam) % D;
    }

    if(sum_of_max == 0)                             // (+1) od K i (-1) od 0 se ubiju
        cout << dp[sz - 1][0] << endl;
    else                                            // inace makni 0
        cout << subt(dp[sz - 1][0], 1) << endl;

    return 0;
}

