int rec(int k, int s, int edge){
    if (k == n) return (s % d) == 0;
    if (dp[k][s][edge] != -1) return dp[k][s][edge];
    int lim = 9, resp = 0;
    if (edge) lim = ent[k] - '0';
    rep(i, 0, lim + 1){
        int nedge = edge && (i == lim);
        resp += rec(k + 1, (s + i) % d, nedge);
        resp %= mod;
    }
    return dp[k][s][edge] = resp;
}

