int cache[N][M][2];
int sz=0, x[N];

int dp(int idx, int rem, int less)
{
	if(idx==sz+1)
		return (rem==0);
	int &ans=cache[idx][rem][less];
	if(ans!=-1)
		return ans;
	ans=0;
	if(!less)
	{
		for(int i=0;i<=x[idx];i++)
			ans+=dp(idx+1, (rem+i)%d, less|(i<x[idx]));
	}
	else
	{
		for(int i=0;i<=9;i++)
			ans+=dp(idx+1, (rem+i)%d, 1);
	}
	ans%=MOD;
	return ans;
}

int f(string &s)
{
	sz=s.size();
	for(int i=1;i<=sz;i++)
		x[i]=(s[i-1]-'0');
	memset(cache, -1, sizeof(cache));
	return dp(1, 0, 0);
}

