    for(int i=0;i<=ub;i++)
    {
      if(i%sum==d)
      ans++;
    }
    return ans%mod;
  }
  if(dp[i][d][b])
  return dp[i][d][b]-1;
  for(int j=0;j<=ub;j++)
  {
    ans+=solve(i+1,(sum+d-j%sum)%sum,(b&&(j==ub)));
    ans=ans%mod;
  }
  dp[i][d][b]=ans+1;
  return ans;
}
