string k;
int d;
int dp[10010][110][2];

int digitdp(int pos,int sum,bool flag){

	if(pos == sz(k)) {
		return (sum == 0);
	}
//	if(sum != 0 and sum % d == 0) return 1;
	int &res = dp[pos][sum][flag];

	if(res != -1) return res;

	res = 0;   int limit = 9;	

	if(!flag) limit = k[pos] - '0';

	for(int i = 0;i <= limit;i++){
		bool current_flag = flag;

		if(!current_flag && i < limit) current_flag = true;

		res = (	res % MOD + digitdp(pos+1,(sum+i) % d,current_flag) % MOD ) % MOD;
	}
	return res ;
}
