ll solve(int i,int m,int isSmaller,int sz)
{
    if(i==sz) {
        if(m==0) return 1;
        return 0;
    }
    ll &ret = dp[i][m][isSmaller];
    if(ret!=-1) return ret;
    ret = 0;
    int j = 0;
