ll dp(int i, int tight, int digsum){
	if (mem.find({i, tight, digsum}) != mem.end()) return mem[{i, tight, digsum}];
	if (i == n) return (digsum == 0 ? 1 : 0);
	ll cnt = 0;
	int max_dig = tight ? lim[i] : 9;
