	ll D;
	cin >> K >> D;
	ll N = (ll)K.size();

	vvvmll dp(N, vvmll(D, vmll(2)));
	auto Dp = [&](ll i, ll d, ll s)->mll&{
		static mll zero = 0;
		static mll one = 1;
		if (i==-1 && d==0 && s==1) return one;
		if (i < 0) return zero;
		return dp[i][d][s];
	};

	REP(i, N)REP(d, D)REP(e, 10){
		Dp(i, (d+e)%D, 0) += Dp(i-1, d, 0);
		if (e < K[i]-'0'){
			Dp(i, (d+e)%D, 0) += Dp(i-1, d, 1);
		}
		else if (e == K[i]-'0'){
			Dp(i, (d+e)%D, 1) += Dp(i-1, d, 1);
		}
	}

	cout << Dp(N-1, 0, 0) + Dp(N-1, 0, 1)-1 << '\n';
}

