int rec(int n, int su, int rem){
    if(memo[n][su] != -1) return memo[n][su];
    int ans = 0;
    if(not n){
        ans = 1;
        if(su % rem) ans = 0;
    }
    else{
        for(int j = 0;j < 10;++j)
            ans = (ans + rec(n - 1, (su + j) % rem, rem)) % mod;
    }
    memo[n][su] = ans % mod;
    return ans % mod;
}



