constexpr LL mod = 1e9 + 7;

LL dp[10100][2][110];

LL f(string S, LL D, LL k = 0, bool tight = true, LL sum = 0) {

    if (k == S.size()) {
        return dp[k][tight][sum] = (sum == 0);
    }

    int x = S[k] - '0';

    int r = tight ? x : 9;

    LL &ret = dp[k][tight][sum];

    if (~ret)return ret;

    ret = 0;

    for (int i = 0; i <= r; i++) {
        ret += f(S, D, k + 1, tight && i == r, (sum + i) % D);
        ret %= mod;
    }

    return ret;
}

int main() {

    string K;
    LL D;
    cin >> K >> D;

    memset(dp, -1, sizeof(dp));

    cout << (f(K, D) - 1 + mod) % mod;

    return 0;
}

