long long P = 1000000000LL+7LL;
long long D;

long long dp[1000010][110][2];

long long f(int pos, long long sum , bool sw){
    if(pos == K.size()){
        if(sum%D == 0) return 1;
        else return 0;
    }
    if(dp[pos][sum][sw]!=-1) return dp[pos][sum][sw];
    long long re = 0;
    long long i = 0;
    if(sw == 0){
        for(i ; i < 10 ; i++){
            re = (re%P  + f(pos+1,(sum%D+i%D)%D,0)%P)%P;
        }
    }else{
        for( i; i <= int(K[pos]-'0') ; i++){
            if(i == int(K[pos]-'0')){
                re=(re%P +f(pos+1,(sum%D+i)%D,1)%P)%P;
            } 
            else re = (re%P +f(pos+1,(sum%D+i)%D,0)%P)%P;
        }
    }
    dp[pos][sum][sw] = re;
    return re;
}
int main(){
    while(cin>>K>>D){
        memset(dp,-1,sizeof dp);
        cout<<(f(0,0,1)-1)%P<<"\n";
    }
    return 0;
}

