ll kai_mod(ll x){
  if(x == 0) return 1;
  return x * kai_mod(x-1) % MOD;
}

//コンビネーション
const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

ll solve(ll D, string N){
  ll dp[N.size()+1][2][D];
  rep(i, N.size()+1)rep(j, 2)rep(k, D) dp[i][j][k] = 0;
  dp[0][0][0] = 1;
  rep(i, N.size()){
    ll x = N[i] - '0';
    rep(j, D){
      rep(k, x){
        dp[i+1][1][(j+k)%D] += dp[i][1][j];
        dp[i+1][1][(j+k)%D] += dp[i][0][j];
        dp[i+1][1][(j+k)%D] %= MOD;
      }
      dp[i+1][1][(j+x)%D] += dp[i][1][j];
      dp[i+1][0][(j+x)%D] += dp[i][0][j];
      dp[i+1][1][(j+x)%D] %= MOD;
      dp[i+1][0][(j+x)%D] %= MOD;
      for(ll k = x+1; k < 10; k++){
        dp[i+1][1][(j+k)%D] += dp[i][1][j];
        dp[i+1][1][(j+k)%D] %= MOD;
      }
    }
  }
  return ((dp[N.size()][1][0] + dp[N.size()][0][0] - 1) + MOD) % MOD;
}

int main(void){
  string N;
  cin >> N;
  ll D;
  cin >> D;
  cout << solve(D, N) << endl;
}

