mint dfs(int i, bool lower, int r) {
  // 上からi番目までの数字を決めた。
  // r: ここまで時点での余り
  r %= D;
  if (visited[i][lower][r])
    return dp[i][lower][r];
  if (i == N)
    return r == 0;
  mint ans = 0;
  if (lower) {
    rep(j, 10)
      ans += dfs(i+1, true, r+j);
    visited[i][lower][r] = true;
    return dp[i][lower][r] = ans;
  }
  int d = S[i]-'0';
  rep(j, d+1)
    ans += dfs(i+1, j < d, r+j);
  visited[i][lower][r] = true;
  return dp[i][lower][r] = ans;
}

