string k;
ll d;
ll dp[10001][101][2], mod = 1e9 + 7;
ll calc(ll pos, ll small, ll rem) {
	if(pos == k.length()) {
		if(rem == 0) {
			return 1;
		}
		return 0;
	}
	if(dp[pos][rem][small] != -1) {
		return dp[pos][rem][small];
	}
	int maxi = k[pos] - '0';
	if(small) {
		maxi = 9;
	}
	int ret = 0;
	for(int i = 0; i <= maxi; i++) {
		int nextSmall = small;
		if(i < maxi) {
			nextSmall = 1;
		}
		ll newRem = (rem + i) % d;
		ret = (ret + calc(pos + 1, nextSmall, newRem)) % mod;
	}
	return dp[pos][rem][small] = ret;
}
