LL dfs(int pos, bool lim, int sum) {
    if(pos == -1) return sum % D == 0;
    if(dp[pos][sum] != -1 && !lim) return dp[pos][sum];
    int up = lim ? a[pos] : 9;
    LL ans = 0;
    rep(i, 0, up) {
        ans = (ans + dfs(pos-1, lim && i == up, (sum + i) % D)) % mod;
    }
    if(!lim) dp[pos][sum] = ans;
    return ans;
}

