int dp(int x, int sum, bool less) {
  if (x == n) return sum == 0;
  int &ret = mem[x][sum][less];
  if (solved[x][sum][less]) return ret;
  solved[x][sum][less] = 1;

  int k = less == 0 ? C[x] - '0' : 9;
  for (int i = 0; i <= k; ++i) {
    ret = (ret + dp(x+1, (sum+i) % d, less | (i < (C[x] - '0')))) % MOD;
  }

  return ret;
}

