ll solve(int pos,int rem,int f)
{
    if(pos == n)
    {
        if(rem%d == 0)
        {
            return 1;
        }
        return 0;
    }

    ll &res = dp[pos][rem][f];
    if(~res)
        return res;

    int limit;
    res = 0;

    if(f == 0)
    {
        limit = str[pos] - '0';
    }
    else
        limit = 9;

    for(int i=0;i<=limit;i++)
    {
        int nf = f;
        int div = rem;
        if(f == 0 && i < limit)
            nf= 1;
        div = (rem+i)%d;
        res += solve(pos+1,div,nf);
        res %= mod;
    }
    //cout << pos << " " << rem <<  " " << res << "\n";
    return res;
}

