int memo[10001][2][101];
int go(int n = 0, bool lt = false, int rem = 0) {
   if (n >= SZ(K))
      return rem == 0 ? 1 : 0;
   int& res = memo[n][lt][rem];
   if (res < 0) {
      res = 0;
      FOR(d, 0, lt ? 9 : K[n]-'0') {
         res += go(n+1, lt || (d < K[n]-'0'), (rem + d) % D);
         if (res >= MOD)
            res -= MOD;
      }
   }
   return res;
}

