			}
			ans+=call(i+1,(sum+j)%num,temo);
		}
		dp[i][sum][edge?1:0]=ans%mod;
		return ans%mod;

	}
	static void memset() {

		for(int i=0;i<dp.length;i++) {
			for(int j=0;j<dp[i].length;j++) {
