    static class SDigitSum {
        static int[] arr;
        static int m;
        static int mod = (int) 1e9 + 7;
        static Integer[][][][] memo;

        public void solve(int testNumber, Scanner sc, PrintWriter pw) {
            String tmp = sc.next();
            arr = new int[tmp.length()];
            for (int i = 0; i < arr.length; i++)
                arr[i] = tmp.charAt(i) - '0';
            m = sc.nextInt();
            memo = new Integer[2][2][m][arr.length];
            int s = dp(0, 0, 0, 0) % mod;
            pw.println(s);
        }

        private int dp(int idx, int s, int rem, int NonZero) {
            if (idx == arr.length)
                return rem == 0 && NonZero == 1 ? 1 : 0;
            boolean small = s == 1;
            int end = small ? 9 : arr[idx];
            int sum = 0;
            if (memo[s][NonZero][rem][idx] != null)
                return memo[s][NonZero][rem][idx];
            for (int i = 0; i <= end; i++) {
                sum += dp(idx + 1, i < arr[idx] ? 1 : s, (rem + i) % m, i != 0 ? 1 : NonZero);
                sum %= mod;
            }
            return memo[s][NonZero][rem][idx] = sum;
        }

    }

