	private static long f(int i, int m, int l) {
		if(i == s.length) {
			if(m == 0) return 1;
			return 0;
		}
		if(dp[i][m][l] != -1) return dp[i][m][l];
		long o1 = 0;
		int end = (l==1)?s[i]-'0':9;
		for(int dig=0;dig<=end;++dig) {
			o1 = (o1 + f(i+1,(m+dig)%d,l&((dig == end)?1:0)))%mod;
		}
		return dp[i][m][l] = o1;
	}



    }

