        public long calc(int pos, boolean eq, int m) {

            int ei = eq ? 1 : 0;

            if (dp[pos][ei][m] >= 0) return dp[pos][ei][m];
            if (pos >= n) {
                dp[pos][ei][m] = (m == 0) ? 1 : 0;
                return dp[pos][ei][m];
            }

            long res = 0l;

            int cc = (int)N.charAt(pos) - (int)'0';
            int mx = eq ? cc : 9;


            for (int d = 0; d <= mx; d++) {
                int rm = (m + D * 1000 - d) % D;
                res += calc(pos + 1, eq && (d == cc), rm);
                res %= mod;
            }

            dp[pos][ei][m] = res;
            return res;
        }

