public class Main {

    static String K;
    static int D;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        K = sc.next();
        D = sc.nextInt();

        System.out.println(solve());
    }

    static int MOD = 1_000_000_007;

    static long solve() {
        int n = K.length();
        int tight = 0;
        long[] dp = new long[D];
        for (int i = 0; i < n; i++) {

            // 前の分に単純に足す
            // K * D * 10 なので間に合う
            long[] next = new long[D];
            for (int j = 0; j < D; j++) {
                for (int k = 0; k <= 9; k++) {
                    next[(j+k)%D] += dp[j];
                }
            }

            // tightの以降tightではない分について追加する
            int c = K.charAt(i) - '0';
            for (int j = 0; j < c; j++) {
                next[(j+tight)%D]++;
            }
            tight += c;

            for (int j = 0; j < D; j++) {
                next[j] %= MOD;
            }
            dp = next;
        }

        // tightの分が抜けてるので足す
        dp[tight%D]++;
        dp[tight%D] %= MOD;

        // 0は範囲外なので減らす
        // 減らしすぎに注意
        long ans = dp[0]-1;
        if( ans < 0 ) ans += MOD;
        return ans;
    }

