      for (int s = 0; s < d; s ++) {
        for (int t = 0; t < 10; t ++) {
          dp[i - 1][(s + t) % d][0] += dp[i][s][0];

          if (t < kd) {
            dp[i - 1][(s + t) % d][0] += dp[i][s][1];
