		{
			ans[i]=Long.valueOf(cmd[i]);
		}
		return ans;
	}
	static long p=1000000007;
	static long[][][]dp;
	static String s;
	static int n;
	static int k;
	static long count(int ind,int mod,int st)
	{
		if(ind==n && mod==0)
			return 1;
		if(ind==n)
			return 0;
		if(dp[ind][mod][st]!=-1)
			return dp[ind][mod][st];
		int x=s.charAt(ind)-'0';
		if(st==0)
			x=9;
		long res=0;
		for(int i=0;i<=x;i++)
		{
			int status=(st==1 && i==x)?1:0;
			res=(res+count(ind+1,(mod+i)%k,status));
		}
		dp[ind][mod][st]=res;
		return res;
	}
