public class Main implements Runnable {
	FastReader scn;
	PrintWriter out;
	String INPUT = "";

	void solve() {
		char[] arr = scn.next().toCharArray();
		int d = scn.nextInt(), mod = (int) 1e9 + 7;

		int[][] dp = new int[d][2];
		dp[0][0] = 1;
		for (char c : arr) {
			int curr = c - '0';
			int[][] ndp = new int[d][2];

			for (int sum = 0; sum < d; sum++) {
				for (int is_small : new int[] { 0, 1 }) {
					for (int dig = 0; dig < 10; dig++) {
						if (dig > curr && is_small == 0) {
							break;
						}

						int ind = (is_small == 1 || dig < curr) ? 1 : 0;
						ndp[(sum + dig) % d][ind] += dp[sum][is_small];
						if (ndp[(sum + dig) % d][ind] >= mod) {
							ndp[(sum + dig) % d][ind] -= mod;
						}
					}
				}
			}
			dp = ndp;
		}

		int ans = (dp[0][0] + dp[0][1] - 1) % mod;
		out.println(Math.max(0, ans));
	}

	public void run() {
		long time = System.currentTimeMillis();
		boolean oj = true;
		out = new PrintWriter(System.out);
		scn = new FastReader(oj);
		solve();
		out.flush();
		if (!oj) {
			System.out.println(Arrays.deepToString(new Object[] { System.currentTimeMillis() - time + " ms" }));
		}
	}

