        public static long fun(int vis,int a[][],int n,long dp[][]){
            if(n<0)
            return 1;
            if(dp[n][vis]!=-1)
            return dp[n][vis];
            int l=a.length;
            dp[n][vis]=0;
            for(int i=0;i<l;i++){
                if(a[n][i]==1&&(vis&(1<<i))==0){
                    //vis|=(1<<i);
                    dp[n][vis]+=fun(vis|(1<<i), a, n-1,dp);
                    //vis^=(1<<i);
                    dp[n][vis]%=mod;
                }

            }
            return dp[n][vis];
        }

        public static int fun(int i,int k,int a[]){
            if(k==0){
                return a[i];
            }
            int j=1;
            while(k-2*j>0){
                j=2*j;
            }
            return fun(i, k-j, a)^fun(i+j, k-j, a);
        }
        public static long[][] multiply(long a[][], long b[][]) 
    { 
        long mul[][] = new long[a.length][b[0].length]; 
        for (int i = 0; i < a.length; i++) 
        { 
            for (int j = 0; j < b[0].length; j++) 
            { 
                mul[i][j] = 0; 
                for (int k = 0; k < a[0].length; k++) 
                    mul[i][j] += (a[i][k]* b[k][j])%mod;
                    mul[i][j] %= mod;
            }
        }

        return mul;

    } 

