	// f==1 bound f==0 no bound
	public static long Solve(int pos, int sum, int f) {
		int lmt = f == 1 ? a.charAt(pos) - '0' : 9;

		if (pos == a.length() - 1) {
			int ans = 0;
			//System.out.println(sum+" "+lmt);
			for (int d = 0; d <= lmt; d++) {
				int x1 = sum + d;
				//System.out.println(x1);
				if (x1 % div == 0)
				{
					//System.out.println(x1);
					ans++;
				}
			}
			return ans;

		}
		if (dp[pos][sum][f] == -1) {
			long res = 0;
			for (int d = 0; d <= lmt; d++) {

				int nf = f;
				if (f == 1 && d < a.charAt(pos) - '0')
					nf = 0;

				res = (res + Solve(pos + 1, sum + d, nf)) % m;

			}
			dp[pos][sum][f]=res;

		}
		return dp[pos][sum][f];

	}

