		dp2[0][0] = 1;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < d; j++) {
				for (int kk = 0; kk < 10; kk++) {
					dp[(j + kk) % d][i + 1] += dp[j][i];
					dp[(j + kk) % d][i + 1] %= MOD;

					if (kk < k[n - 1 - i] - '0') {
						dp2[(j + kk) % d][i + 1] += dp[j][i];
						dp2[(j + kk) % d][i + 1] %= MOD;
					} else if (kk == k[n - 1 - i] - '0') {
						dp2[(j + kk) % d][i + 1] += dp2[j][i];
						dp2[(j + kk) % d][i + 1] %= MOD;
					}
				}
			}
		}

