        for(int j = 1; j <= s.length(); j++){
            for(int i = 0; i < D; i++){
                for(int k = 0; k <= 9; k++){
                    dp[(i+k)%D][j] += dp[i][j-1];
                    dp[(i+k)%D][j] %= MOD;
                    if(k < N[j]) dp2[(i+k)%D][j] += dp[i][j-1];
                    else if(k == N[j]) dp2[(i+k)%D][j] += dp2[i][j-1];
                    dp2[(i+k)%D][j] %= MOD;                }
            }
        }
        System.out.println(dp2[0][s.length()] -1);

