	// cons==0 means we are tighting the limit
	public static long Solve(int pos, int sum, int f) {
		// Base Case
		int lmt = 9;
		if (f == 0)
			lmt = k.charAt(pos) - '0';

		if (pos == k.length() - 1) {
			int ans = 0;
			for (int d1 = 0; d1 <= lmt; d1++) {
				if(d1%d==sum) ans++;
			}

			return ans;
		}

		if (dp[pos][sum][f] != -1)
			return dp[pos][sum][f];

		long ans = 0;
		for (int d1 = 0; d1 <= lmt; d1++) {
			int nf = f;
			if (f == 0 && d1 < k.charAt(pos) - '0')
				nf = 1;
			// System.out.println(d1+" "+nf);
			long res = Solve(pos + 1, (sum-d1%d+d)%d, nf);
			ans = (ans+res)%m;

		}

		dp[pos][sum][f] = ans;

		return dp[pos][sum][f];
	}

