                    dpPrev[i][j] = dpNext[i][j];
                }
//                System.out.println(Arrays.toString(dpPrev[i]));
            }
        }
        long ans = (dpPrev[0][0] + dpPrev[1][0] - 1 + mod) % mod;
        out.println(ans);
