        char c[];
        int d;

        void solve() {
            c = sc.sn().toCharArray();
            n = c.length;
            d = sc.ni();
            fill();
            out.println(digit(0, 0, 0) - 1);
        }

        long dp[][][] = new long[10000][2][101];

        void fill() {
            for (int i = 0; i < 10000; i++) {
                for (int j = 0; j < 2; j++)
                    for (int k = 0; k < 101; k++)
                        dp[i][j][k] = -1;
            }
        }

        long digit(int i, int t, int r) {
            if (i == n) {
                if (r == 0)
                    return 1;
                return 0;
            }
            if (dp[i][t][r] != -1)
                return dp[i][t][r];
            int limit = (t == 1) ? 9 : (c[i] - '0');
            long res = 0;
            for (int j = 0; j <= limit; j++) {
                int cur = t;
                if (j < (c[i] - '0'))
                    cur = 1;
                res = (res + digit(i + 1, cur, (r + j) % d)) % mod;
            }
            return dp[i][t][r] = (res + mod) % mod;
        }
