class SolS {
    int[][] dp;
    char[] k;
    int d, mod = 1000000007;
    long tres;

    SolS(char[] k, int d){
        this.k = k;
        this.d = d;
        dp = new int[d][2];
    }

    void sol(){
        dp[0][1] = 1;

        for(int st = 0, end = k.length; st < end; ++st){
            int[][] newdp = new int[d][2];
            int lim = k[st] - '0';
            for(int s = 0; s < 2; ++s){
                for(int j = 0; j < 10; ++j){
                    if(s == 1 && j > lim)
                        break;
                    for(int i = 0; i < d; ++i){
                        if(s == 0){
                            // i.e for number of solutions which are smaller than k
                            tres = newdp[(i+j)%d][0] + dp[i][0];
                            if(tres >= mod)
                                tres -= mod;
                            newdp[(i+j)%d][0] = (int) tres;         
                        }
                        else {
                            // i.e for k itself
                            if(j == lim){
                                tres = newdp[(i+j)%d][1] + dp[i][1];
                                if(tres >= mod)
                                    tres -= mod;
                                newdp[(i+j)%d][1] = (int) tres;  
                            }
                            // i.e for number of solutions which are smaller than k
                            else {
                                tres = newdp[(i+j)%d][0] + dp[i][1];
                                if(tres >= mod)
                                    tres -= mod;
                                newdp[(i+j)%d][0] = (int) tres;  
                            }
                        }
                    }
                }
            }
            dp = newdp;
        }
        System.out.println(dp[0][0] + dp[0][1] - 1);
    }

}

