    public static long recurse(int pos,int rem,int state)
    {
    	if(pos==str.length())
    	{
    		//System.out.println("rem is "+rem);
    		if(rem==0)
    			return 1;
    		return 0;
    	}
    	if(dp[pos][rem][state]!=0)
    		return (dp[pos][rem][state]%mod-1)%mod;
    	int cur=(int)str.charAt(pos)-(int)'0';
    	int limit=(int)str.charAt(pos)-(int)'0';
    	if(state==1)
    		limit=9;

    	long ans=0;
    	for(int i=0;i<=limit;i++)
    	{
    		int ns=state;
    		if(state==0&&i<cur)
    			ns=1;
    		//System.out.println(pos+" "+i);
    		int nr=(rem+i)%d;
    		ans=(ans+recurse(pos+1,nr,ns))%mod;
    	}
    	dp[pos][rem][state]=(ans%mod+1)%mod;
    	return ans;
    }
