public class Main {

	final boolean isDebug = false;
	String fileName = "input.txt";
	FastScanner sc;
	//PrintWriter out;
	final int MOD = 1000000007;
	final int INF = Integer.MAX_VALUE / 2;

	/* solve */
	void solve(){
		String K = sc.next();
		int D = sc.nextInt();

		long[][][] dp = new long[K.length()+1][2][D];

		dp[0][0][0] = 1;

		for(int i = 0; i < K.length(); i++){
			int digit = Integer.valueOf(K.charAt(i) - '0');
			for(int j = 0; j <= 1; j++){
				for(int k = 0; k < D; k++){
					for(int d = 0; d <= ((j == 1) ? 9 : digit); d++){
						int nextJ = (j == 1 || d < digit) ? 1 : 0;
						int nextK = (k + d) % D;
						dp[i+1][nextJ][nextK] += dp[i][j][k];
						dp[i+1][nextJ][nextK] %= MOD;
					}
				}
			}
		}

		long ans = dp[K.length()][1][0] + dp[K.length()][0][0] - 1;
		ans %= MOD;
		if(ans < 0) ans += MOD;

		System.out.println(ans);
	}

	/* end solve */

