					dp[i][k][1]+=(dp[i-1][((k-j)%D+D)%D][0]+dp[i-1][((k-j)%D+D)%D][1])%MOD;
					dp[i][k][1]%=MOD;
				}
			}
			for (int j = 0; j < D; j++) {
				dp[i][j][0]+=dp[i-1][((j-c)%D+D)%D][0];
				dp[i][j][0]%=MOD;
				dp[i][j][1]+=dp[i-1][((j-c)%D+D)%D][1];
				dp[i][j][1]%=MOD;
			}
