public class Main
{
    static int n,k;
    static int m[];
    static int dp[][],dp1[][][];
    static int M=(int)1e9+7;
    static int solve(int i,int sum)
    {
        if(i==n)
        {
            if(sum==0)
                return 1;
            else
                return 0;
        }
        if(dp[i][sum]!=-1)
            return dp[i][sum];
        dp[i][sum]=0;
        for(int ii=0;ii<=9;ii++)
        {
            dp[i][sum]=(dp[i][sum]%M+solve(i+1,(sum+ii)%k)%M)%M;
        }
        return dp[i][sum]%M;
    }
    static int solve1(int i,int sum,int kk)
    {
        if(i==n+1)
        {
            if(sum==0)
            {
                return 1;
            }
            else
                return 0;
        }
        if(dp1[i][sum][kk]!=-1)
            return dp1[i][sum][kk];
        dp1[i][sum][kk]=0;
        if(kk==0)
        {
            for(int ii=0;ii<m[i];ii++)
            {
                if(i==1&&ii==0)
                    continue;
                dp1[i][sum][kk] = (dp1[i][sum][kk] % M + solve1(i + 1, (sum + ii) % k, 1) % M) % M;
            }
            dp1[i][sum][kk]=(dp1[i][sum][kk]%M+solve1(i+1,(sum+m[i])%k,0)%M)%M;
        }
        else
        {
            for (int ii = 0; ii <= 9; ii++)
                dp1[i][sum][kk] = (dp1[i][sum][kk] % M + solve1(i + 1, (sum + ii) % k, 1) % M) % M;
        }
        return dp1[i][sum][kk];
    }
