        if(pos == str.length()){
            if(sum%d == 0)
                return 1;
            return 0;
        }
        if(dp[pos][sum][tight] != -1){
            return dp[pos][sum][tight];
        }
        long ans = 0;
        int len = 9;
        if(tight == 1){
            len = str.charAt(pos)-'0';
        }
        for(int i = 0; i <= len; i++){
            int newt = 0;
            if(tight == 1 && i == len){
                newt = 1;
            }
            ans += solve(pos+1, (sum + i)%d, newt)%mod;
        }
        return dp[pos][sum][tight] = ans%mod;
    }
