	static int dp(int idx,int mod,int equal) {
		if(idx==x.length)
			return mod>0?0:1;
		if(memo[equal][mod][idx]!=-1)
			return memo[equal][mod][idx];
		int up=equal==1?x[idx]:9;
		int ans=0;
