            String K = nstr(sc);
            int D = nint(sc);
            int mod = 1000000007;

            int length = K.length();
            long[][][] dp = new long[length + 1][2][D];
            dp[0][0][0] = 1;

            for (int i = 0; i < length; i++) {
                for (int j = 0; j < 2; j++) {
