                            x = K.charAt(i) - '0';
                        }
                        for (int d = 0; d < x + 1; d++) {
                            if (j == 1){
                                dp[i + 1][1][(k + d) % D] += dp[i][j][k];

                            }else if (d < x){
                                dp[i + 1][1][(k + d) % D] += dp[i][j][k];

                            }else{
                                dp[i + 1][0][(k + d) % D] += dp[i][j][k];

                            }
                            dp[i + 1][0][(k + d) % D] %= mod;
                        }
                    }
                }
            }
            long ans = 0;
            for (int i = 0; i < 2; i++) {
                ans += dp[length][i][0];
