public class Main {
    static final int UNCALC = -1;
    static final int INF = (int) 1e9;
    static final int mod = (int) (1e9 + 7);
    static char[] num;
    static int d, n;
    static int memo[][][];

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        num = sc.next().toCharArray();
        d = sc.nextInt();
        n = num.length;
        memo = new int[2][d][n];
        for (int[][] a : memo)
            for (int[] b : a)
                Arrays.fill(b, UNCALC);
        out.println(dp(1, 0, 0) - 1);
        out.flush();
        out.close();
    }

    static int dp(int isequal, int i, int sum) {
        if (i == n)
            return sum == 0 ? 1 : 0;
        if (memo[isequal][sum][i] != UNCALC)
            return memo[isequal][sum][i];
        int cnt = 0;
        int end = (isequal == 1 ? num[i] : '9') - '0';
        for (int j = 0; j <= end; j++) {
            int nf = (num[i] - '0' == j ? isequal : 0);
            int nsum = (sum + j) % d;
            cnt = (cnt + dp(nf, i + 1, nsum)) % mod;
        }
        return memo[isequal][sum][i] = cnt;
    }


