		if (pos == a.length() - 1) {
			int ans = 0;
			//System.out.println(sum+" "+lmt);
			for (int d = 0; d <= lmt; d++) {

				//System.out.println(sum+d);
				if (d%div==(div-sum)%div)
				{
					//System.out.println(sum);
					ans++;
				}
			}
			return ans;

		}
		if (dp[pos][sum][f] == -1) {
			long res = 0;
