    static class Task {
        void solve(Scanner sc, PrintWriter out) {
            String K = nstr(sc);
            int D = nint(sc);
            int mod = 1000000007;

            int length = K.length();
            long[][][] dp = new long[length + 1][2][D];
            dp[0][0][0] = 1;

            for (int i = 0; i < length; i++) {
                for (int j = 0; j < 2; j++) {
                    for (int k = 0; k < D; k++) {
                        int x;
                        if (j == 1) {
                            x = 9;
                        } else {
                            x = K.charAt(i) - '0';
                        }
                        for (int d = 0; d < x + 1; d++) {
                            if (j == 1){
                                dp[i + 1][1][(k + d) % D] += dp[i][j][k];

                            }else if (d < x){
                                dp[i + 1][1][(k + d) % D] += dp[i][j][k];

                            }else{
                                dp[i + 1][0][(k + d) % D] += dp[i][j][k];

                            }
                            dp[i + 1][0][(k + d) % D] %= mod;
                        }
                    }
                }
            }
            long ans = 0;
            for (int i = 0; i < 2; i++) {
                ans += dp[length][i][0];
                ans %= mod;
            }
            out.println((ans-1) % mod);
        }
    }

