    public static long recurse(int pos,int rem,int state)
    {
    	if(pos==str.length())
    	{
    		//System.out.println("rem is "+rem);
    		if(rem==0)
    			return 1;
    		return 0;
    	}
    	if(dp[pos][rem][state]!=-1)
    		return (dp[pos][rem][state]);
    	int cur=(int)str.charAt(pos)-(int)'0';
    	int limit=(int)str.charAt(pos)-(int)'0';
    	if(state==1)
    		limit=9;

    	long ans=0;
