    static class Reader {
        final private int BUFFER_SIZE = 1 << 16;
        private DataInputStream din;
        private byte[] buffer;
        private int bufferPointer, bytesRead;

        public Reader() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public Reader(String file_name) throws IOException {
            din = new DataInputStream(new FileInputStream(file_name));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        public static void pr(Object s) {
            System.out.println(s);
        }

        public int ni() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            } while ((c = read()) >= '0' && c <= '9');

            if (neg)
                return -ret;
            return ret;
        }

        public long nl() throws IOException {
            long ret = 0;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();
            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');
            if (neg)
                return -ret;
            return ret;
        }

        public String rl() throws IOException {
            byte[] buf = new byte[1024]; // line length
            int cnt = 0, c;
            while ((c = read()) != -1) {
                if (c == '\n')
                    break;
                buf[cnt++] = (byte) c;
            }
            return new String(buf, 0, cnt);
        }

        public double nd() throws IOException {
            double ret = 0, div = 1;
            byte c = read();
            while (c <= ' ')
                c = read();
            boolean neg = (c == '-');
            if (neg)
                c = read();

            do {
                ret = ret * 10 + c - '0';
            }
            while ((c = read()) >= '0' && c <= '9');

            if (c == '.') {
                while ((c = read()) >= '0' && c <= '9') {
                    ret += (c - '0') / (div *= 10);
                }
            }

            if (neg)
                return -ret;
            return ret;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1)
                buffer[0] = -1;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead)
                fillBuffer();
            return buffer[bufferPointer++];
        }

        public void close() throws IOException {
            if (din == null)
                return;
            din.close();
        }
    }
}

import java.util.*;
import java.io.*;

 class Main {
    static long global_mod = 1000000007;
    static long dp[][][];

   public static long solve2(String str, int pos, int mod, int d, int tight){
		if(pos >= str.length()){
			if(mod%d == 0)
				return 1;
			return 0;
		}

        if( dp[pos][mod][tight] != -1)
            return  dp[pos][mod][tight];

		long ans = 0;

		int allowed = tight == 1 ? str.charAt(pos)-'0' : 9;

		for(int i = 0; i <= allowed; i++){
			if(i == allowed && tight == 1)
				ans += solve2(str,pos+1, (mod +i )%d ,d ,1)%global_mod;


			else
				ans += solve2(str,pos+1,(mod  + i)%d,d,0)%global_mod;
		}

		return dp[pos][mod][tight] = ans%global_mod;

	}

	public static void main(String[] args) throws Exception {
	    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
	    String s = br.readLine().trim();
	    int d = Integer.parseInt(br.readLine().trim());

	    dp = new long[s.length()+1][d+1][3];

	    for(int i = 0; i < dp.length; i++){
	        for(int j = 0;j <= d; j++){
	            Arrays.fill(dp[i][j],-1l);
	        }
	    }

		System.out.println(solve2(s,0,0,d,1)-1);
	}
}

