    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public int readString(int[] data, int offset) {
            skipBlank();

            int originalOffset = offset;
            while (next > 32) {
                data[offset++] = (char) next;
                next = read();
            }

            return offset - originalOffset;
        }

    }

    static class Modular {
        int m;

        public Modular(int m) {
            this.m = m;
        }

        public Modular(long m) {
            this.m = (int) m;
            if (this.m != m) {
                throw new IllegalArgumentException();
            }
        }

        public Modular(double m) {
            this.m = (int) m;
            if (this.m != m) {
                throw new IllegalArgumentException();
            }
        }

        public int valueOf(int x) {
            x %= m;
            if (x < 0) {
                x += m;
            }
            return x;
        }

        public int plus(int x, int y) {
            return valueOf(x + y);
        }

        public int subtract(int x, int y) {
            return valueOf(x - y);
        }

        public String toString() {
            return "mod " + m;
        }

    }

    static class SequenceUtils {
        public static void deepFill(Object array, int val) {
            if (!array.getClass().isArray()) {
                throw new IllegalArgumentException();
            }
            if (array instanceof int[]) {
                int[] intArray = (int[]) array;
                Arrays.fill(intArray, val);
            } else {
                Object[] objArray = (Object[]) array;
                for (Object obj : objArray) {
                    deepFill(obj, val);
                }
            }
        }

    }

    static class DigitUtils {
        private DigitUtils() {
        }

        public static int mod(int x, int mod) {
            x %= mod;
            if (x < 0) {
                x += mod;
            }
            return x;
        }

    }
}

import java.util.*;
import java.io.*;
class Main {
    static long MOD = (long)(1e9+7);
    static long[][][] dp;
    static long recurse(String s, int mod, int idx, boolean isTight, int currRem) {
        if(idx==s.length()) {
            if(currRem==0)
                return 1;
            return 0;
        }
        int secIdx = isTight?1:0;
        if(dp[idx][secIdx][currRem]!=-1)
            return dp[idx][secIdx][currRem];
        int limit = 9;
        int currDig = s.charAt(idx)-'0';
        if(isTight)
            limit = currDig;
        long ans = 0;
        for(int i = 0; i<=limit; i++) {
            boolean newTight = isTight;
            if(i<limit)
                newTight = false;
            int newRem = (currRem+i)%mod;
            ans = (ans + recurse(s, mod, idx+1, newTight, newRem))%MOD;
        }
        return dp[idx][secIdx][currRem] = ans;
    }
    public static void main (String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        int rem = sc.nextInt();
        dp = new long[s.length()][2][rem];
        for(long[][] i: dp)
            for(long[] j: i)
                Arrays.fill(j, -1);
        long ans = (recurse(s, rem, 0, true, 0)+MOD-1)%MOD;
        System.out.println(ans);
    }
}

