		long[] dp = new long[D];
		for(int i = 0;i < n;i++){
			long[] ndp = new long[D];
			for(int j = 0;j < D;j++){
				for(int k = 0, l = j;k < 10;k++,l++){
					if(l == D)l = 0;
					ndp[l] += dp[j];
				}
			}

			if(i == 0){
				for(int j = 1;j < s[i]-'0';j++){
					ndp[j%D]++;
				}
			}else{
				for(int j = 0;j < s[i]-'0';j++){
					ndp[(j+e)%D]++;
				}
				for(int j = 1;j <= 9;j++){
					ndp[j%D]++;
				}
			}
			e += s[i]-'0';
			e %= D;

			for(int j = 0;j < D;j++)ndp[j] %= mod;
			dp = ndp;
		}
		dp[e]++;
		out.println((dp[0]%mod));
	}

