            dp=new long[n+1][k+1];
            dp1=new long[n+1][k+1][2];
            for(int i=1;i<=n;i++)
            {
                char c=s.charAt(i-1);
                int d=(int)c-(int)'0';
                m[i]=d;
            }
            for(int i=0;i<=n;i++)
                Arrays.fill(dp[i],-1);
            for(int i=0;i<=n;i++)
            {
                for(int j=0;j<=k;j++)
                {
                    for(int jj=0;jj<=1;jj++)
                        dp1[i][j][jj]=-1;
                }
            }
