        static int solvedp(string s, int[][][] dp, int k, bool free, int d, int sum)
        {
            if (dp[k][sum][free ? 1 : 0] >= 0)
            {
                return dp[k][sum][free ? 1 : 0];
            }

            if (k >= s.Length)
            {
                if (sum > 0 && (sum % d) == 0) return 1;
                else return 0;
            }

            var x = s[k] - '0';
            var l = free ? 9 : x;
            var count = 0;
            for (int i = 0; i <= l; i++)
            {
                count += solvedp(s, dp, k + 1, free || i < l, d, sum + i);
                count %= MOD;
            }

            dp[k][sum][free ? 1 : 0] = count;

            return count;
        }

