using System;
using System.Collections.Generic;
class Program{
	const int mod=1000000007;
	static void Main(){
		string s=Console.ReadLine();
		int e=int.Parse(Console.ReadLine());
		int n=s.Length,ans=0;
		int[,,] dp=new int[n+1,2,e];
		dp[0,0,0]=1;
		for(int i=0;i<n;i++){
			for(int j=0;j<2;j++){
				for(int l=0;l<e;l++){
					int lm=j==0?s[i]-'0':9;
					for(int d=0;d<=lm;d++){
						dp[i+1,(j==1||d<lm)?1:0,(l+d)%e]+=dp[i,j,l];
						dp[i+1,(j==1||d<lm)?1:0,(l+d)%e]%=mod;
					}
				}
			}
		}
		for(int j=0;j<2;j++){ans+=dp[n,j,0];}
		if(n<4&&int.Parse(s)==e){Console.WriteLine(1);}
		else{Console.WriteLine(ans-1);}
	}
}

