        static void Solve()
        {
            var K = Cin.Str;
            var D = Cin.Int;
            int L = K.Length;
            var dp = new ModInt[D, 2];
            dp[0, 0] = 1;
            for(var i = 0; i < L; i++)
            {
                var dp2 = new ModInt[D, 2];
                int m = K[i] - '0';
                for(var j = 0; j < D; j++)
                {
                    dp2[(j + m) % D, 0] += dp[j, 0];
                    for(var k = 0; k <= 9; k++)
                    {
                        dp2[(j + k) % D, 1] += dp[j, 1];
                        if (k < m) dp2[(j + k) % D, 1] += dp[j, 0];
                    }
                }
                dp = dp2;
            }
            OutL((dp[0, 0] + dp[0, 1] - 1).value);
        }

        public struct Edge
