    int count = 0;
    while (k > 0)
    {
      int digitsSum = SumDigits(k.ToString());
      if (k % d == 0)
        count++;
      k--;
    }
    Console.WriteLine(count);
  }

  public static int SumDigits(ReadOnlySpan<char> k)
  {
    if (k.Length == 0) return 0;
    if (k.Length == 1) return k[1] - '0';
    return (k[0] - '0') + SumDigits(k.Slice(1, k.Length));
  }
}

