		static void Main()
		{
			var cin = new Scanner();
			string k = cin.Next();
			int d = cin.Int();
			int n = k.Length;

			var dpKa = new ModInt[n, d];
			var dpMi = new ModInt[n, d];
			int first = k[0] - '0';
			for (int m = 0; m < 10; m++) {
				if (m < first) {
					dpKa[0, m % d] += 1;
				} else if (m == first) {
					dpMi[0, m % d] += 1;
				}
			}
			dpKa[0, 0] = 1;

			for (int i = 0; i < n - 1; i++) {
				int num = k[i + 1] - '0';
				for (int j = 0; j < d; j++) {
					for (int m = 0; m < 10; m++) {
						int t = (j + m) % d;
						if (m < num) {
							dpKa[i + 1, t] += dpKa[i, j] + dpMi[i, j];
						} else if (m == num) {
							dpMi[i + 1, t] += dpMi[i, j];
							dpKa[i + 1, t] += dpKa[i, j];
						} else {
							dpKa[i + 1, t] += dpKa[i, j];
						}
					}
				}
			}

			ModInt ans = dpKa[n - 1, 0] + dpMi[n - 1, 0] - 1;
			Console.WriteLine(ans.Value);
		}
	}

	public struct ModInt
	{
		public static long P { get; set; } = (long)1e9 + 7;

		public static ModInt Pow(ModInt value, long k)
		{
			return Pow(value.Value, k);
		}

		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}

		public static ModInt Inverse(ModInt value)
		{
			return Pow(value, P - 2);
		}

		public long Value;

		public ModInt(long value)
		{
			value %= P;
			if (value < 0) {
				value += P;
			}

			Value = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.Value += rhs.Value;
			if (lhs.Value >= P) {
				lhs.Value -= P;
			}
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.Value -= rhs.Value;
			if (lhs.Value < 0) {
				lhs.Value += P;
			}

			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			return new ModInt(lhs.Value * rhs.Value % P);
		}
		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n)
		{
			n %= P;
			if (n < 0) {
				n += P;
			}

			return new ModInt(n);
		}

		public override string ToString()
		{
			return Value.ToString();
		}
	}

