    public class Program
    {
        public object Calc()
        {
            var K = consoleReader.String.Select(c => c - '0').ToArray();
            var D = consoleReader.Int;

            var dp = new Mod[K.Length, D, 2];
            for (int k = 0; k < K[0]; k++)
