	public class Solver : SolverBase
	{
		public void Run() {
			string S = ReadString();
			var D = ReadInt();

			// 桁DP
			// dp[桁][Dの余り][制限あり?]=パターン数modD

			var dp = new long[10005, 101, 2];
			dp[0, 0, 1] = 1;

			for (int i = 0; i < S.Length; i++) {
				for (int j = 0; j < 101; j++) {
					for (int k = 0; k < 2; k++) {
						var cnt = dp[i, j, k];
						if (cnt == 0) continue;

						var ni = i + 1;
						var sn = S[i] - '0';

						for (int n = 0; n < 10; n++) {
							int nj = (j + n) % D;
							var nk = k;
							if (k == 1) {
								// Sを上回っている場合はどこにも遷移しない
								if (sn < n) continue;

								if (sn == n) {
									// Sと同じなのでやはり 制約あり に遷移する
								} else if (n < sn) {
									// Sを下回っったので 制約なし に遷移する
									nk = 0;
								}
							} else {
								// 制約なし からは 制約なし にしか遷移しない
							}

							dp[ni, nj, nk] = (dp[ni, nj, nk] + dp[i, j, k]) % MOD;
						}
					}
				}
			}

			// 結果を加算する ※0 の分を1個マイナスするのを忘れずに
			long ans = dp[S.Length, 0, 0] + dp[S.Length, 0, 1] - 1;
			WriteLine(ans);
		}

