namespace Contest
{

    class Program
    {
        private const long Mod = (long)1e9 + 7;
        private Scanner sc;

        public void Solve()
        {
            sc = new Scanner();
            string K = new string(sc.Next().Reverse().ToArray());
            int length = K.Length;
            int D = sc.NextInt();

            // 10^i-1までの余りjの個数 dp1[i,j]
            var dp1 = new long[length + 1, D];
            // Kの下i桁目まで見た余りjの個数 dp2[i,j]
            var dp2 = new long[length + 1, D];
            dp1[0, 0] = 1;
            dp2[0, 0] = 1;
            for (int i = 0; i < length; i++)
            {
                // n K のi桁目
                int n = K[i] - '0';

                for (int j = 0; j <= 9; j++)
                {
                    if (j < n)
                    {
                        for (int k = 0; k < D; k++)
                        {
                            dp2[i + 1, (j + k) % D] += dp1[i, k];
                            dp2[i + 1, (j + k) % D] %= Mod;
                        }
                    }
                    else if (j == n)
                    {
                        for (int k = 0; k < D; k++)
                        {
                            dp2[i + 1, (j + k) % D] += dp2[i, k];
                            dp2[i + 1, (j + k) % D] %= Mod;
                        }
                    }

                    for (int k = 0; k < D; k++)
                    {
                        dp1[i + 1, (j + k) % D] += dp1[i, k];
                        dp1[i + 1, (j + k) % D] %= Mod;
                    }

                }
            }

            Console.WriteLine((dp2[length, 0] + Mod - 1) % Mod);
        }


        static void Main() => new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
        _stream = new StreamReader(Console.OpenStandardInput());
        _pos = 0;
        _line = new string[0];
        _separator = ' ';
    }
    private readonly char _separator;
    private readonly StreamReader _stream;
    private int _pos;
    private string[] _line;
    #region get a element
    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = _stream.ReadLine().Split(_separator);
            _pos = 0;
        }
        return _line[_pos++];
    }
    public int NextInt()
    {
        return int.Parse(Next());
    }
    public long NextLong()
    {
        return long.Parse(Next());
    }
    public double NextDouble()
    {
        return double.Parse(Next());
    }
    #endregion
    #region convert array
    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }
    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }
    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }
    #endregion
    #region get array
    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = _stream.ReadLine().Split(_separator);
        _pos = _line.Length;
        return _line;
    }
    public int[] IntArray()
    {
        return ToIntArray(Array());
    }
    public long[] LongArray()
    {
        return ToLongArray(Array());
    }
    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }
    #endregion
}

