    class Program
    {
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }

        static readonly long Mod = 1000000000 + 7;
        static void Main(string[] args)
        {
            var K = ReadLine();
            var D = Sarray()[0];
            var sum = new long[D, 2];
            sum[0, 1] = 1;
            var pretk = 0L;
            for (var i = 0; i < K.Length; ++i)
            {
                var aftsum = new long[D, 2];
                var tk = int.Parse(K[i].ToString());
                for (var j = 0; j < D; ++j)
                {
                    for (var k = 0; k < 10; ++k)
                    {
                        var mk = (k + j) % D;
                        aftsum[mk, 0] = (aftsum[mk, 0] + sum[j, 0]) % Mod;
                    }
                    for (var k = 0; k < tk; ++k)
                    {
                        var mk = (k + j) % D;
                        aftsum[mk, 0] = (aftsum[mk, 0] + sum[j, 1]) % Mod;
                    }
                }
                aftsum[(tk + pretk) % D, 1] = sum[pretk % D, 1] % Mod;
                pretk = (tk + pretk) % D;
                sum = aftsum;
            }
            WriteLine((sum[0, 0] + sum[0, 1] - 1) % Mod);//0がDに対応。0オンリーを引いておく
        }
    }
