namespace Solver
{
    class Program
    {
        static void Main()
        {
            int d = sc.Int();
            string s = Console.ReadLine();
            int n = s.Length;
            int M = 1000000007;
            int[,] a = new int[n + 1, d];

            a[0, 0] = 1;

            for (int i = 1; i < n; ++i)
            {
                for (int j = 0; j < 10; ++j)
                    for (int k = 0; k < d; ++k)
                        a[i, (k + j) % d] = (a[i, (k + j) % d] + a[i - 1, k % d]) % M;
            }

            int msum = 0;
            for (int i = 0; i < n; ++i)
            {
                int m = s[i] - '0';
                for (int j = 0; j < m; ++j)
                    for (int k = 0; k < d; ++k)
                        a[n, (k + msum + j) % d] = (a[n, (k + msum + j) % d] + a[n - i - 1, k % d]) % M;

                msum += m;
            }
            ++a[n, (msum - (s[n - 1] - '0')) % d];
            int ans = a[n, 0] - 1;

            while (ans < 0)
                ans += M;

            Console.WriteLine(ans);
        }
    }
    public static class sc
