                            int kk = (k + d) % D;
                            dp[i + 1, jj, kk] += dp[i, j, k];
                            dp[i + 1, jj, kk] %= MOD;
                        }
                    }
                }
            }
            var ans = (dp[K.Length, kSmaller, 0] + dp[K.Length, kUnknown, 0]) % MOD;
