					dp[i+1][(j+x)%D][0] += dp[i][j][0]
					dp[i+1][(j+x)%D][0] %= MOD
				} else if x < d {
					dp[i+1][(j+x)%D][1] += dp[i][j][0]
					dp[i+1][(j+x)%D][1] %= MOD
				}
				dp[i+1][(j+x)%D][1] += dp[i][j][1]
				dp[i+1][(j+x)%D][1] %= MOD
			}
		}
	}
