func getNextLine(scanner *bufio.Reader) string {
	var buffer string
	for {
		line, isPrefix, _ := scanner.ReadLine()
		buffer += string(line)
		if isPrefix == false {
			break
		}
	}
	return buffer
}

func getIntList(scanner *bufio.Reader) []int {
	list := strings.Split(getNextLine(scanner), " ")
	l := len(list)
	result := make([]int, l)
	for i := 0; i < l; i++ {
		result[i], _ = strconv.Atoi(list[i])
	}
	return result
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := bufio.NewReader(fp)

	var k string
	var d int
	fmt.Sscan(getNextLine(scanner), &k)
	fmt.Sscan(getNextLine(scanner), &d)
	lk := len(k)
	dp := make([][][]int64, lk+1)
	for i := 0; i <= lk; i++ {
		dp[i] = make([][]int64, 2)
		for j := 0; j < 2; j++ {
			dp[i][j] = make([]int64, d)
		}
	}

	counts := lk * 2 * d
	dp[0][0][0] = int64(1)
	for i := 0; i <= counts; i++ {
		i1, i2, i3 := indexes(i, lk, 2, d)
		for n := 0; n < 10; n++ {
			if i2 == 1 || n < int(k[i1]-'0') {
				dp[i1+1][1][(i3+n)%d] += dp[i1][i2][i3]
				dp[i1+1][1][(i3+n)%d] %= 1000000007
				continue
			}
			dp[i1+1][0][(i3+n)%d] += dp[i1][i2][i3]
			dp[i1+1][0][(i3+n)%d] %= 1000000007
			break
		}
	}
	fmt.Println((dp[len(k)][0][0] + dp[len(k)][1][0] - int64(1)) % 1000000007)
}

func indexes(i int, a int, b int, c int) (int, int, int) {
	return (i / (b * c)) % a, (i / c) % b, i % c
}

