}

func dfs(i int, j int, k int, K string, D int, dp [][][]int) int {
	if i == len(K) {
		if j == 0 {
			return 1
		}
		return 0
	}

	// 已经计算过
	if dp[i][j][k] > 0 {
		return dp[i][j][k]
	}

    M := 1000000007
	ans := 0
    addAns := func(cnt int) {
        ans += cnt
        if ans >= M {
            ans -= M
        }
    }

	if k == 0 {
		// 前面的值不能保证小于等于K
		// 所以当前的值, 只能取0~Ki
		for jj:=0; jj<int(K[i]-'0'); jj++ {
			// 可以保证小于K
			addAns(dfs(i+1, (j+jj)%D, 1, K, D, dp))
		}
		// 不能保证小于K
		addAns(dfs(i+1, (j+int(K[i]-'0'))%D, 0, K, D, dp))
	} else {
		// 前面的值不能保证小于等于K
		// 所以当前的值, 只能取0~Ki
		for jj:=0; jj<=9; jj++ {
			// 可以保证小于K
			addAns(dfs(i+1, (j+jj)%D, 1, K, D, dp))
		}
	}

	dp[i][j][k] = ans
	return dp[i][j][k]
}

func main() {
	bf := bufio.NewReader(os.Stdin)
	K := readLineStrs(bf)[0]
	D := readLineNums(bf)[0]

	/*
		定义:
			dp[i][j][k]: 第i位, 和模D的值为j, k表示前面的位是否已经小于K, 
						 如果小于, 则当前为可以取值为0~9, 否则当前为只
						 能取值为0~K[i]
		求解见见dfs那里
	*/
	dp := make([][][]int, len(K))
	for i := range dp {
		dp[i] = make([][]int, D)
		for j := range dp[i] {
			dp[i][j] = make([]int, 2)
		}
	}

	fmt.Println(dfs(0, 0, 0, K, D, dp)-1)
}

