var CYCLE = 1000000007

var K string
var D int

func shiftAndAdd(a []int, b []int, s int) {
	for j := 0; j < D; j++ {
		jj := (j + s) % D
		a[jj] = (a[jj] + b[j]) % CYCLE
	}
}

func convolute(a []int, b []int, s int) {
	for i := 0; i <= s; i++ {
		shiftAndAdd(a, b, i)
	}
}

