int LIS(T)(T[] arr) {
    import std.range, std.algorithm;

    auto n = arr.length;
    auto dp = repeat(T.max, n + 1).array.assumeSorted;
    dp[0] = T.min;

    int res;

    foreach (i; 0 .. n) {
        auto j = dp.lowerBound(arr[i]).length;
        dp[j] = arr[i];
        res = max(res, j);
    }

    return res;
