fn main() {
    let n: String = read();
    let d: usize = read();
    let mut dp = vec![vec![vec![0; d]; 2]; n.len() + 1];
    let big_int = 1000_000_000 + 7;
    dp[0][0][0] = 1;  // pos, less, d

    for (i, c) in n.chars().enumerate() {
        for j in 0..2 {
            for m in 0..d {
                let lim = if j == 1 { 9 } else { c.to_digit(10).unwrap() };
                for l in 0..lim + 1 {
                    let idx1 = if j == 1 || l < lim { 1 } else { 0 };
                    let idx2: usize = (m + l as usize) % d;
                    dp[i + 1][idx1][idx2] += dp[i][j][m];
                    dp[i + 1][idx1][idx2] %= big_int;
                }
            }
        }
    }
    // println!("{:?}", dp);

    let mut ans = 0;
    for j in 0..2 {
        ans += dp[n.len()][j][0];
        ans %= big_int;
    }
    println!("{:?}", ans - 1);
}

