pub const M: u64 = 1_000_000_007;

fn main() {
    input! {
        k: chars,
        d: usize
    }
    let k_digits = k.into_iter().map(|c| (c as u8 - b'0') as usize).collect::<Vec<_>>();
    let n = k_digits.len();
    let mut dp = vec_md![0u64;n+1;d;2];
    dp[0][0][0] = 1;
    for i in 0..n {
        for j in 0..d {
            for less in 0..2 {
                for z in 0..(if less == 0 {k_digits[i]+1} else {10}) {
                    dp[i+1][(j + z) % d][less | (z < k_digits[i]) as usize]
                        += dp[i][j][less];
                    dp[i+1][(j + z) % d][less | (z < k_digits[i]) as usize]
                        %= M;
                }
            }
        }
    }
    let mut ret = dp[n][0][0] + dp[n][0][1];
    ret %= M;
    println!("{}", sub_mod(ret, 1, M));
}

#[allow(dead_code)]
fn sub_mod(a: u64, b: u64, m: u64) -> u64 {
    let mut tmp = (a as i64 - b as i64) % m as i64;
    if tmp < 0 {
        tmp += m as i64;
    }
    tmp as u64
}

