fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());
    input!{
        k:chars,
        d:usize,
    }
    let mut a = vec![];
    for c in k {
        let i = c as usize - '0' as usize;
        a.push(i);
    }
    let n = a.len();
    let mut dp = dvec![Mod::new(-1); n+1,2,d];

    for i in 0..2 {
        for j in 0..d {
            dp[1][i][j] = 0.into();
        }
    }
    for i in 0..incl(9) {
        dp[1][0][i%d] += 1;
    }
    for i in 0..incl(a[n-1]) {
        dp[1][1][i%d] += 1;
    }

    struct Rec {
        n: usize,
        d: usize,
        a: Vec<usize>,
        dp: Vec<Vec<Vec<Mod>>>,
    }
    impl Rec {
        fn dp(&mut self, i: usize, b: usize, sum: usize) -> Mod {
            let d = self.d;
            if self.dp[i][b][sum] != Mod::new(-1) {
                return self.dp[i][b][sum]
            }
            let digit = self.a[self.n-i];
            if b == 1 {
                let mut tot = 0.into();
                // keep b
                tot += self.dp(i-1, 1, (d+sum-digit%d)%d);
                // b -> false
                for choice in 0..digit {
                    tot += self.dp(i-1, 0, (d+sum-choice%d)%d);
                }
                self.dp[i][b][sum] = tot;
            } else {
                let mut tot = 0.into();
                for choice in 0..incl(9) {
                    tot += self.dp(i-1, 0, (d+sum-choice%d)%d)
                }
                self.dp[i][b][sum] = tot;
            }
            self.dp[i][b][sum]
        }
    }
    let mut rec = Rec {
        n: n,
        d: d,
        a: a,
        dp: dp,
    };
    let ans = rec.dp(n,1,0) - 1;
    writeln!(out,"{}",ans);
}
pub mod modular {
    const M: i64 = 1_000_000_007;
    #[derive(Debug, Clone, Copy, Default, PartialOrd, Ord, PartialEq, Eq)]
    pub struct Mod(pub i64);
    impl ::std::fmt::Display for Mod {
        fn fmt(&self, f: &mut ::std::fmt::Formatter) -> ::std::fmt::Result {
            write!(f, "{}", self.0)
        }
    }
    impl Mod {
        pub fn new(v: i64) -> Mod {
            Mod((v + M) % M)
        }
        pub fn pow(self, mut r: i64) -> Mod {
            let mut k = self;
            let mut ret = 1.into();
            while r > 0 {
                if r % 2 != 0 {
                    ret = ret * k;
                }
                r /= 2;
                k = k * k;
            }
            ret
        }
        pub fn recip(self) -> Mod {
            self.pow(M - 2)
        }
    }
    use std::ops::*;
    impl<T: Into<Mod>> Add<T> for Mod {
        type Output = Mod;
        fn add(self, rhs: T) -> Self::Output {
            Mod::new(self.0 + rhs.into().0)
        }
    }
    impl<T: Into<Mod>> AddAssign<T> for Mod {
        fn add_assign(&mut self, rhs: T) {
            *self = *self + rhs;
        }
    }
    impl<T: Into<Mod>> Sub<T> for Mod {
        type Output = Mod;
        fn sub(self, rhs: T) -> Self::Output {
            Mod::new(self.0 - rhs.into().0 + M)
        }
    }
    impl<T: Into<Mod>> SubAssign<T> for Mod {
        fn sub_assign(&mut self, rhs: T) {
            *self = *self - rhs;
        }
    }
    impl<T: Into<Mod>> Mul<T> for Mod {
        type Output = Mod;
        fn mul(self, rhs: T) -> Self::Output {
            Mod::new(self.0 * rhs.into().0)
        }
    }
    impl<T: Into<Mod>> MulAssign<T> for Mod {
        fn mul_assign(&mut self, rhs: T) {
            *self = *self * rhs;
        }
    }
    impl<T: Into<Mod>> Div<T> for Mod {
        type Output = Mod;
        fn div(self, rhs: T) -> Self::Output {
            self * rhs.into().recip()
        }
    }
    impl<T: Into<Mod>> DivAssign<T> for Mod {
        fn div_assign(&mut self, rhs: T) {
            *self = *self / rhs;
        }
    }
    impl Neg for Mod {
        type Output = Mod;
        fn neg(self) -> Self::Output {
            Mod(0) - self
        }
    }
    impl<T: ::std::convert::Into<i64>> ::std::convert::From<T> for Mod {
        fn from(v: T) -> Self {
            Mod::new(v.into())
        }
    }
}
