/*
dp[i][j][k] = { j = 0 ならば，先頭からi桁がK未満で，あまりがjとなる数の総数
            　　 j = 1 ならば，先頭からi桁がKと等しくで，あまりがjとなる数の総数 
              }
dp[0][1][0] = 1 //未満ではない，K[-1] = 0と考える．
dp[i+1][0][k] = for l = 0..10 { dp[i][0][ (k-l) mod D] } + for l = 0..K[i] { dp[i][1][(k - l) mod D] }
dp[i+1][1][k] = dp[i][1][(k - K[i]) mod D]
*/
const MOD: usize = 1_000_000_000 + 7;
fn main() {
    let K: Vec<usize> = read::<String>().chars().map(|e| e as usize - '0' as usize).collect();
    let D: usize = read();
    let n = K.len();
    let mut dp = vec![vec![vec![0; D]; 2]; n+1];

    // 
    dp[0][1][0] = 1;

    for i in 0..n {   
        for k in 0..D {
            for l in 0..10 {
                // 未満の場合の更新式
                dp[i+1][0][(k + l) % D] += dp[i][0][k];
                dp[i+1][0][(k + l) % D] %= MOD;

                if l < K[i] {
                    dp[i+1][0][(k + l) % D] += dp[i][1][k];
                    dp[i+1][0][k] %= MOD;
                }
            }
            // 一致している場合の更新式
            dp[i+1][1][(k + K[i]) % D] += dp[i][1][k];
            dp[i+1][1][(k + K[i]) % D] %= MOD;
        }
    }

    // for i in 0..n+1 {
    //     println!("{:?}", dp[i][0]);
    //     println!("{:?}", dp[i][1]);
    // }

    let ans: usize = (dp[n][0][0] % MOD + dp[n][1][0] % MOD) % MOD;
    println!("{}", ans-1); // 0000...0000の場合を除く
}

