fn run() {
    input! {
        s: chars,
        d: usize,
    }
    const MOD: u64 = 1000000007;
    let mut dp = vec![0; d];
    let mut sup = 0;
    for c in s {
        let mut next = vec![0; d];
        for i in 0..d {
            for j in 0..10 {
                next[(i + j) % d] += dp[i];
            }
        }
        let k = c.to_digit(10).unwrap()as usize;
        for i in 0..k {
            next[(sup + i) % d] += 1;
        }
        sup = (sup + k) % d;
        for i in 0..d {
            dp[i] = next[i] % MOD;
        }
    }
    let ans = (dp[0] + if sup == 0 {1} else {0} + MOD - 1) % MOD;
    println!("{}", ans);
}

