fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());
    input!{
        k:chars,
        d:usize,
    }
    let mut a = vec![];
    for c in k {
        let i = c as usize - '0' as usize;
        a.push(i);
    }
    let n = a.len();
    let mut dp = dvec![Mod::new(-1); n+1,2,d];

    for i in 0..2 {
        for j in 0..d {
            dp[1][i][j] = 0.into();
        }
    }
    for i in 0..=9 {
        dp[1][0][i%d] += 1;
    }
    for i in 0..=a[n-1] {
        dp[1][1][i%d] += 1;
    }

    struct Rec {
        n: usize,
        d: usize,
        a: Vec<usize>,
        dp: Vec<Vec<Vec<Mod>>>,
    }
    impl Rec {
        fn dp(&mut self, i: usize, b: usize, sum: usize) -> Mod {
            if self.dp[i][b][sum] != Mod::new(-1) {
                return self.dp[i][b][sum]
            }
            let digit = self.a[self.n-i];
            if b == 1 {
                let mut tot = 0.into();
                // keep b
                tot += self.dp(i-1, 1, (self.d+sum-digit%self.d)%self.d);
                // b -> false
                for choice in 0..digit {
                    tot += self.dp(i-1, 0, (self.d+sum-choice%self.d)%self.d);
                }
                self.dp[i][b][sum] = tot;
            } else {
                let mut tot = 0.into();
                for choice in 0..=9 {
                    tot += self.dp(i-1, 0, (self.d+sum-choice%self.d)%self.d)
                }
                self.dp[i][b][sum] = tot;
            }
            self.dp[i][b][sum]
        }
    }
    let mut rec = Rec {
        n: n,
        d: d,
        a: a,
        dp: dp,
    };
    let ans = rec.dp(n,1,0) - 1;
    writeln!(out,"{}",ans);
}
