        d: usize,
    }
    let k: Vec<_> = k.into_iter().map(|c| c as u8 as usize - 48).collect();
    let n = k.len();
    let mut dp = vec![vec![[ModInt::new(0); 2]; d]; n + 1];
    dp[0][0][1] = ModInt::new(1);
    for i in 0 .. n {
        for j in 0 .. d {
            dp[i + 1][(j + k[i]) % d][1] += dp[i][j][1];
            for u in 0 .. k[i] {
                dp[i + 1][(j + u) % d][0] += dp[i][j][1];
            }
            for u in 0 .. 10 {
                dp[i + 1][(j + u) % d][0] += dp[i][j][0];
            }
        }
    }
    puts!("{}\n", dp[n][0][0] + dp[n][0][1] - ModInt::new(1));
}

