const P: i64 = 1_000_000_007;

fn main() {
    let K = rl().chars().map(|c| c as u8 - b'0').collect::<Vec<u8>>();
    let D = read!(usize);

    let N = K.len();

    // dp[i][s][less] = x
    // 上位 i 桁が確定済み
    // 確定済みの桁の総和が s (mod D)
    // less = 1 <=> K 未満であることが確定済み
    // 数字の個数が x (mod P)
    let mut dp = vec![vec![vec![0, 0]; D]; N + 1];

    dp[0][0][0] = 1;

    for i in 0..N {
        for s in 0..D {
            for d in 0..10 {
                let less = K[i] > d as u8;
                let eq = K[i] == d as u8;

                dp[i + 1][(s + d) % D][1] += dp[i][s][1];
                dp[i + 1][(s + d) % D][1] %= P;

                if less {
                    dp[i + 1][(s + d) % D][1] += dp[i][s][0];
                    dp[i + 1][(s + d) % D][1] %= P;
                }
                if eq {
                    dp[i + 1][(s + d) % D][0] += dp[i][s][0];
                    dp[i + 1][(s + d) % D][0] %= P;
                }
            }
        }

        // debug!(dp[i + 1]);
    }

    let mut x = dp[N][0][0];
    x += dp[N][0][1];
    x %= P;

    // 0 を数えてしまっているので引く
    x += P - 1;
    x %= P;

    println!("{}", x)
}

