    let n = k.len();
    let mut dp = vec![vec![vec![ModInt::new(0); 2]; d]; n+1];
    dp[0][0][0] = ModInt::new(1);
    for i in 0..n {
        for j in 0..d {
            for l in 0..10 {
                let dst = (j+l)%d;
                dp[i+1][dst][1] += dp[i][j][1];
            }
            for l in 0..k[i] {
                let dst = (j+l)%d;
                dp[i+1][dst][1] += dp[i][j][0];
            }
            dp[i+1][(j+k[i])%d][0] += dp[i][j][0];
        }
    }
    println!("{}", dp[n][0][1] + dp[n][0][0] - ModInt::new(1));
}

