const MOD: usize = 1000000007;

fn main() {
   input! {
      _k: String,
      d: usize,
   }

   let k: Vec<usize> = _k.as_bytes().iter().map(|&b| (b - b'0') as usize).collect();
   let n = k.len();

   let mut dp = vec![vec![vec![0; 2]; d]; n];
   for i in 0..k[0] {
      dp[0][i % d][0] += 1;
   }
   dp[0][k[0] % d][1] = 1;
   for i in 1..n {
      for j in 0..d {
         for l in 0..10 {
            dp[i][(j + l) % d][0] += dp[i - 1][j % d][0];
