            }
            dp[i][(j + l) % d][0] %= MOD;
            dp[i][(j + l) % d][1] %= MOD;
         }
      }
   }
   let mut ans = dp[n - 1][0][0] + dp[n - 1][0][1] + MOD - 1;
   ans %= MOD;
   println!("{}", ans);
}

