}

fn rec(
    pos: usize,
    sum: usize,
    any: usize,
    k: &[char],
    d: usize,
    tbl: &mut Vec<Vec<Vec<Option<Mod>>>>,
) -> Mod {
    if pos == k.len() {
        return if sum % d == 0 { 1 } else { 0 }.into();
    }

    if let Some(ret) = tbl[any][sum][pos] {
        return ret.clone();
    }

    let last = (k[pos] as u8 - b'0') as usize;
    let mut ret = Mod::new(0);
    for i in 0..if any == 1 { 9 + 1 } else { last + 1 } {
        ret += rec(
            pos + 1,
            (sum + i) % d,
            if any == 1 {
                1
            } else {
                if i != last {
                    1
                } else {
                    0
                }
            },
            k,
            d,
            tbl,
        );
    }

    tbl[any][sum][pos] = Some(ret);
    ret
}

