    }

    let mut dp = vec_md![0u64;k.len()+1;d;2];
    dp[0][0][0] = 1;
    for i in 0..k.len() {
        for z in 0..d {
            for less in 0..2 {
                let ki_digit = (k[i] as u8 - b'0') as usize;
                for j in if less == 1 {0..10} else {0..ki_digit+1} {
                    dp[i+1][(z + j) % d][less | (j < ki_digit) as usize]
                        += dp[i][z][less];
                    dp[i+1][(z + j) % d][less | (j < ki_digit) as usize] %= M;
                }
            }
        }
    }
    println!("{}", (dp[k.len()][0][0] + dp[k.len()][0][1] - 1) % M);
}

