const MOD: usize = 1000000007;

fn main() {
   input! {
      _k: String,
      d: usize,
   }

   let k: Vec<usize> = _k.as_bytes().iter().map(|&b| (b - b'0') as usize).collect();
   let n = k.len();

   let mut dp = vec![vec![0; d]; n];
   let mut s = k[0];
   for i in 0..k[0] {
      dp[0][i % d] = 1;
   }
   for i in 1..n {
      for j in 0..10 {
         for l in 0..d {
            dp[i][(l + j) % d] += dp[i - 1][l % d];
            dp[i][(l + j) % d] %= MOD;
         }
      }
      for j in s..s + k[i] {
         dp[i][j % d] += 1;
      }
      s += k[i];
      s %= d;
   }
   dp[n - 1][s % d] += 1;

   dp[n - 1][0] += MOD - 1;
   dp[n - 1][0] %= MOD;

   println!("{}", dp[n - 1][0]);
}

