fn solve() {
    input!{
        K:chars,
        D:usize,
    }

    let mut k = vec![];
    for c in K {
        let mut cc = String::new();
        cc.push(c);
        let x: usize = cc.parse().unwrap();
        k.push(x);
    }
    // L連続の9
    // nines[L][mod D]
    let mut nines = dvec![0; k.len()+1,D];
    for j in 0..10 {
        nines[1][j%D] += 1;
    }
    for i in 1..k.len() { // 10000
        for j in 0..10 { // 10
            for d in 0..D { // 100
                nines[i+1][(d+j)%D] += nines[i][d];
                nines[i+1][(d+j)%D] %= mo;
            }
        }
    }

    let n = k.len();
    let mut cum = CumSum1::build(&k);

    let mut sum = 0;
    for i in 0..n-1 {
        let x = k[i];
        let premod = cum.query(0,i);
        // K=3223の場合
        // 0000-2999
        // 3000-3199
        // 3200-3219
        for m in 0..x {
            let headsum = (premod+m)%D;
            sum += nines[n-(i+1)][(D-headsum)%D];
            sum %= mo;
        }
    }
    // 最後の桁
    let premod = cum.query(0,n-1)%D;
    for x in 0..k[n-1]+1 {
        if (premod+x)%D==0 {
            sum+=1;
            sum%=mo;
        }
    }
    // 000000は抜く
    println!("{}",(mo+sum-1)%mo);
}
struct CumSum1 {
    dp: Vec<usize>,
}
impl CumSum1 {
    fn build(base: &[usize]) -> CumSum1 {
        let n = base.len();
        let mut dp = vec![0; n + 1];
        let mut acc = 0;
        for i in 0..n {
            acc += base[i];
            dp[i + 1] = acc;
        }
        CumSum1 { dp: dp }
    }
    fn query(&self, i: usize, j: usize) -> usize {
        self.dp[j] - self.dp[i]
    }
}
