    }
    for i in 1..k.len() { // 10000
        for j in 0..10 { // 10
            for d in 0..D { // 100
                nines[i+1][(d+j)%D] += nines[i][d];
                nines[i+1][(d+j)%D] %= mo;
            }
        }
    }

    let n = k.len();
    let mut cum = CumSum1::build(&k);

    let mut sum = 0;
    for i in 0..n-1 {
        let x = k[i];
        let rest = n-(i+1);
        let premod = cum.query(0,i) % D;
        // K=3223の場合
        // 0000-2999
        // 3000-3199
        // 3200-3219
        for m in 0..x {
            let headsum = (D+premod+m)%D;
            sum += nines[rest][(D-headsum)%D];
            sum %= mo;
        }
    }
    // 最後の桁
    let curmod = cum.query(0,n-1)%D;
    for x in 0..k[n-1]+1 {
        if (curmod+x)%D==0 {
            sum+=1;
            sum%=mo;
        }
    }
