    println!("{}",sum-1);
}
struct CumSum1 {
    dp: Vec<usize>,
}
impl CumSum1 {
    fn build(base: &[usize]) -> CumSum1 {
        let n = base.len();
        let mut dp = vec![0; n + 1];
        let mut acc = 0;
        for i in 0..n {
            acc += base[i];
            dp[i + 1] = acc;
        }
        CumSum1 { dp: dp }
    }
    fn query(&self, i: usize, j: usize) -> usize {
        self.dp[j] - self.dp[i]
    }
}
