    input.clear();
    io::stdin().read_line(&mut input);
    let d = input.trim().parse::<usize>().unwrap();
    input.clear();

    let ks: Vec<char> = k.chars().collect();
    // 0 is not max, 1 is max.
    let mut dp = vec![vec![vec![-1; ks.len()]; d as usize]; 2];
    let result = solve(&mut dp, 0, 0, true, d, &ks);
    // delete all 0
    println!("{}", result - 1);
