fn solve(
    dp: &mut Vec<Vec<Vec<i64>>>,
    index: usize,
    remain: usize,
    is_max: bool,
    d: usize,
    k: &[char],
) -> i64 {
    if index == k.len() {
        if remain == 0 {
            return 1;
        } else {
            return 0;
        }
    }
    let first_index = if is_max { 1 } else { 0 };
    if dp[first_index][remain][index] != -1 {
        return dp[first_index][remain][index];
    }

    if is_max {
        let mut result = 0;
        let number = k[index].to_digit(10).unwrap() as usize;
        for i in 0..number {
            let new_remain = (remain + i) % d;
            result += solve(dp, index + 1, new_remain, false, d, k);
            result %= 1_000_000_007;
        }
        let new_remain = (remain + number) % d;
        result += solve(dp, index + 1, new_remain, true, d, k);
        result %= 1_000_000_007;
        dp[1][remain][index] = result;
        return result;
    }

    let mut result = 0;
    for i in 0..10 {
        let new_remain = (remain + i) % d;
        result += solve(dp, index + 1, new_remain, false, d, k);
        result %= 1_000_000_007;
    }
    dp[0][remain][index] = result;
    result
}

