fn main(){
    input!{
        k:chars,
        d:usize,
    }
    let mut dp = vec![vec![vec![-1;d];10001];2];

    fn dfs(k:usize, tight:bool, now:usize, dp:&mut Vec<Vec<Vec<i64>>>, ks:&Vec<char>, d:usize)->i64{
        if dp[tight as usize][k][now] != -1{
            return dp[tight as usize][k][now];
        }
        if k == ks.len() {
            if now == 0{
                return 1;
            }
            else{
                return 0;
            }
        }

        let mut nxt = (ks[k] as u32 - '0' as u32) as i64;
        if tight == false{
            nxt = 9;
        }
        let mut res = 0;
        for i in 0..nxt+1{
            if tight && (i == nxt){
                res += dfs(k+1, true, (now + i as usize)%d, dp, ks, d);
                res %= MOD;
            }
            else{
                res += dfs(k+1, false,  (now + i as usize)%d, dp, ks, d);
                res %= MOD;
            }
        }
        dp[tight as usize][k][now] = res;
        return res;

    }
    println!("{}", (dfs(0, true, 0, &mut dp, &k, d)+MOD-1)%MOD);
}

