use std::vec::Vec;

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().split_whitespace()
        .map(|e| e.parse().ok().unwrap()).collect()
}


/*
dp[i][j][k] = { j = 0 ならば，先頭からi桁がK未満で，あまりがjとなる数の総数
            　　 j = 1 ならば，先頭からi桁がKと等しくで，あまりがjとなる数の総数 
              }
dp[0][1][0] = 1 //未満ではない，K[-1] = 0と考える．
dp[i+1][0][k] = for l = 0..10 { dp[i][0][ (k-l) mod D] } + for l = 0..K[i] { dp[i][1][(k - l) mod D] }
dp[i+1][1][k] = dp[i][1][(k - K[i]) mod D]
*/
const MOD: usize = 1_000_000_000 + 7;
fn main() {
    let K: Vec<usize> = read::<String>().chars().map(|e| e as usize - '0' as usize).collect();
    let D: usize = read();
    let n = K.len();
    let mut dp = vec![vec![vec![0; D]; 2]; n+1];

    // 
    dp[0][1][0] = 1;

    for i in 0..n {   
        for k in 0..D {
            for l in 0..10 {
                // 未満の場合の更新式
                dp[i+1][0][k] += dp[i][0][(k + 10 * D - l) % D];
                dp[i+1][0][k] %= MOD;

                if l < K[i] {
                    dp[i+1][0][k] += dp[i][1][(k + 10 * D - l) % D];
                    dp[i+1][0][k] %= MOD;
                }
            }
            // 一致している場合の更新式
            dp[i+1][1][k] += dp[i][1][(k + 10 * D - K[i]) % D];
            dp[i+1][1][k] %= MOD;
        }
    }

    let ans = (dp[n][0][0] % MOD + dp[n][1][0] % MOD) % MOD;
    println!("{}", ans-1); // 0000...0000の場合を除く
}

#![allow(non_snake_case)]

use std::io::{stdin, Read, StdinLock};
use std::str::FromStr;

fn main() {
    let cin = stdin();
    let mut scan = Scanner::new(cin.lock());

    let K = scan.chars();
    let D = scan.read::<usize>();
    let n = K.len();
    let mut dp = vec3(n+1, 2, D, Co(0));
    dp[0][0][0] = Co(1);

    for i in 0..n {
        for less in 0..2 {
            let c = K[i] as usize - '0' as usize;
            for d in 0..(if less==1 {10} else {c+1}) {
                for e in 0..D {
                    dp[i+1][less | (d < c) as usize][(d + e) % D] += dp[i][less][e];
                }
            }
        }
    }
    println!("{}", dp[n][0][0] + dp[n][1][0] - Co(1));
}

#[allow(dead_code)]
fn vec2<T: Clone>(a: usize, b: usize, init: T) -> Vec<Vec<T>> {
    vec![vec![init;b];a]
}

#[allow(dead_code)]
fn vec3<T: Clone>(a: usize, b: usize, c: usize, init: T) -> Vec<Vec<Vec<T>>> {
    vec![vec![vec![init;c];b];a]
}

