/*
dp[i][j][k] = { j = 0 ならば，先頭からi桁がK未満で，あまりがjとなる数の総数
            　　 j = 1 ならば，先頭からi桁がKと等しくで，あまりがjとなる数の総数 
              }
dp[0][1][0] = 1 //未満ではない，K[-1] = 0と考える．
dp[i+1][0][k] = for l = 0..10 { dp[i][0][ (k-l) mod D] } + for l = 0..K[i] { dp[i][1][(k - l) mod D] }
dp[i+1][1][k] = dp[i][1][(k - K[i]) mod D]
*/
const MOD: usize = 1_000_000_000 + 7;
fn main() {
    let K: Vec<usize> = read::<String>().chars().map(|e| e as usize - '0' as usize).collect();
    let D: usize = read();
    let n = K.len();
    let mut dp = vec![vec![vec![0; D]; 2]; n+1];

    // 
    dp[0][1][0] = 1;

    for i in 0..n {   
        for k in 0..D {
            for l in 0..10 {
                // 未満の場合の更新式
                dp[i+1][0][k] += dp[i][0][(k + 10 * D - l) % D];
                dp[i+1][0][k] %= MOD;

                if l < K[i] {
                    dp[i+1][0][k] += dp[i][1][(k + 10 * D - l) % D];
                    dp[i+1][0][k] %= MOD;
                }
            }
            // 一致している場合の更新式
            dp[i+1][1][k] += dp[i][1][(k + 10 * D - K[i]) % D];
            dp[i+1][1][k] %= MOD;
        }
    }

    let ans = (dp[n][0][0] + dp[n][1][0]) % MOD;
    println!("{}", ans-1); // 0000...0000の場合を除く
}

use std::error::Error;
use std::io;

pub fn main() {
    if let Err(_e) = run() {
        panic!("failed.");
    }
}

fn run() -> Result<(), Box<Error>> {
    let mut input = String::new();
    io::stdin().read_line(&mut input);
    let k = input.trim().to_owned();
    input.clear();
    io::stdin().read_line(&mut input);
    let d = input.trim().parse::<usize>().unwrap();
    input.clear();

    let ks: Vec<char> = k.chars().collect();
    // 0 is not max, 1 is max.
    let mut dp = vec![vec![vec![-1; ks.len()]; d as usize]; 2];
    let mut result = solve(&mut dp, 0, 0, true, d, &ks);
    // delete all 0
    result = result + 1_000_000_007;
    result -= 1;
    result %= 1_000_000_007;
    println!("{}", result);
    Ok(())
}

fn solve(
    dp: &mut Vec<Vec<Vec<i64>>>,
    index: usize,
    remain: usize,
    is_max: bool,
    d: usize,
    k: &[char],
) -> i64 {
    if index == k.len() {
        if remain == 0 {
            return 1;
        } else {
            return 0;
        }
    }
    let first_index = if is_max { 1 } else { 0 };
    if dp[first_index][remain][index] != -1 {
        return dp[first_index][remain][index];
    }

    if is_max {
        let mut result = 0;
        let number = k[index].to_digit(10).unwrap() as usize;
        for i in 0..number {
            let new_remain = (remain + i) % d;
            result += solve(dp, index + 1, new_remain, false, d, k);
            result %= 1_000_000_007;
        }
        let new_remain = (remain + number) % d;
        result += solve(dp, index + 1, new_remain, true, d, k);
        result %= 1_000_000_007;
        dp[1][remain][index] = result;
        return result;
    }

    let mut result = 0;
    for i in 0..10 {
        let new_remain = (remain + i) % d;
        result += solve(dp, index + 1, new_remain, false, d, k);
        result %= 1_000_000_007;
    }
    dp[0][remain][index] = result;
    result
}

