struct Input {
    stdin: io::Stdin,
    buf: VecDeque<String>
}

impl Input {
    fn new() -> Input {
        Input { 
            stdin: io::stdin(),
            buf: VecDeque::new()
        }
    }

    fn read<T: FromStr>(&mut self) -> T 
    where <T as FromStr>::Err: fmt::Debug {
        self.next().unwrap().parse::<T>().unwrap()
    }

    fn read_2<T: FromStr, U: FromStr>(&mut self) -> (T, U)
    where <T as FromStr>::Err: fmt::Debug,
          <U as FromStr>::Err: fmt::Debug {
        (self.read(), self.read())
    }

    fn read_3<T: FromStr, U: FromStr, V: FromStr>(&mut self) -> (T, U, V)
    where <T as FromStr>::Err: fmt::Debug,
          <U as FromStr>::Err: fmt::Debug,
          <V as FromStr>::Err: fmt::Debug {
        (self.read(), self.read(), self.read())
    }

    fn read_bytes(&mut self) -> Vec<u8> {
        self.next().unwrap().into_bytes()
    }

    fn read_n<T: FromStr>(&mut self, n: usize) -> Vec<T>
    where <T as FromStr>::Err: fmt::Debug {
        let mut v = Vec::new();
        for _ in 0..n { v.push(self.read::<T>()); }
        v
    }
}

impl Iterator for Input {
    type Item = String;
    fn next(&mut self) -> Option<String> {
        while self.buf.is_empty() {
            let mut s = String::new();
            let _res = self.stdin.read_line(&mut s);
            self.buf.extend(s.split_whitespace().map(|s| s.to_owned()));
        }
        self.buf.pop_front()
    }
}

fn run() {
    let mut ip = Input::new();
    const MOD: i64 = 1000000007;
    let k = ip.read_bytes();
    let n = k.len();
    let d: usize = ip.read();
    let mut dp = vec![vec![[0; 2]; d + 1]; n + 1];
    dp[0][0][1] = 1;
    for i in 1..n + 1 {
        let y = (k[i - 1] - b'0') as usize;
        for j in 0..d {
            for x in 0..10 {
                if x <= y {
                    let k = if x == y { 1 } else { 0 };
                    dp[i][j][k] = (dp[i][j][k] + dp[i - 1][(j + x) % d][1]) % MOD;
                }
                dp[i][j][0] = (dp[i][j][0] + dp[i - 1][(j + x) % d][0]) % MOD;
            } 
        }
    }
    println!("{}", dp[n][0][0] + dp[n][0][1] - 1);
}

