const M: usize = 1_000_000_007;

fn main() {
    input! {
        k: chars,
        d: usize,
    }
    let mut dp = vec![vec![vec![0; 2]; 100]; k.len() + 1];
    dp[0][0][0] = 1;

    for pos in 0..k.len() {
        for m in 0..d {
            for is_less in 0..2 {
                for nd in 0..10 {
                    let nm = (m + nd) % d;
                    let digit = k[pos] as usize - '0' as usize;
                    if nd > digit && is_less == 0 {
                        continue;
                    }
                    if nd < digit {
                        dp[pos + 1][nm][1] += dp[pos][m][is_less];
                        dp[pos + 1][nm][1] %= M;
                    } else {
                        dp[pos + 1][nm][is_less] += dp[pos][m][is_less];
                        dp[pos + 1][nm][is_less] %= M;
                    }
                }
            }
        }
    }
    println!("{}", dp[k.len()][0].iter().sum::<usize>() - 1);
}

use std::io;
use std::error::Error;

pub fn main(){
    if let Err(_e) = run(){
        panic!("failed.");
    }
}

fn run() -> Result<(), Box<Error>>{
    let mut input = String::new();
    io::stdin().read_line(&mut input);
    let k = input.trim().to_owned(); 
    input.clear();
    io::stdin().read_line(&mut input);
    let d = input.trim().parse::<usize>().unwrap();
    input.clear(); 
    let mut dp = vec![vec![-1;k.len()+1]; d as usize];
    let mut ks:Vec<char>= k.chars().collect();
    ks.insert(0, '0');
    let result = solve(&mut dp, 0, 0, true, d,  &ks);
    // delete all 0
    println!("{}", result-1);
    Ok(())
}

fn solve(dp: &mut Vec<Vec<i64>>, index: usize, remain: usize, is_max:bool, d:usize,  k:&[char]) -> i64{
    if index == k.len()  {
        if remain == 0{
            return 1;
        } else {
            return 0;
        }
    }

    if !is_max && dp[remain][index] != -1{
        return dp[remain][index];
    }

    let mut result = 0;
    if is_max {
        let number = k[index].to_digit(10).unwrap() as usize; 
        for i in 0..number {
            let new_remain = (remain + i ) % d;
            result += solve(dp, index + 1, new_remain, false, d, k);
            result %= 1_000_000_007;
        }
        let new_remain = (remain + number ) % d;
        result += solve(dp, index + 1, new_remain, true, d, k);
        result %= 1_000_000_007;
    } else {
        for i in 0..10 {
            let new_remain = (remain + i ) % d;
            result += solve(dp, index + 1, new_remain, is_max, d, k);
            result %= 1_000_000_007;
        }
    }
    dp[remain][index] = result;

    result
}

