    let n = k_digits.len();
    let mut dp = vec_md![Co(0);n+1;d;2];
    dp[0][0][0] = Co(1);
    for i in 0..n {
        for j in 0..d {
            for less in 0..2 {
                for z in 0..(if less == 0 {k_digits[i]+1} else {10}) {
                    let tmp = dp[i][j][less];
                    dp[i+1][(j + z) % d][less | (z < k_digits[i]) as usize]
                        += tmp;
                }
            }
        }
    }
    let ret = dp[n][0][0] + dp[n][0][1];
    println!("{}", ret - Co(1));
